// Species descriptions: intro extracts from English Wikipedia (CC BY-SA, attributed in UI),
// keyed by eBird species code. IUCN status via Wikidata (P141). Build-time snapshot.
export interface KaDetail {
  extract: string;
  iucn: "" | "LC" | "NT" | "VU" | "EN" | "CR";
}

export const KA_DETAILS: Record<string, KaDetail> = {
  "fuwduc": { extract: "The fulvous whistling duck or fulvous tree duck (Dendrocygna bicolor) is a species of whistling duck that breeds across the world's tropical regions in much of Mexico and South America, the West Indies, the southern United States, sub-Saharan Africa and the Indian subcontinent. It has plumage that is mainly reddish brown, long legs and a long grey bill, and shows a distinctive white band across its black tail in flight. Like other members of its ancient lineage, it has a whistling call which is given in flight or on the ground. Its preferred habitat consists of wetlands with plentiful vegetation, including shallow lakes and paddy fields. The nest, built from plant material and unlined, is placed among dense vegetation or in a tree hole. The typical clutch is around ten whitish eggs. The breeding adults, which pair for life, take turns to incubate, and the eggs hatch in 24–29 days.", iucn: "LC" },
  "lewduc1": { extract: "The lesser whistling duck (Dendrocygna javanica), also known as Indian whistling duck or lesser whistling teal, is a species of whistling duck that breeds in the Indian subcontinent and Southeast Asia. They are nocturnal feeders that during the day may be found in flocks around lakes and wet paddy fields. They can perch on trees and sometimes build their nest in the hollow of a tree. This brown and long-necked duck has broad wings that are visible in flight and produces a loud two-note wheezy call. It has a chestnut rump, differentiating it from its larger relative, the fulvous whistling duck, which has a creamy white rump.", iucn: "LC" },
  "bahgoo": { extract: "The bar-headed goose (Anser indicus) is a goose that breeds in Central Asia in colonies of thousands near mountain lakes and winters in South Asia, as far south as peninsular India. It lays three to eight eggs at a time in a ground nest. It is known for the extreme altitudes it reaches when migrating across the Himalayas.", iucn: "LC" },
  "gragoo": { extract: "The greylag goose (Anser anser) is a species of large goose in the waterfowl family Anatidae and the type species of the genus Anser. It has mottled and barred grey and white plumage and an orange beak and pink legs. A large bird, it measures between 74 and 91 centimetres (29 and 36 in) in length, with an average weight of 3.3 kilograms (7 lb 4 oz). Its distribution is widespread, with birds from the north of its range in Europe and Asia often migrating southwards to spend the winter in warmer places, although many populations are resident, even in the north. It is the ancestor of most breeds of domestic goose, having been domesticated at least as early as 1360 BCE. The genus name and specific epithet are from anser, the Latin for \"goose\". In the USA, its name has been spelled \"graylag\".", iucn: "LC" },
  "gwfgoo": { extract: "The greater white-fronted goose (Anser albifrons) is a species of goose, closely related to the smaller lesser white-fronted goose (A. erythropus). The greater white-fronted goose is migratory, breeding in northern Canada, Alaska, Greenland, and Russia, and winters farther south in North America, Europe, and Asia. It is named for the patch of white feathers bordering the base of its bill; its specific name albifrons comes from the Latin albus \"white\" and frons \"forehead\". In the United Kingdom and Ireland, it has been known as the white-fronted goose; in North America, it is known as the greater white-fronted goose (or \"greater whitefront\"), and this name is also increasingly adopted internationally. Even more distinctive are the salt-and-pepper markings on the breast of adult birds, which is why the goose is colloquially called the \"specklebelly\" in North America.", iucn: "LC" },
  "lwfgoo": { extract: "The lesser white-fronted goose (Anser erythropus) is a goose closely related to the larger greater white-fronted goose (A. albifrons). It breeds in the northernmost Palearctic, but it is a scarce breeder in Europe, with a reintroduction attempt in Fennoscandia.", iucn: "VU" },
  "comduc2": { extract: "The knob-billed duck (Sarkidiornis melanotos) or African comb duck is a type of duck found along the tropical/sub-tropical wetlands and waterways of Sub-Saharan Africa and the island of Madagascar, as well as most of South Asia and mainland Indochina. Most taxonomic authorities classify the knob-billed duck and the comb duck separately. A misidentified species of extinct Mauritian comb duck was initially described from unrecognised remains of the Mauritius sheldgoose (Alopochen mauritiana); this was realised as early as 1897, but the printed case of mistaken identity can still, occasionally, be found in modern-day sources.", iucn: "LC" },
  "rudshe": { extract: "The ruddy shelduck (Tadorna ferruginea) is a bird species in the family Anatidae. It is a distinctive waterfowl, 58 to 70 cm (23 to 28 in) in length with a wingspan of 110 to 135 cm (43 to 53 in). It has orange-brown body plumage with a paler head, while the tail and the flight feathers in the wings are black, contrasting with the white wing-coverts. It is a migratory bird, wintering in the Indian subcontinent and breeding in southeastern Europe and central Asia, though there are small resident populations in North Africa. It has a loud honking call. The ruddy shelduck mostly inhabits inland water-bodies such as lakes, reservoirs and rivers. The male and female form a lasting pair bond and the nest may be well away from water, in a crevice or hole in a cliff, tree or similar site. A clutch of about eight eggs is laid and is incubated solely by the female for about four weeks.", iucn: "LC" },
  "musduc": { extract: "The Muscovy duck (Cairina moschata) is a species of duck native to the Americas, from the Lower Rio Grande Valley of Texas and Mexico south to Argentina and Uruguay. The species has been domesticated, and feral Muscovy ducks can be found locally in New Zealand, Australia, the United States, and in Central and Eastern Europe.", iucn: "LC" },
  "copgoo1": { extract: "The cotton pygmy goose or cotton teal (Nettapus coromandelianus) is a small perching duck which breeds in South and Southeast Asia extending to Queensland in Australia where they are sometimes called white-quilled pygmy goose. They are among the smallest waterfowl in the world and are found in small to large waterbodies with good aquatic vegetation. They are usually seen in pairs or larger groups of pairs, roosting and nesting on trees near water. They are strong fliers and are known to disperse widely, especially in winter. Their breeding season coincides with the rains.", iucn: "LC" },
  "gargan": { extract: "The garganey (Spatula querquedula) is a small dabbling duck. It breeds in much of Europe and across the Palearctic, but is strictly migratory, with the entire population moving to Africa, India (in particular Santragachi), Bangladesh (in the natural reservoirs of Sylhet district) and Australasia during the winter of the Northern hemisphere, where large flocks can occur. This species was first described by Carl Linnaeus in his landmark 1758 10th edition of Systema Naturae. Like other small ducks such as the Eurasian teal, this species rises easily from the water with a fast twisting wader-like flight. Their breeding habitat is grassland adjacent to shallow marshes and steppe lakes.", iucn: "LC" },
  "norsho": { extract: "The northern shoveler (; Spatula clypeata), often known simply as the shoveler where other related species do not occur, is a common and widespread duck. It breeds in northern areas of Europe and throughout the Palearctic and across most of North America, and winters in southern Europe, the Indian subcontinent, Southeast Asia, Central America, the Caribbean, and northern South America. It is a rare vagrant to Australia. In North America, it breeds along the southern edge of Hudson Bay and west of this body of water, and as far south as the Great Lakes west to Colorado, Nevada, and Oregon. The northern shoveler is one of the species to which the Agreement on the Conservation of African-Eurasian Migratory Waterbirds (AEWA) applies. The conservation status of this bird is least concern.", iucn: "LC" },
  "gadwal": { extract: "The gadwall (Mareca strepera) is a common and widespread dabbling duck in the family Anatidae.", iucn: "LC" },
  "eurwig": { extract: "The Eurasian wigeon or European wigeon (Mareca penelope), also known as the widgeon or wigeon, is one of three extant species of wigeon in the dabbling duck genus Mareca. It is common and widespread within its Palearctic range.", iucn: "LC" },
  "isbduc1": { extract: "The Indian spot-billed duck (Anas poecilorhyncha) is a species of large dabbling duck that is a non-migratory breeding duck throughout freshwater wetlands in the Indian subcontinent. The name is derived from the red spot at the base of the bill that is found in the mainland Indian population. When in water it can be recognized from a long distance by the white tertials that form a stripe on the side, and in flight it is distinguished by the green speculum with a broad white band at the base. This species and the eastern spot-billed duck (A. zonorhyncha) were formerly considered conspecific, together called the spot-billed duck (A. poecilorhyncha).", iucn: "LC" },
  "mallar3": { extract: "The mallard () or wild duck (Anas platyrhynchos) is a dabbling duck that breeds throughout the temperate and subtropical Americas, Eurasia, and North Africa. It has been introduced to New Zealand, Australia, Peru, Brazil, Uruguay, Argentina, Chile, Colombia, the Falkland Islands, and South Africa. Belonging to the subfamily Anatinae of the waterfowl family Anatidae, mallards live in wetlands, eat water plants and small animals, and are social animals preferring to congregate in groups or flocks of varying sizes. Males (drakes) have green heads, while the females (ducks) have mainly brown-speckled plumage. Both sexes have an area of white-bordered black or iridescent purple or blue feathers called a speculum on their wings; males especially tend to have blue speculum feathers. The mallard is 50–65 cm (20–26 in) long, of which the body makes up around two-thirds the length.", iucn: "LC" },
  "norpin": { extract: "The pintail or northern pintail (Anas acuta) is a duck species with wide geographic distribution that breeds in the northern areas of Europe and across the Palearctic and North America. It is migratory and winters south of its breeding range as far as the equator. Unusually for a bird with such a large range, it has no geographical subspecies, although the possibly conspecific duck Eaton's pintail is considered to be a separate species. The Northern Pintail is a large duck, and the long central tail feathers of the male give the species its English and scientific names. Both sexes have blue-grey bills and grey legs and feet. The drake is more striking, with a thin white stripe running from the back of its chocolate-coloured head down its neck to its mostly white underparts. The drake also has attractive grey, brown, and black markings on its back and sides.", iucn: "LC" },
  "gnwtea": { extract: "The Eurasian teal (Anas crecca), common teal, or Eurasian green-winged teal is a common and widespread duck that breeds in temperate Eurosiberia and migrates south in winter. The Eurasian teal is often called simply the teal due to being the only one of these small dabbling ducks in much of its range. The bird gives its name to the blue-green colour teal. It is a highly gregarious duck outside the breeding season and can form large flocks. It is commonly found in sheltered wetlands and feeds on seeds and aquatic invertebrates. The North American green-winged teal (A. carolinensis) was formerly (and sometimes is still) considered a subspecies of A. crecca.", iucn: "LC" },
  "recpoc": { extract: "The red-crested pochard (Netta rufina) is a large diving duck. The scientific name is derived from Greek Netta \"duck\", and Latin rufina, \"golden-red\" (from rufus, \"ruddy\"). Its breeding habitat is lowland marshes and lakes in southern Europe and it extends from the steppe and semi-desert areas on the Black Sea to Central Asia and Mongolia, wintering in the Indian subcontinent and Africa. It is somewhat migratory, and northern birds winter further south into north Africa. The adult male is unmistakable. It has a rounded orange head, red bill and black breast. The flanks are white, the back brown, and the tail black. The female is mainly a pale brown, with a darker back and crown and a whitish face. Eclipse males are like females but with red bills. They are gregarious birds, forming large flocks in winter, often mixed with other diving ducks, such as common pochards.", iucn: "LC" },
  "compoc": { extract: "The common pochard (; Aythya ferina), known simply as pochard in the United Kingdom, is a medium-sized diving duck in the family Anatidae. It is widespread across the Palearctic. It breeds primarily in Scandinavia and the steppe regions of Siberia, and winters farther south and west.", iucn: "VU" },
  "ferduc": { extract: "The ferruginous duck (Aythya nyroca), also known as the ferruginous pochard, common white-eye or white-eyed pochard, is a medium-sized diving duck native to the Palearctic. The scientific name is derived from the Ancient Greek word, αἴθυιᾰ (aithuia), an unknown seabird mentioned by authors including Hesychius and Aristotle, and the Russian word, нырок (nyrok), the Russian word for pochard, which occurs in the bird's Russian common name.", iucn: "NT" },
  "tufduc": { extract: "The tufted duck (or tufted pochard) (Aythya fuligula) is a small diving duck with a population of nearly one million birds, found in northern Eurasia. They are partially migratory. The scientific name is derived from Ancient Greek aithuia, an unidentified seabird mentioned by authors such as Hesychius and Aristotle, and Latin fuligo 'soot' and gula 'throat'. It is a game bird.", iucn: "LC" },
  "helgui": { extract: "The helmeted guinea fowl (Numida meleagris) is the best known of the guinea fowl bird family, Numididae, and the only member of the genus Numida. It is native to Africa, mainly south of the Sahara, and has been widely introduced, as a domesticated species, into the West Indies, North America, Colombia, Brazil, Australia and Europe.", iucn: "LC" },
  "wiltur": { extract: "The wild turkey (Meleagris gallopavo) is an upland game bird native to North America, one of two extant species of turkey and the heaviest member of the order Galliformes. It is the ancestor to the domestic turkey (M. g. domesticus), which was originally derived from a southern Mexican subspecies of wild turkey (not the related ocellated turkey).", iucn: "LC" },
  "compea": { extract: "The Indian peafowl (Pavo cristatus), also known as the common peafowl, or blue peafowl, is a species of peafowl native to the Indian subcontinent. While it originated in the Indian subcontinent, it has since been introduced to many other parts of the world. Male peafowl are referred to as peacocks, and female peafowl are referred to as peahens, although both sexes are often referred to colloquially as a \"peacock\". The Indian peafowl displays a marked form of sexual dimorphism. The brightly coloured male has a blue coloured head with a fan-shaped crest and is best known for his long train. The train is made up of elongated upper-tail covert feathers with colourful eyespots. These stiff feathers are raised into a fan and quivered in a display during courtship. The peahen is predominantly brown in colour, with a white face and iridescent green lower neck, and lacks the elaborate train.", iucn: "LC" },
  "redspu1": { extract: "The red spurfowl (Galloperdix spadicea) is a member of the pheasant family and is endemic to India. It is a bird of forests, and is quite secretive despite its size. It has a distinctive call and is often hard to see except for a few seconds when it flushes from the undergrowth. It appears reddish and like a long-tailed partridge. The bare skin around the eye is reddish. The legs of both males and females have one or two spurs, which give them their name.", iucn: "LC" },
  "paispu1": { extract: "The painted spurfowl (Galloperdix lunulata) is a bird of the pheasant family found in rocky hill and scrub forests mainly in peninsular India. Males are more brightly coloured and spotted boldly in white. Males have two to four spurs while females can have one or two of the spurs on their tarsus. The species is found mainly in rocky and scrub forest habitats unlike the red spurfowl. It is found in the undergrowth in pairs or small groups, escaping by running and rarely taking to the wing when flushed.", iucn: "LC" },
  "grejun2": { extract: "The grey junglefowl (Gallus sonneratii), also known as Sonnerat's junglefowl, is one of the wild ancestors of the domestic chicken together with the red junglefowl and other junglefowls. The species epithet commemorates the French explorer Pierre Sonnerat. Local names include Komri in Rajasthan, Geera kur or Parda komri in Gondi, Jangli Murghi in Hindi, Raan kombdi in Marathi, Kattu Kozhi in Tamil and Malayalam, Kaadu koli in Kannada and Tella adavi kodi in Telugu.", iucn: "LC" },
  "gryfra": { extract: "The grey francolin (Ortygornis pondicerianus) is a species of francolin found in the plains and drier parts of the Indian subcontinent and Iran. This species was formerly also called the grey partridge, not to be confused with the European grey partridge. They are mainly ground-living birds and are found in open cultivated lands as well as scrub forest and their local name of teetar is based on their calls, a loud and repeated Ka-tee-tar...tee-tar, which is produced by one or more birds. The term teetar can also refer to other partridges and quails. During the breeding season, calling males attract challengers, and decoys were used to trap these birds especially for fighting.", iucn: "LC" },
  "paifra1": { extract: "The painted francolin or painted partridge (Francolinus pictus) is a species of francolin found in grassy areas in central and southern India and in the lowlands of southeastern Sri Lanka. Thomas C. Jerdon noted that the species was found mainly in Central India south of the Narmada and to the east of the Western Ghats as well as the Chota Nagpur and Northern Circars. It partly overlaps with the black francolin with which it partly overlaps and is said to sometimes hybridize. This species can be so distinguished from a black francolin female by the lack of a rufous hind collar and the white spots on the underside. The face is rufous and there is no dark stripe running behind the eye.", iucn: "LC" },
  "blbqua1": { extract: "The king quail (Synoicus chinensis), also known as the Asian blue quail, blue-breasted quail, Chinese painted quail, button quail, or Chung-Chi, is a very small, diminutive galliform of the tribe Coturnicini in the subfamily Phasianinae. They are the smallest member in this subfamily and the family Phasianidae, as well as being the smallest and lightest member of the order Galliformes. It is quite common in aviculture worldwide, where it is sometimes referred to as the \"button quail\", although it is not closely related to the family of birds called buttonquails. Its voice is a piping whistle, ti-yu or ti-ti-yu. It also gives sharp cheeps or a tir-tir-tir sound when flushed.", iucn: "LC" },
  "comqua1": { extract: "The common quail (Coturnix coturnix) or European quail is a small ground-nesting game bird in the pheasant family Phasianidae. It is mainly migratory, breeding in the Palearctic and wintering in Africa and southern India. With its characteristic call of three repeated chirps (repeated three times in quick succession), this species of quail is more often heard than seen. It is widespread in Europe and North Africa, and is categorised by the IUCN as \"least concern\". It should not be confused with the Japanese quail (Coturnix japonica), native to Asia, which, although visually similar, has a call that is very distinct from that of the common quail. Like the Japanese quail, common quails are sometimes kept as poultry.", iucn: "LC" },
  "raiqua1": { extract: "The rain quail or black-breasted quail (Coturnix coromandelica) is a species of quail found in the Indian Sub-continent and South-east Asia; its range including Pakistan, India, Nepal, Sri Lanka, Bangladesh, Myanmar, Thailand, Cambodia and Vietnam.", iucn: "LC" },
  "jubqua1": { extract: "The jungle bush quail (Perdicula asiatica) is a species of quail in the family Phasianidae. It is native to the Indian subcontinent, where it is found in peninsular India and Sri Lanka. It has also been reported from Nepal but has not been seen there since the 19th century, and an introduced population exists on the island of Réunion. A small species of quail 15–18 cm (5.9–7.1 in) long and weighing 57–82 g (2.0–2.9 oz), it shows significant sexual dimorphism. Males have brown upperparts with blackish and buff marking and whitish underparts with black barring. The face is mainly dark reddish-brown, with brown ear-coverts, a buffy-white moustachial stripe, and the supercilium turning whitish towards the back of the neck. Females have a similar pattern, but with pinkish-brown underparts, more uniform wings, and duller moustachial stripes.", iucn: "LC" },
  "robqua1": { extract: "The rock bush quail (Perdicula argoondah) is a species of quail found in parts of peninsular India. It is a common species with a wide range and the IUCN has rated it as being of \"least concern\".", iucn: "LC" },
  "pabqua1": { extract: "The painted bush quail (Perdicula erythrorhyncha) is a species of quail found in the hill forests of India. They move in small coveys on hillsides and are distinguished by their red bills and legs. They have a liquid alarm call and small groups will run in single file along paths before taking flight when flushed.", iucn: "LC" },
  "rocpig": { extract: "The rock dove (Columba livia), also known as the common pigeon or rock pigeon (but see also Petrophassa), is a member of the bird family Columbidae (doves and pigeons). In common usage, it is often simply referred to as the \"pigeon\", although the rock dove is the wild form of the bird; the pigeons familiar to most people are the domesticated forms of the wild rock dove. Wild rock doves are uniformly pale grey with two black bars on each wing, with few differences being seen between males and females; i.e. they are not strongly sexually dimorphic. The domestic pigeon, often called \"Columba livia domestica\", which includes about 1,000 different breeds, is descended from this species. Escaped domestic pigeons are the origin of feral pigeons around the world.", iucn: "LC" },
  "cowpig1": { extract: "The common wood pigeon (Columba palumbus), also known simply as the wood pigeon, is a large pigeon native to the western Palearctic. It belongs to the genus Columba, which includes closely related species such as the rock dove (Columba livia). It has a flexible diet, feeding mainly on plant material, including cereals, and is therefore considered an agricultural pest. Wood pigeons are extensively hunted over much of their range, but this does not appear to have a major impact on their population numbers.", iucn: "LC" },
  "niwpig1": { extract: "The Nilgiri wood pigeon (Columba elphinstonii) is a large pigeon found in the moist deciduous forests and sholas of the Western Ghats in southwestern India. They are mainly frugivorous and forage in the canopy of dense hill forests. They are best identified in the field by their large size, dark colours and the distinctive checkerboard pattern on their nape.", iucn: "VU" },
  "ortdov": { extract: "The Oriental turtle dove or rufous turtle dove (Streptopelia orientalis) is a member of the bird family Columbidae. The species has a wide native distribution range from Central Asia east across Asia to Japan. The populations show variations in the patterning of plumage and have been designated into at least six named subspecies. Populations in the higher latitudes tend to migrate south in winter, while those closer to the tropics are sedentary. Vagrants have been recorded in North America. The species is predominantly granivorous and forages on the ground.", iucn: "LC" },
  "eucdov": { extract: "The Eurasian collared dove (Streptopelia decaocto), often called the collared dove, is a dove species from the genus Streptopelia. It is grey-buff to pinkish-grey, and has a black half-collar edged with white on its nape, alluding to the name. It is native to Europe, Asia, and North Africa. It has also been introduced to Japan, North and Central America, and select Caribbean islands.", iucn: "LC" },
  "recdov1": { extract: "The red collared dove (Streptopelia tranquebarica), also known as the red turtle dove, is a small pigeon which is a resident breeding bird in the tropics of Asia. The male has a blue-grey head and a red-brown body. The female is much plainer, with pale brown plumage similar to that of the larger Eurasian collared dove.", iucn: "LC" },
  "spodov": { extract: "The spotted dove or eastern spotted dove (Spilopelia chinensis) is a small and somewhat long-tailed pigeon that is a common resident breeding bird across its native range on the Indian subcontinent and in East and Southeast Asia. The species has been introduced to many parts of the world and feral populations have become established. This species was formerly included in the genus Streptopelia with other turtle-doves, but studies suggest that they differ from typical members of that genus. This dove is long tailed buff brown with a white-spotted black collar patch on the back and sides of the neck. The tail tips are white and the wing coverts have light buff spots. There are considerable plumage variations across populations within its wide range. The species is found in light forests and gardens as well as in urban areas.", iucn: "LC" },
  "laudov1": { extract: "The laughing dove (Spilopelia senegalensis) is a small pigeon that is a resident breeder in Africa, the Middle East, South Asia, and Western Australia where it has established itself in the wild after being released from Perth Zoo in 1898. This small long-tailed dove is found in dry scrub and semi-desert habitats where pairs can often be seen feeding on the ground. It is closely related to the spotted dove (Spilopelia chinensis) which is distinguished by a white and black chequered necklace. Other names include laughing turtle dove, palm dove and Senegal dove while in Asia the name little brown dove is often used.", iucn: "LC" },
  "emedov2": { extract: "The emerald dove or common emerald dove (Chalcophaps indica), also called Asian emerald dove and grey-capped emerald dove, is a widespread resident breeding pigeon native to the tropical and subtropical parts of the Indian subcontinent and Southeast Asia. The dove is also known by the names of green dove and green-winged pigeon. The common emerald dove is the state bird of the Indian state of Tamil Nadu. The Pacific emerald dove and Stephan's emerald dove were both considered conspecific.", iucn: "LC" },
  "diadov1": { extract: "The diamond dove (Geopelia cuneata) is a resident bird in Australia. The pigeon predominantly exists in areas near water but which are lightly arid or semi-arid in nature, being Central, West and Northern Australia. They are one of Australia's smallest pigeons along with the peaceful dove. They have been spotted occasionally in Southern Australia in parks and gardens when the centre of Australia is very dry.", iucn: "LC" },
  "orbpig1": { extract: "The orange-breasted green pigeon (Treron bicinctus) is a pigeon found across tropical Asia south of the Himalaya across parts of the Indian subcontinent and Southeast Asia. Like other green pigeons, it feeds mainly on small fruit. They may be found in pairs or in small flocks, foraging quietly and moving slowly on trees. The nape is blue-grey and the crown is yellowish green. The uppertail coverts are bronzed and the undertail coverts are unmarked rufous. The male has a pinkish band on the upper breast with a broader orange one below while the female has a bright yellow breast.", iucn: "LC" },
  "pomgrp2": { extract: "The grey-fronted green pigeon (Treron affinis) is a pigeon in the genus Treron. It is found in the forests of the Western Ghats in India. Many authorities have split the species from the pompadour green pigeon complex.", iucn: "LC" },
  "yefpig1": { extract: "The yellow-footed green pigeon (Treron phoenicopterus), also known as yellow-legged green pigeon, is a common species of green pigeon found in the Indian subcontinent and parts of Southeast Asia. It is the state bird of Maharashtra. Their population is currently increasing.", iucn: "LC" },
  "gripig1": { extract: "The green imperial pigeon (Ducula aenea) is a large forest pigeon. The large range extends from Nepal, southern India and Sri Lanka eastwards to southern China, Indonesia and the Philippines.", iucn: "NT" },
  "mouimp1": { extract: "The Malabar imperial pigeon or Nilgiri imperial pigeon (Ducula cuprea) is a species of bird in the family Columbidae. It is endemic to the Western Ghats of India. Its natural habitats are subtropical or tropical moist lowland forests and subtropical or tropical moist montane forests. It previously was considered a subspecies of the mountain imperial pigeon, but was split due to differences in morphology and plumage. This split was later supported by an analysis of its calls.", iucn: "LC" },
  "chbsan": { extract: "The chestnut-bellied sandgrouse or common sandgrouse (Pterocles exustus) is a species of sandgrouse. It is a sedentary and nomadic species that ranges from northern and central Africa and further east towards western and southern Asia. There are six recognized subspecies. The chestnut-bellied sandgrouse is sexually dimorphic in plumage colouration and varies in overall plumage colouration between the six subspecies. The chestnut-bellied sandgrouse is a bird of barren, semi-deserts. It is heavily reliant on water, despite living in hot, arid climates and is known to travel up to 50 miles (80 kilometres) in a day to search for water. Chestnut-bellied sandgrouse are selective feeders which primarily subsist on seeds, often preferring to consume small seeds in large amounts.", iucn: "LC" },
  "paisan1": { extract: "The painted sandgrouse (Pterocles indicus) is a medium large bird in the sandgrouse family Pteroclidae found in India and Pakistan.", iucn: "LC" },
  "indbus1": { extract: "The great Indian bustard (Ardeotis nigriceps) or Indian bustard is a bustard occurring on the Indian subcontinent. It is a large bird with a horizontal body, long bare legs and is among the heaviest of the flying birds. Once common on the dry grasslands and shrubland in India, as few as 150 individuals were estimated to survive as of 2018, reduced from an estimated 250 individuals in 2011. It is critically endangered due to hunting and habitat loss. It is protected under the Indian Wild Life (Protection) Act, 1972.", iucn: "CR" },
  "lesflo2": { extract: "The lesser florican (Sypheotides indicus), also known as the likh or kharmore, is the smallest in the bustard family and the only member of the genus Sypheotides. It is endemic to the Indian Subcontinent where it is found in tall grasslands and is best known for the leaping breeding displays made by the males during the monsoon season. The male has a contrasting black and white breeding plumage and distinctive elongated head feathers that extend behind the neck. These bustards are found mainly in northwestern and central India during the summer but are found more widely distributed across India in winter. The species is highly endangered and has been extirpated in some parts of its range such as Pakistan. It is threatened both by hunting and habitat degradation.", iucn: "CR" },
  "guitur1": { extract: "The Guinea turaco (Tauraco persa), also known as the green turaco or green lourie, is a species of turaco, a group of African otidimorph birds. It formerly included the Livingstone's, Schalow's, Knysna, black-billed and Fischer's turacos as subspecies.", iucn: "LC" },
  "grecou1": { extract: "The greater coucal or crow pheasant (Centropus sinensis), is a large non-parasitic member of the cuckoo order of birds, the Cuculiformes. A widespread resident in the Indian subcontinent and Southeast Asia, it is divided into several subspecies, some being treated as full species. They are large, crow-like with a long tail and coppery brown wings and found in a wide range of habitats from jungle to cultivation and urban gardens. They are weak fliers, and are often seen clambering about in vegetation or walking on the ground as they forage for insects, eggs and nestlings of other birds. They have a familiar deep resonant call which is associated with omens in many parts of its range.", iucn: "LC" },
  "lescou1": { extract: "The lesser coucal (Centropus bengalensis) is a species of cuckoo in the family Cuculidae. It has a wide distribution range that overlaps with several other similar species. The habitat in which it is found is often marshy land with grass and tree cover. It is distinguished by its smaller size, less prominent bill, pale shaft streaks on the feathers of the head and back. It has a much longer claw on its hind toe and a distinct call. It is also among the few coucals that show season plumage differences but like in other coucals, the sexes cannot be distinguished in the field.", iucn: "LC" },
  "sirmal1": { extract: "The sirkeer malkoha or sirkeer cuckoo (Taccocua leschenaultii), is a non-parasitic cuckoo found in dry scrub forest and open woodland habitats in the Indian subcontinent. The species is long-tailed, largely olive brown on the upper side with a distinctive curved red beak tipped in yellow. They forage singly or in pairs mainly on or close to the ground creeping between grasses and bushes, often on rocky habitats where they feed on small lizards, insects, and sometimes berries and seeds. They are very silent and the sexes are identical in plumage.", iucn: "LC" },
  "blfmal1": { extract: "The blue-faced malkoha (Phaenicophaeus viridirostris) or small green-billed malkoha, is a non-parasitic cuckoo found in the scrub and deciduous forests of peninsular India and Sri Lanka. It has a waxy, dark, blue-grey plumage on its upperparts and has a long tail with graduated white-tipped feathers. The throat and chin are dark with spiny pale feathers that are branched. The lower belly is a dull creamy to rufous colour. The bill is apple green, and a naked patch of blue skin surrounds the eye. The sexes are alike. The blue-faced malkoha is a bird of open forests and scrub jungle.", iucn: "LC" },
  "chwcuc1": { extract: "The chestnut-winged cuckoo or red-winged crested cuckoo (Clamator coromandus) is a cuckoo found in Southeast Asia and parts of South Asia. It has dark glossy upperparts, a black head with long crest chestnut wings, a long graduated glossy black tail, rufous throat dusky underside and a narrow white nuchal half collar. They breed along the Himalayas and migrate south in winter to Sri Lanka, southern India and tropical Southeast Asia including parts of Indonesia, Thailand and the Philippines. It is about 47 cm (19 in) long.", iucn: "LC" },
  "piecuc1": { extract: "The Jacobin cuckoo (Clamator jacobinus), also pied cuckoo or pied crested cuckoo, is a member of the cuckoo order of birds that is found in Africa and Asia. It is partially migratory and in India, it has been considered a harbinger of the monsoon rains due to the timing of its arrival. It has been associated with a bird in Indian mythology and poetry, known as the chātaka (Sanskrit: चातक) represented as a bird with a beak on its head that waits for rains to quench its thirst.", iucn: "LC" },
  "asikoe2": { extract: "The Asian koel (Eudynamys scolopaceus) is a member of the cuckoo family of birds, the Cuculidae. It is found in the Indian subcontinent, China, and Southeast Asia. It forms a superspecies with the closely related black-billed koels, and Pacific koels which are sometimes treated as subspecies. The Asian koel, like many of its related cuckoo kin, is a brood parasite that lays its eggs in the nests of crows and other hosts, who raise its young. They are unusual among the cuckoos in being largely frugivorous as adults. The name koel is echoic in origin with several language variants. The bird is a widely used symbol in Indian, Pakistani and Nepali poetry.", iucn: "LC" },
  "babcuc2": { extract: "The banded bay cuckoo or bay-banded cuckoo (Cacomantis sonneratii) is a species of small cuckoo found in the Indian subcontinent and Southeast Asia. Like others in the genus they have round nostrils. They are usually founded in well-wooded areas mainly in the lower hills. Males sing from exposed branches during the breeding season, which can vary with region. They are distinctive both in their calls as well as plumage with a white eyebrowed appearance and the rufous upperparts with regular dark bands and the whitish underside with fine striations.", iucn: "LC" },
  "placuc1": { extract: "The plaintive cuckoo (Cacomantis merulinus) is a species of bird belonging to the genus Cacomantis in the cuckoo family Cuculidae. It is native to Asia, from India, Nepal and China to Indonesia.", iucn: "LC" },
  "placuc3": { extract: "The grey-bellied cuckoo or the Indian plaintive cuckoo (Cacomantis passerinus) is a cuckoo with widespread occurrence throughout Asia.", iucn: "LC" },
  "asidrc2": { extract: "The fork-tailed drongo-cuckoo (Surniculus dicruroides) is a species of cuckoo that resembles the Black drongo (Dicrurus macrocercus). It is found mainly in hill forests in peninsular India and Sri Lanka although some specimens are known from the Himalayan foothills. It can be identified by its metallic black plumage, straight beak, white barred vent, forked tail and white spot on the back of the head. The fork-tailed drongo-cuckoo's song has been described as a series of 5 or 6 whistling \"pip-pip-pip-pip-pip-\" notes rising in pitch with each \"pip\". They are also known for their drongo-like calls such as \"quip\" calls in flight and \"wheep-wheep\" call with a higher second note. In Sri Lanka, the fork-tailed drongo-cuckoo also has similar calls to the Sri Lanka Drongo (Dicrurus lophorinus). It is a brood parasite on small babblers.", iucn: "LC" },
  "larhac2": { extract: "The large hawk-cuckoo (Hierococcyx sparverioides) is a species of cuckoo in the family Cuculidae. It has a wide breeding distribution from temperate Asia along the Himalayas extending to East Asia. Many populations winter further south. They are known for their loud and repetitive calls which are similar to that of the common hawk-cuckoo but do not rise in crescendo. They are also somewhat larger and adults can be readily told apart from the smaller common hawk-cuckoo by the black patch on the chin. They are brood-parasites of babblers and laughing-thrushes.", iucn: "LC" },
  "cohcuc1": { extract: "The common hawk-cuckoo (Hierococcyx varius), popularly known as the brainfever bird, is a medium-sized cuckoo resident in the Indian subcontinent. It bears a close resemblance to the shikra, even in its style of flying and landing on a perch. The resemblance to hawks gives this group the generic name of hawk-cuckoo; like many other cuckoos, these are brood parasites, laying their eggs in the nests of babblers. During their breeding season in summer males produce loud, repetitive three-note calls that are well-rendered as brain-fever, the second note being longer and higher pitched. These notes rise to a crescendo before ending abruptly and repeat after a few minutes; the calling may go on through the day, well after dusk and before dawn.", iucn: "LC" },
  "lescuc1": { extract: "The lesser cuckoo (Cuculus poliocephalus) is a species of cuckoo in the family Cuculidae. It is native to East Asia and the Himalayas; it winters to East Africa and Sri Lanka.", iucn: "LC" },
  "indcuc1": { extract: "The Indian cuckoo or short-winged cuckoo (Cuculus micropterus) is a member of the cuckoo order of birds, the Cuculiformes, that is found in the Indian subcontinent and Southeast Asia. It ranges from India, Bangladesh, Bhutan, Nepal and Sri Lanka east to Indonesia and north to China and Russia. It is a solitary and shy bird, found in forests and open woodland at up to 3,600 m (11,800 ft).", iucn: "LC" },
  "comcuc": { extract: "The cuckoo, common cuckoo, European cuckoo or Eurasian cuckoo (Cuculus canorus) is a member of the cuckoo order of birds, Cuculiformes, which includes the roadrunners, the anis and the coucals. This species is a widespread summer migrant to Europe and Asia, and winters in Africa. It is a brood parasite, which means it lays eggs in the nests of other bird species, particularly of dunnocks, meadow pipits, and reed warblers. Although its eggs are larger than those of its hosts, the eggs in each type of host nest resemble the host's eggs. The adult too is a mimic, in its case of the sparrowhawk; since that species is a predator, the mimicry gives the female time to lay her eggs without being attacked.", iucn: "LC" },
  "grynig2": { extract: "The jungle nightjar (Caprimulgus indicus) is a species of nightjar found in the Indian subcontinent. It is found mainly on the edge of forests where it is seen or heard at dusk. The taxonomy of this and related nightjars is complex and a range of treatments have been followed that cover this and several other nightjars in the Asian region. It was formerly called the grey nightjar or Indian jungle nightjar and sometimes included the East Asian grey nightjar (C. jotaka) as a subspecies.", iucn: "LC" },
  "syknig1": { extract: "The Sykes's nightjar, Sykes' nightjar, Sind nightjar or Sindh nightjar (Caprimulgus mahrattensis) is a nightjar species found in northwestern South Asia. This species has a large range with stable population size and therefore has been listed as \"Least Concern\" with no prediction of substantial human influence on their habitats in the near future.", iucn: "LC" },
  "jernig1": { extract: "Jerdon's nightjar (Caprimulgus atripennis) is a medium-sized nightjar species native to southern India and Sri Lanka. Formerly considered as a subspecies of the long-tailed nightjar, it is best recognized by its distinctive call which sounds like a wooden plank being beaten periodically with each note ending in a quaver. The common name commemorates Thomas C. Jerdon who described the species.", iucn: "LC" },
  "indnig1": { extract: "The Indian nightjar (Caprimulgus asiaticus) is a small nightjar which is a resident breeder in open lands across South Asia and Southeast Asia. Like most nightjars it is crepuscular and is best detected from its characteristic calls at dawn and dusk that have been likened to a stone skipping on a frozen lake - a series of clicks that become shorter and more rapid. They are sometimes spotted on roads when their eyes gleam red in the spotlight of a vehicle. There is considerable plumage variation across its range and can be hard to differentiate from other nightjars in the region especially in the field.", iucn: "LC" },
  "savnig1": { extract: "The savanna nightjar (Caprimulgus affinis), also known as allied nightjar or Franklin's nightjar, is a species of nightjar found in South and Southeast Asia. The IUCN Red List has assessed the species to be of least concern because it has a large range and its population trend is stable. As other nightjars, this nocturnal bird is characterised by its large eyes, gaping mouth and excellent camouflage. It can be distinguished from similar south Asian nightjar species, like the chirruping nightjar, by its unique vocalisations.", iucn: "LC" },
  "ceyfro1": { extract: "The Sri Lanka frogmouth, Sri Lankan frogmouth or Ceylon frogmouth (Batrachostomus moniliger) is a small frogmouth found in the Western Ghats of south India and Sri Lanka. Related to the nightjars, it is nocturnal and is found in forest habitats. The plumage coloration resembles that of dried leaves and the bird roosts quietly on branches, making it difficult to see. Each has a favourite roost that it uses regularly unless disturbed. It has a distinctive call that is usually heard at dawn and dusk. The sexes differ slightly in plumage.", iucn: "LC" },
  "whrnee1": { extract: "The white-rumped spinetail or white-rumped needletail (Zoonavena sylvatica) is a species of swift found in the forests of Bangladesh, India (the Western Ghats) and Nepal. It is often seen over waterbodies in the middle of forest. It can resemble a house swift but has a white vent.", iucn: "LC" },
  "brbnee1": { extract: "The brown-backed needletail (Hirundapus giganteus), or brown needletail, is a large swift. These birds have very short legs which they use only mainly for clinging to vertical surfaces. They never settle voluntarily on the ground and spend most of their lives in the air, living on the insects they catch in their beaks. These swifts are resident breeders in hill forests in southern India and southeast Asia, extending to the Greater Sunda islands of Indonesia and Palawan in the southern Philippines. They build their nests in rock crevices in cliffs, laying 3-5 eggs. The flight is impressively fast, even compared to other swifts. The brown-backed needletail is among the largest swifts worldwide, and at 23 cm is bigger than the Alpine swift and the white-throated needletail. It has a similar build to the latter species, with a heavy barrel-like body.", iucn: "LC" },
  "indswi1": { extract: "The Indian Swiftlet or Indian Edible-Nest Swiftlet (Aerodramus unicolor) is a small swift. It is a common resident colonial breeder in the hills of Sri Lanka and southwest India. The half-cup nest is built on a vertical surface, often in a cave. The male swift uses thick saliva to construct the white, shiny nest into which two eggs are laid. The relatively tasteless nests are harvested, and mixed with chicken, spices, and other flavours as bird's nest soup, a supposed aphrodisiac. This 12 cm long species is mainly dark brown above and paler brown below. It has swept-back wings that resemble a crescent or a boomerang. The body is slender, and the tail is short and only slightly indented. Both sexes and young birds are similar. The Indian swiftlet has very short legs which it uses only for clinging to vertical surfaces, since swifts never settle voluntarily on the ground.", iucn: "LC" },
  "alpswi1": { extract: "The alpine swift (Tachymarptis melba) is a species of swift found in Africa, southern Europe, and Asia. They breed in mountains from southern Europe to the Himalayas. Like common swifts, they are migratory; the southern European population winters further south in southern Africa. They have very short legs which are used for clinging to vertical surfaces. Like most swifts, they never settle voluntarily on the ground, spending most of their lives in the air living on the insects they catch in their beaks.", iucn: "LC" },
  "comswi": { extract: "The common swift (Apus apus) is a medium-sized bird, superficially similar to the barn swallow or house martin but somewhat larger, though not stemming from those passerine species, being in the order Apodiformes. The resemblances between the groups are due to convergent evolution, reflecting similar contextual development. The swifts' nearest relatives are the New World hummingbirds and the Southeast Asian treeswifts. Its scientific name Apus is Latin for a swift, thought by the ancients to be a type of swallow with no feet (from Ancient Greek α, a, \"without\", and πούς, pous, \"foot\"). Swifts have very short legs which they use primarily for clinging to vertical surfaces (hence the German name Mauersegler, literally meaning \"wall-glider\").", iucn: "LC" },
  "blyswi1": { extract: "Blyth's swift (Apus leuconyx) is a small species of bird. It is superficially similar to a house martin, but completely unrelated to those passerine species, as swifts are in the order Apodiformes. The resemblances between the groups are due to convergent evolution reflecting similar life styles.", iucn: "" },
  "litswi1": { extract: "The little swift (Apus affinis) is a small species of swift found in Africa and southwestern Asia, and are vagrants and local breeders in southern Europe. They are found both in urban areas and at rocky cliffs where they build nests in a way typical of all members of the order Apodiformes. The genus name Apus is Latin for a swift, thought by the ancients to be a type of swallow without feet (from Ancient Greek α, a, \"without\", and πούς, pous, \"foot\"). The Latin specific affinis means similar to or related to, but in this case the species that the little swift supposedly resembles is not clear from the description. A population formerly considered to be an eastern subspecies of little swift is now separated as a distinct species, the house swift (Apus nipalensis).", iucn: "LC" },
  "aspswi1": { extract: "The Asian palm swift (Cypsiurus balasiensis) is a small swift. It is very similar to the African palm swift, Cypsiurus parvus, and was formerly considered to be the same species. It is a common resident breeder in tropical Asia from India to the Philippines. The down and feather nest is glued to the underside of a palm leaf with saliva, which is also used to secure the usually two or three eggs. This is a bird of open country and cultivation, which is strongly associated with oil palms. This 13 cm long species is mainly pale brown in colour. It has long swept-back wings that resemble a crescent or a boomerang. The body is slender, and the tail is long and deeply forked, although it is usually held closed. The call is a loud shrill scream. Sexes are similar, and young birds differ from adults mainly in their shorter tails.", iucn: "LC" },
  "cretre1": { extract: "The crested treeswift (Hemiprocne coronata) is a species of tree swift. It was for some time considered the same species as its eastern relative, the gray-rumped treeswift (Hemiprocne longipennis), but they do not interbreed where their ranges overlap. It is distinct in flight, with long, bowed wings and a deeply forked tail that usually appears narrow and pointed.", iucn: "LC" },
  "slbrai1": { extract: "The slaty-breasted rail (Lewinia striata) is a rail species native to the Indian subcontinent and Southeast Asia.", iucn: "LC" },
  "spocra1": { extract: "The spotted crake (Porzana porzana) is a small waterbird of the family Rallidae. The scientific name is derived from Venetian terms for small rails. The spotted crake's breeding habitat is marshes and sedge beds across temperate Europe into western Asia. They nest in a dry location in marsh vegetation, laying 6–15 eggs. This species is migratory, wintering in Africa and Pakistan. At 19–22.5 cm (7.5–8.9 in) length, spotted crakes are slightly smaller than water rails, from which they are readily distinguished by the short straight bill, yellow with a red base. Adults have mainly brown upperparts and blue-grey breast, with dark barring and white spots on the flanks. They have green legs with long toes, and a short tail which is buff underneath. Immature spotted crakes are similar, but the blue-grey is replaced by brown. The downy chicks are black, as with all rails.", iucn: "LC" },
  "commoo3": { extract: "The common moorhen (Gallinula chloropus), also known as the waterhen, is a bird species in the rail family (Rallidae). It is distributed across many parts of the Old World, across Africa, Europe, and Asia. It lives around well-vegetated marshes, ponds, canals and other wetlands. The species is not found in the polar regions or many tropical rainforests; generally it is one of the most common Old World rail species, together with the Eurasian coot in some regions.", iucn: "LC" },
  "eurcoo": { extract: "The Eurasian coot (Fulica atra), also known as the common coot or Australian coot, is a member of the rail and crake bird family, the Rallidae. It is found in Europe, Asia, Australia, New Zealand and parts of North Africa. It has a slaty-black body, a glossy black head and a white bill with a white frontal shield. The sexes are similar in appearance.", iucn: "LC" },
  "purswa3": { extract: "The grey-headed swamphen (Porphyrio poliocephalus) is a species of swamphen occurring from the Middle East and the Indian subcontinent to southern China and northern Thailand. It used to be considered a subspecies of the purple swamphen, but was elevated to full species status in 2015; today the purple swamphen is considered a superspecies and each of its six subspecies groups are designated full species. It is a large greyish-blue to greyish-purple wetland bird 43 cm long with a pale grey head, and a stout red bill. The wings are greenish, and the legs red. It occurs in marshes and jheels. The male has an elaborate courtship display, holding water weeds in his bill and bowing to the female with loud chuckles.", iucn: "" },
  "waterc1": { extract: "The watercock (Gallicrex cinerea) is a waterbird in the rail and crake family, Rallidae that is widely distributed across Southeast Asia. It is the only member of the genus Gallicrex.", iucn: "LC" },
  "whbwat1": { extract: "The white-breasted waterhen (Amaurornis phoenicurus) is a waterbird of the rail and crake family, Rallidae, that is widely distributed across South and Southeast Asia. They are dark slaty birds with a clean white face, breast and belly. They are somewhat bolder than most other rails and are often seen stepping slowly with their tail cocked upright in open marshes or even drains near busy roads. They are largely crepuscular in activity and during the breeding season, just after the first rains, make loud and repetitive croaking calls.", iucn: "LC" },
  "sllcra1": { extract: "The slaty-legged crake or banded crake (Rallina eurizonoides) is a waterbird in the rail and crake family, Rallidae.", iucn: "LC" },
  "rubcra1": { extract: "The ruddy-breasted crake (Zapornia fusca), or ruddy crake, is a waterbird in the rail and crake family Rallidae, formerly included in the genus Porzana. Its breeding habitat is swamps and similar wet areas across South Asia from the Indian subcontinent east to south China, Japan and Indonesia. It has been recorded as a vagrant from the Australian territory of Christmas Island. It is mainly a permanent resident throughout its range, but some northern populations migrate further south in winter. This crake nests in a dry location on the ground in marsh vegetation, laying 6-9 eggs. The ruddy-breasted crake is about 22–23 cm long. The body is flattened laterally to allow easier passage through the reeds or undergrowth. It has long toes and a short tail. The back is pale brown, the head and underparts chestnut, and with white barring on the flanks and undertail.", iucn: "LC" },
  "brocra1": { extract: "The brown crake (Zapornia akool), or brown bush-hen, is a waterbird in the rail and crake family (Rallidae) found in South Asia. The species name, akool, is of uncertain origin. It may come from Hindu mythology, or it may be a derivation of the Sinhalese word kukkula, which is used for both moorhen and watercock.", iucn: "LC" },
  "baicra1": { extract: "Baillon's crake (Zapornia pusilla), also known as the marsh crake, is a small waterbird of the family Rallidae.", iucn: "LC" },
  "demcra1": { extract: "The demoiselle crane (Grus virgo) is a species of crane found in central Eurosiberia, ranging from the Black Sea to Mongolia and Northeast China. There is also a small breeding population in Turkey. These cranes are migratory birds. Birds from western Eurasia will spend the winter in Africa while the birds from Asia, Mongolia and China will spend the winter in the Indian subcontinent. The bird is symbolically significant in the culture of India, where it is known as koonj or kurjaa.", iucn: "LC" },
  "comcra": { extract: "The common crane (Grus grus), also known as the Eurasian crane, is a bird of the family Gruidae, the cranes. A medium-sized species, it is the only crane commonly found in Europe besides the demoiselle crane (Grus virgo) and the Siberian crane (Leucogeranus leucogeranus) that only are regular in the far eastern part of the continent. Along with the sandhill crane (Antigone canadensis), demoiselle crane and the brolga (Antigone rubicunda), it is one of only four crane species not currently classified as threatened with extinction or conservation dependent on the species level. Despite the species' large numbers, local extinctions and extirpations have taken place in part of its range, and an ongoing reintroduction project is underway in the United Kingdom.", iucn: "LC" },
  "grtkne1": { extract: "The great stone-curlew or great thick-knee (Esacus recurvirostris) is a large wader which is a resident breeder in tropical southern Asia from India, Pakistan, Sri Lanka, Bangladesh into South-east Asia.", iucn: "NT" },
  "indthk1": { extract: "The Indian stone-curlew or Indian thick-knee (Burhinus indicus) is a species of bird in the family Burhinidae. It was formerly included as a subspecies of the Eurasian stone-curlew. This species is found in the plains of South and South-eastern Asia. They have large eyes and are brown with streaks and pale marks making it hard to spot against the background of soils and rocks. Mostly active in the dark, they produce calls similar to the true curlews, giving them their names.", iucn: "LC" },
  "bkwsti": { extract: "The black-winged stilt (Himantopus himantopus) is a widely distributed, very long-legged wader in the avocet and stilt family Recurvirostridae. Its scientific name, Himantopus himantopus, is sometimes used to generalize a single, almost cosmopolitan species. Alternatively, it is restricted to the form that is widespread in Europe, Asia and Africa, which equals the nominate group of H. himantopus sensu lato. Meanwhile, the black-necked (H. mexicanus) and white-backed stilts (H. melanurus) both inhabit the Americas; the pied stilt (H. leucocephalus) ranges from Australia and New Zealand. Today, most sources accept between one and four actual species.", iucn: "LC" },
  "pieavo1": { extract: "The pied avocet (Recurvirostra avosetta) is a species of wader in the Recurvirostridae family, the only member of the avocet genus Recurvirostra found in Europe, Africa, and Asia. This characteristic wader of coastal lagoons and marshes is easily recognisable by its long, upturned bill, long legs, and striking black-and-white plumage. Measuring approximately 40 cm (16 in) in length with a wingspan of about 70 cm (28 in), it is a relatively large species that feeds on various invertebrates in water and mudflats, captured using its distinctive bill. It typically nests in colonies of 10 to 70 pairs on islets or dikes near water, laying usually four eggs in a simple, shallow scrape in the sand. It is highly territorial when defending its chicks against conspecifics, or predators such as various raptors, corvids, and mammals.", iucn: "LC" },
  "euroys1": { extract: "The Eurasian oystercatcher or European oystercatcher (Haematopus ostralegus), also known as the common pied oystercatcher, or (in Europe) just oystercatcher, is a wader in the oystercatcher bird family Haematopodidae. It has striking black and white plumage, a long straight orange-red bill, red eyes and relatively short dull pink legs. The sexes are similar in appearance but the bill of the female is longer than that of the male. It is the most widespread of the oystercatchers, with four subspecies breeding in western Europe, central Eurosiberia, Kamchatka, China, and the western coast of Korea. No other oystercatcher occurs within this area.", iucn: "NT" },
  "bkbplo": { extract: "The grey plover or black-bellied plover (Pluvialis squatarola) is a large plover breeding in Arctic regions. It is a long-distance migrant, with a nearly worldwide coastal distribution when not breeding.", iucn: "VU" },
  "pagplo": { extract: "The Pacific golden plover (Pluvialis fulva) is a migratory shorebird that breeds during summer in Alaska and Siberia. During nonbreeding season, this medium-sized plover migrates widely across the Pacific.", iucn: "LC" },
  "corplo": { extract: "The common ringed plover, great ringed plover or ringed plover (Charadrius hiaticula) is a species of bird in the family Charadriidae. It breeds across much of northern Eurasia, as well as Greenland.", iucn: "LC" },
  "lirplo": { extract: "The little ringed plover (Thinornis dubius) is a small plover native to the Old World. It has mostly brown upperparts, a black neckband and a black mask around the eye with a noticeable yellow eyering. Its forehead, belly and the rest of the breast are white. A migratory species, it breeds in open gravel areas near freshwater, including gravel pits, islands and river edges. Its diet consists mainly of insects and worms, which it forages for in muddy areas.", iucn: "LC" },
  "yewlap2": { extract: "The yellow-wattled lapwing (Vanellus malabaricus) is a lapwing that is endemic to the Indian subcontinent. It is found mainly on the dry plains of peninsular India and has a sharp call and is capable of fast flight. Although they do not migrate, they are known to make seasonal movements in response to rains. They are dull grey brown with a black cap, yellow legs and a triangular wattle at the base of the beak. Like other lapwings and plovers, they are ground birds and their nest is a mere collection of tiny pebbles within which their well camouflaged eggs are laid. The chicks are nidifugous, leaving the nest shortly after hatching and following their parents to forage for food.", iucn: "LC" },
  "gyhlap1": { extract: "The grey-headed lapwing (Vanellus cinereus) is a lapwing species which breeds in northeast China and Japan. The mainland population winters in northern Southeast Asia from northeastern India to Cambodia. The Japanese population winters, at least partially, in southern Honshū. This species has occurred as a vagrant in Russia, the Philippines, Indonesia, New South Wales, Australia, Telangana and Sri Lanka, as well as Sweden and England.", iucn: "LC" },
  "rewlap1": { extract: "The red-wattled lapwing (Vanellus indicus) is an Asian lapwing or large plover, a wader in the family Charadriidae. Like other lapwings they are ground birds that are incapable of perching. Their characteristic loud alarm calls are indicators of human or animal movements and the sounds have been variously rendered as did he do it or pity to do it leading to the colloquial name of did-he-do-it bird. Usually seen in pairs or small groups not far from water, they sometimes form large aggregations in the non-breeding season (winter). They nest in a ground scrape laying three to four camouflaged eggs. Adults near the nest fly around, diving at potential predators while calling noisily. The cryptically patterned chicks hatch and immediately follow their parents to feed, hiding by lying low on the ground or in the grass when threatened.", iucn: "LC" },
  "lessap1": { extract: "The Tibetan sand plover (Anarhynchus atrifrons) is a small wader in the plover family of birds, breeds in Pamir Mountains, Tian Shan, Tibetan Plateau and south Mongolia, winters in east and south Africa, south, east and southeast Asia.", iucn: "" },
  "grsplo": { extract: "The greater sand plover (Anarhynchus leschenaultii) is a small wader in the plover family of birds. The spelling is often given as \"greater sandplover\" or \"greater sand-plover\", but the official IOC and British Ornithologists' Union spelling is \"Greater Sand Plover\". The specific leschenaultii commemorates the French botanist Jean Baptiste Leschenault de la Tour. Like most other species in the genus Anarhynchus, it was until recently included in the genus Charadrius.", iucn: "LC" },
  "kenplo1": { extract: "The Kentish plover (Anarhynchus alexandrinus) is a small wader (40–44 g (1.4–1.6 oz)) of the family Charadriidae that breeds on the shores of saline lakes, lagoons, and coasts, populating sand dunes, marshes, semi-arid desert, and tundra. Both male and female birds have pale plumages with a white underside, grey/brown back, dark legs and a dark bill; however, additionally the male birds also exhibit very dark incomplete breast bands, and dark markings either side of their head, therefore the Kentish plover is regarded as sexually dimorphic. The Kentish plover has a large geographical distribution, ranging from latitudes of 10º to 55º, occupying North Africa, both mainland, such as Senegal, and island, such as the Cape Verde archipelago, Central Asia, for example alkaline lakes in China, and Europe, including small populations in Spain and Austria.", iucn: "LC" },
  "grpsni1": { extract: "The greater painted-snipe (Rostratula benghalensis) is a species of wader in the small painted-snipe family Rostratulidae. It widely distributed across Africa and southern Asia and is found in a variety of wetland habitats, including swamps and the edges of larger water bodies such as lakes and rivers. This species is sexually dimorphic with the female being larger and more brightly coloured than the male. The female is normally polyandrous with the males incubating the eggs and caring for the young.", iucn: "LC" },
  "phtjac1": { extract: "The pheasant-tailed jacana (Hydrophasianus chirurgus) is a jacana in the monotypic genus Hydrophasianus. Like all other jacanas, they have elongated toes and nails that enable them to walk on floating vegetation in shallow lakes, their preferred habitat. They may also swim or wade in water reaching their body while foraging mainly for invertebrate prey. They are found in tropical Asia from Yemen in the west to the Philippines in the east and move seasonally in parts of their range. They are the only jacanas that migrate long distances and have different non-breeding and breeding plumages. The pheasant-tailed jacana forages by swimming or by walking on aquatic vegetation. Females are larger than males and are polyandrous, laying several clutches that are raised by different males in their harem.", iucn: "LC" },
  "brwjac1": { extract: "The bronze-winged jacana (Metopidius indicus) is a wader in the family Jacanidae. It is found across South and Southeast Asia and is the sole species in the genus Metopidius. Like other jacanas it forages on lilies and other floating aquatic vegetation, using its long feet and legs for balance. The sexes are alike but females are slightly larger and are polyandrous, maintaining a harem of males during the breeding season in the monsoon rains. Males maintain territories, with one male in the harem chosen to incubate the eggs and take care of the young. When threatened, young chicks may be carried to safety by the male under his wings.", iucn: "LC" },
  "whimbr5": { extract: "The Eurasian whimbrel (Numenius phaeopus), historically known as the white-rumped whimbrel in North America, is a wader in the large family Scolopacidae. It is one of the most widespread of the curlews, breeding across much of subarctic Palearctic region and Europe as far south as Scotland. This species and the Hudsonian whimbrel were split in 2019, although some taxonomic authorities still consider them to be conspecific.", iucn: "LC" },
  "eurcur": { extract: "The Eurasian curlew or common curlew (Numenius arquata) is a very large wader in the family Scolopacidae. It is one of the most widespread of the curlews, breeding across temperate Europe and Asia. In Europe, this species is often referred to just as the \"curlew\", and in Scotland known as the \"whaup\" in Scots.", iucn: "NT" },
  "batgod": { extract: "The bar-tailed godwit (Limosa lapponica) is a large and strongly migratory wader in the family Scolopacidae, which feeds on bristle-worms and shellfish on coastal mudflats and estuaries. It has distinctive red breeding plumage, long legs, and a long upturned bill. Bar-tailed godwits breed on Arctic coasts and tundra from Scandinavia to Alaska, and overwinter on coasts in temperate and tropical regions of Australia and New Zealand. The migration of the subspecies Limosa lapponica baueri across the Pacific Ocean from Alaska to New Zealand is the longest known non-stop flight of any bird, and also the longest journey without pausing to feed by any animal. The round-trip migration for this subspecies is over 29,000 km (18,020 mi).", iucn: "NT" },
  "bktgod": { extract: "The black-tailed godwit (Limosa limosa) is a large, long-legged, long-billed shorebird first described by Carl Linnaeus in 1758. It is a member of the godwit genus, Limosa. There are four subspecies, all with orange head, neck and chest in breeding plumage and dull grey-brown winter coloration, and distinctive black and white wingbar at all times. Its breeding range stretches from Iceland through Europe and areas of central Asia. Black-tailed godwits spend (the northern hemisphere) winter in areas as diverse as the Indian subcontinent, Australia, New Zealand, western Europe and west Africa. The species breeds in fens, lake edges, damp meadows, moorlands and bogs and uses estuaries, swamps and floods in (the northern hemisphere) winter; it is more likely to be found inland and on freshwater than the similar bar-tailed godwit.", iucn: "NT" },
  "jacsni": { extract: "The jack snipe or jacksnipe (Lymnocryptes minimus) is a small stocky wader. It is the smallest snipe, and the only member of the genus Lymnocryptes. Features such as its sternum and its continuous 'bobbing up and down' make it quite distinct from other snipes or woodcocks.", iucn: "LC" },
  "eurwoo": { extract: "The Eurasian woodcock (Scolopax rusticola) is a medium-small wading bird found in temperate and subarctic Eurasia. It has cryptic camouflage to suit its woodland habitat, with reddish-brown upperparts and buff-coloured underparts. Its eyes are set far back on its head to give it 360-degree vision and it probes in the ground for food with its long, sensitive bill, making it vulnerable to cold weather when the ground remains frozen. The male performs a courtship flight known as \"roding\" at dusk in spring. It is widely believed that the female will sometimes carry chicks between her legs whilst flying, though evidence of this is purely anecdotal. The world population is estimated to be 14 million to 16 million birds.", iucn: "LC" },
  "gresni1": { extract: "The great snipe (Gallinago media) is a small stocky wader in the genus Gallinago. This bird's breeding habitat is marshes and wet meadows with short vegetation in northeastern Europe and northern Asia, from Scandinavia and Poland east across northern Russia to western Siberia, and south to northern Kazakhstan. Great snipe are migratory, wintering in tropical Africa. The European breeding population is in steep decline.", iucn: "NT" },
  "swisni1": { extract: "Swinhoe's snipe (Gallinago megala), also known as forest snipe or Chinese snipe, is a medium-sized (length 27–29 cm, wingspan 38–44 cm, weight 120 gm), long-billed, migratory wader. The common name commemorates the British naturalist Robert Swinhoe who first described the species in 1861.", iucn: "LC" },
  "pitsni": { extract: "The pin-tailed snipe or pintail snipe (Gallinago stenura) is a species of bird in the family Scolopacidae, the sandpipers.", iucn: "LC" },
  "comsni": { extract: "The common snipe (Gallinago gallinago, formerly also known as Gallinago cælestis) is a small, stocky wader native to the Old World, where it breeds in marshes, bogs, tundra and wet meadows. It is usually shy and well-camouflaged, foraging in soft mud mainly for insects and earthworms but also some plant material. During courtship, males perform a \"winnowing\" display; flying high in circles and then taking shallow dives to produce a \"drumming\" sound by vibrating the tail feathers.", iucn: "LC" },
  "redpha1": { extract: "The red phalarope or grey phalarope (Phalaropus fulicarius) is a small wader. This phalarope breeds in the Arctic regions of North America and Eurasia. It is migratory, and, unusually for a wader, migrates mainly on oceanic routes, wintering at sea on tropical oceans.", iucn: "LC" },
  "renpha": { extract: "The red-necked phalarope (Phalaropus lobatus), also known as the northern phalarope and hyperborean phalarope, is a small wader. This phalarope breeds in the Arctic regions of North America and Eurasia. It is migratory, and, unusually for a wader, winters at sea on tropical oceans.", iucn: "LC" },
  "tersan": { extract: "The Terek sandpiper (Xenus cinereus) is a small migratory Palearctic wader species and is the only member of the genus Xenus. It is named after the Terek River which flows into the west of the Caspian Sea, as it was first observed around this area.", iucn: "LC" },
  "comsan": { extract: "The common sandpiper (Actitis hypoleucos) is a small Palearctic wader. This bird and its American sister species, the spotted sandpiper (A. macularia), make up the genus Actitis. They are parapatric and replace each other geographically; stray birds of either species may settle down with breeders of the other and hybridize. Hybridization has also been reported between the common sandpiper and the green sandpiper, a member of the closely related genus Tringa.", iucn: "LC" },
  "grnsan": { extract: "The green sandpiper (Tringa ochropus) is a small wader (shorebird) of the Old World. The green sandpiper represents an ancient lineage of the genus Tringa; its only close living relative is the solitary sandpiper (T. solitaria). They both have brown wings with little light dots and a delicate but contrasting neck and chest pattern. In addition, both species nest in trees, unlike most other scolopacids. Given its basal position in Tringa, it is fairly unsurprising that suspected cases of hybridisation between this species and the common sandpiper (A. hypoleucos) of the sister genus Actitis have been reported.", iucn: "LC" },
  "marsan": { extract: "The marsh sandpiper (Tringa stagnatilis) is a small wader. It is a rather small shank, and breeds in open grassy steppe and taiga wetlands from easternmost Europe to the Russian Far East. The genus name Tringa is the Neo-Latin name given to the green sandpiper by Aldrovandus in 1599 based on Ancient Greek trungas, a thrush-sized, white-rumped, tail-bobbing wading bird mentioned by Aristotle. The specific stagnatilis is from Latin stagnum, \"swamp\".", iucn: "LC" },
  "woosan": { extract: "The wood sandpiper (Tringa glareola) is a small wader belonging to the sandpiper family Scolopacidae. A Eurasian species, it is the smallest of the shanks, a genus of mid-sized, long-legged waders that largely inhabit freshwater and wetland environments, as opposed to the maritime or coastal habitats of other, similar species.", iucn: "LC" },
  "comred1": { extract: "The common redshank or simply redshank (Tringa totanus) is a Eurasian wader in the large family Scolopacidae.", iucn: "LC" },
  "spored": { extract: "The spotted redshank (Tringa erythropus) is a wader (shorebird) in the large bird family Scolopacidae. It breeds across northern Scandinavia and the northern Palearctic and migrates south to the Mediterranean, the southern British Isles, France, tropical Africa, and tropical Asia for the winter. It is an occasional vagrant to Australia and North America.", iucn: "LC" },
  "comgre": { extract: "The common greenshank (Tringa nebularia) is a wader in the large family Scolopacidae, the typical waders. The genus name Tringa is the Neo-Latin name given to the green sandpiper by Aldrovandus in 1599 based on Ancient Greek trungas, a thrush-sized, white-rumped, tail-bobbing wading bird mentioned by Aristotle. The specific nebularia is from Latin nebula \"mist\". Like the Norwegian Skoddefoll, this refers to the greenshank's damp marshy habitat.", iucn: "LC" },
  "rudtur": { extract: "The ruddy turnstone (Arenaria interpres) is a small cosmopolitan wading bird, one of two species of turnstone in the genus Arenaria. It is now classified in the sandpiper family Scolopacidae but was formerly sometimes placed in the plover family Charadriidae. It is a highly migratory bird, breeding in northern parts of Eurasia and North America, and flying south to winter on coastlines almost worldwide. It is the only species of turnstone in much of its range and is often known simply as turnstone.", iucn: "NT" },
  "grekno": { extract: "The great knot (Calidris tenuirostris) is a medium-sized wader. It is one of the largest species in the genus Calidris. It is a migratory bird which breeds in eastern Siberia, Russia, and flies to southern Asia and Australia in the northern winter.", iucn: "EN" },
  "ruff": { extract: "The ruff (Calidris pugnax) is a medium-sized wading bird that breeds in marshes and wet meadows across northern Eurasia. This highly gregarious sandpiper is migratory and sometimes forms huge flocks in its winter grounds, which include southern and western Europe, Africa, southern Asia and Australia. The ruff is a long-necked, pot-bellied bird. This species shows marked sexual dimorphism; the male is much larger than the female (the reeve), and has a breeding plumage that includes brightly coloured head tufts, bare orange facial skin, extensive black on the breast, and the large collar of ornamental feathers that inspired this bird's English name. The female and the non-breeding male have grey-brown upperparts and mainly white underparts.", iucn: "LC" },
  "brbsan": { extract: "The broad-billed sandpiper (Calidris falcinellus) is a small wader. The scientific specific name falcinellus is the diminutive from Latin falx, falcis, \"a small sickle\". It was formerly treated in its own monospecific genus Limicola, but this was found to be embedded within the wider genus Calidris, into which it was transferred in 2004. Within the genus Calidris, the broad-billed sandpiper is most closely related to the sharp-tailed sandpiper (C. acuminata). The two subspecies are: C. f. falcinellus – breeds northern Scandinavia, northwest Russia; winters east Africa, Middle East, India C. f. sibirica – breeds central and eastern Siberia; winters southeast Asia", iucn: "VU" },
  "cursan": { extract: "The curlew sandpiper (Calidris ferruginea) is a small wader. It is a long-distance migrant, breeding in the bogs and coastal lowlands of the Siberian Arctic, arriving there in June and staying until August or September. After the breeding season, it migrates south to spend the winter in Africa and along the coasts of Oceania and southern Eurasia, occupying tidal mudflats and saltpans. It has three main plumages that change with maturity and season. The non-breeding plumage shows brown-greyish upperparts and white underparts. The breeding plumage is much more striking, with the entire front tinted a deep rusty colour, more intensely so in males. The first-year bird does not migrate or breed, instead remaining in its overwintering range throughout the breeding season.", iucn: "VU" },
  "temsti": { extract: "Temminck's stint (Calidris temminckii) is a small wader native to the Old World. This bird's common name and Latin binomial commemorate the Dutch naturalist Coenraad Jacob Temminck. The genus name is from Ancient Greek kalidris or skalidris, a term used by Aristotle for some grey-coloured waterside birds. Within the genus Calidris, Temminck's stint is most closely related to the long-toed stint (Calidris subminuta). Temminck's stint is one of the species to which the Agreement on the Conservation of African-Eurasian Migratory Waterbirds (AEWA) applies.", iucn: "LC" },
  "lotsti": { extract: "Calidris is a genus of Arctic-breeding, strongly migratory wading birds in the family Scolopacidae. These birds form huge mixed flocks on coasts and estuaries in winter. They are small to medium-sized sandpipers, long-winged and relatively short-billed; some are difficult to identify because of the similarity between species, and various breeding, non-breeding, juvenile, and moulting plumages. With a few exceptions, they have a fairly stereotypical colour pattern, being brownish above and lighter, usually white or buffy coloured, on much of the underside. They often have a lighter supercilium above brownish cheeks.", iucn: "" },
  "sander": { extract: "The sanderling (Calidris alba) is a small wading bird. It is a circumpolar Arctic breeder, being among the most extreme northern breeding birds in the world, nesting only on the coldest tundra, north of the 5°C July isotherm; in Europe, its southernmost breeding locality is Svalbard, where only a handful (5–15) pairs breed. It is a long-distance migrant, wintering south to South America, western and southern Europe, Africa, and Australia. It is highly gregarious in winter, sometimes forming large flocks on coastal mudflats or sandy beaches. It is somewhat unlike other small sandpipers in appearance, in particular in lacking a hind toe, which has led to the suggestion that it should be placed into a monotypic genus Crocethia.", iucn: "LC" },
  "dunlin": { extract: "The dunlin (Calidris alpina) is a small wader in the genus Calidris. The English name is a dialect form of \"dunling\", first recorded in 1531–1532. It derives from dun, \"dull brown\", with the suffix -ling, meaning a person or thing with the given quality. It is a circumpolar breeder in Arctic or subarctic regions. Birds that breed in western Europe are short-distance migrants largely staying on western and southern European and northwest African coasts; those breeding in far northern Europe and Asia are long-distance migrants, wintering south to Africa, southeast and west Asia. Birds that breed in Alaska and the Canadian Arctic migrate short distances to the Pacific and Atlantic coasts of North America, although those nesting in northern Alaska overwinter in Asia.", iucn: "NT" },
  "litsti": { extract: "The little stint (Calidris minuta) is a very small wader. It breeds in arctic Europe and Asia, and is a long-distance migrant, wintering south to Africa and south Asia. It occasionally is a vagrant to North America and to Australia. The genus name is from Ancient Greek kalidris or skalidris, a term used by Aristotle for some grey-coloured waterside birds. The specific minuta is Latin for \"small.", iucn: "LC" },
  "yelbut1": { extract: "The yellow-legged buttonquail (Turnix tanki) is a buttonquail, one of a small family of birds which resemble, but are unrelated to, the true quails. This family is peculiar in that the females are larger and more colourful than the males and are polyandrous.", iucn: "LC" },
  "barbut1": { extract: "The barred buttonquail or common bustard-quail (Turnix suscitator) is a species of buttonquail, one of a small family (Turnicidae) of birds which resemble, but are not closely related to, the true quails. This species is resident from India across tropical Asia to south China, Indonesia and the Philippines.", iucn: "LC" },
  "craplo1": { extract: "The crab-plover or crab plover (Dromas ardeola) is a coastal wader (shorebird). It is the only member of the genus Dromas and the family Dromadidae. It is unique among waders in making use of ground warmth to aid the incubation of its eggs. The crab-plover is classified in the suborder Lari in a group together with the Glareolidae (pratincoles and coursers), and next most closely related to the Laridae (gulls and terns), rather than to most other waders such as plovers (suborder Charadrii) and sandpipers (suborder Scolopaci).", iucn: "LC" },
  "jercou1": { extract: "Jerdon's courser (Rhinoptilus bitorquatus) is a nocturnal bird belonging to the pratincole and courser family Glareolidae endemic to India. The bird was discovered by the surgeon-naturalist Thomas C. Jerdon in 1848 but not seen again until its rediscovery in 1986. This courser is a restricted-range endemic found locally in India in the Eastern Ghats of Andhra Pradesh. It is currently known only from the Sri Lankamalleswara Wildlife Sanctuary, and Sri Penusila Narasimha Wildlife Sanctuary where it inhabits sparse scrub forest with patches of bare ground.", iucn: "CR" },
  "indcou1": { extract: "The Indian courser (Cursorius coromandelicus) is a species of courser found in mainland South Asia, mainly in the plains bounded by the Ganges and Indus river system. Like other coursers, it is a ground bird that can be found in small groups as they forage for insects in dry open semi-desert country.", iucn: "LC" },
  "smapra1": { extract: "The small pratincole, little pratincole, or small Indian pratincole (Glareola lactea) is a small wader in the pratincole family, Glareolidae.", iucn: "LC" },
  "colpra": { extract: "The collared pratincole (Glareola pratincola), also known as the common pratincole or red-winged pratincole, is a wader in the pratincole family, Glareolidae. As with other pratincoles, it is native to the Old World.", iucn: "LC" },
  "oripra": { extract: "The oriental pratincole (Glareola maldivarum), also known as the grasshopper-bird or swallow-plover, is a wader in the pratincole family, Glareolidae.", iucn: "LC" },
  "lotjae": { extract: "The long-tailed jaeger or long-tailed skua (Stercorarius longicaudus) is a seabird in the skua family Stercorariidae.", iucn: "LC" },
  "parjae": { extract: "The parasitic jaeger or arctic skua (Stercorarius parasiticus), also known as the parasitic skua or arctic jaeger, is a seabird in the skua family Stercorariidae. It is a migratory species breeding in Northern Fennoscandia, Scotland, Iceland, Greenland, Northern Canada, Alaska, and Siberia and wintering across the southern hemisphere. Kleptoparasitism is a major source of food for this species during migration and winter, and is where the name is derived from.", iucn: "LC" },
  "pomjae": { extract: "The pomarine jaeger (Stercorarius pomarinus), pomarine skua, or pomatorhine skua, is a seabird in the skua family Stercorariidae. It is a migrant, wintering at sea in the tropical oceans.", iucn: "LC" },
  "brnsku3": { extract: "The brown skua (Stercorarius antarcticus), also known as the Antarctic skua, Subantarctic skua, southern great skua, southern skua, or hākoakoa (Māori), is a large seabird that breeds in the subantarctic and Antarctic zones and moves farther north when not breeding. Its taxonomy is highly complex and a matter of dispute, with some splitting it into two or three species: Falkland skua (S. antarcticus), Tristan skua (S. hamiltoni), and subantarctic skua (S. lonnbergi). To further confuse, it hybridizes with both the south polar and Chilean skuas, and the entire group has been considered to be a subspecies of the great skua, a species otherwise restricted to the Northern Hemisphere.", iucn: "" },
  "sopsku1": { extract: "The south polar skua (Stercorarius maccormicki) is a large seabird in the skua family, Stercorariidae. An older name for the bird is MacCormick's skua, after explorer and naval surgeon Robert McCormick, who first collected the type specimen. This species and the other large skuas, such as the great skua, are sometimes placed in a separate genus Catharacta.", iucn: "LC" },
  "litgul": { extract: "The little gull (Hydrocoloeus minutus) is a species of gull belonging to the family Laridae which is mainly found in the Palearctic with some small colonies in North America. It breeds on freshwater lakes and marshes, and spends winters at sea. It is the smallest species of gull in the world, and the only species in the monospecific genus Hydrocoloeus.", iucn: "LC" },
  "slbgul1": { extract: "The slender-billed gull (Chroicocephalus genei) is a mid-sized gull which breeds very locally around the Mediterranean and the north of the western Indian Ocean (e.g. Pakistan) on islands and coastal lagoons. Most of the population is somewhat migratory, wintering further south to as far as North Africa and India. A few birds have wandered to western Europe. A vagrant individual was reportedly seen on Antigua, April 24, 1976 (AOU, 2000). The genus name Chroicocephalus is from Ancient Greek khroizo, \"to colour\", and kephale, \"head\". The specific genei commemorates Italian naturalist Giuseppe Gené.", iucn: "" },
  "bkhgul": { extract: "The black-headed gull (Chroicocephalus ridibundus) is a small gull that breeds in much of the Palearctic in Europe and Asia, and also locally in smaller numbers in coastal eastern Canada. Most of the population is migratory and winters further south, but many also remain in the milder areas of northwestern Europe. It was formerly sometimes cited as \"common black-headed gull\" to distinguish it from \"great black-headed gull\" (an old name for Pallas's gull). The genus name Chroicocephalus is from the Ancient Greek words khroizo, \"to colour\", and kephale, \"head\". The specific name ridibundus is Latin for \"laughing\".", iucn: "LC" },
  "bnhgul1": { extract: "The brown-headed gull (Chroicocephalus brunnicephalus) is a small gull which breeds in the high plateaus of central Asia from Tajikistan to Ordos in Inner Mongolia. It is migratory, wintering on the coasts and large inland lakes of the Indian subcontinent. As is the case with many gulls, was traditionally placed in the genus Larus. This gull breeds in colonies in large reedbeds or marshes, or on islands in lakes, nesting on the ground. Like most gulls, it is highly gregarious in winter, both when feeding or in evening roosts. It is not a pelagic species, and is rarely seen at sea far from coasts. This is a bold and opportunist feeder, which will scavenge in towns or take invertebrates in ploughed fields with equal relish. The brown-headed gull is slightly larger than black-headed gull.", iucn: "LC" },
  "gbhgul2": { extract: "Pallas's gull (Ichthyaetus ichthyaetus), also known as the great black-headed gull, is a large bird species. As is the case with many gulls, it has traditionally been placed in the genus Larus. The scientific name is from Ancient Greek. Ichthyaetus is from ikhthus, \"fish\", and aetos, \"eagle\".", iucn: "" },
  "soogul2": { extract: "The sooty gull (Ichthyaetus hemprichii) is a species of gull in the family Laridae, also known as the Aden gull or Hemprich's gull. It is found in Bahrain, Djibouti, Egypt, Eritrea, India, Iran, Israel, Jordan, Kenya, Lebanon, Maldives, Mozambique, Oman, Pakistan, Palestine, Qatar, Saudi Arabia, Somalia, Sri Lanka, Sudan, Tanzania, United Arab Emirates, and Yemen. As is the case with many gulls, it has traditionally been placed in the genus Larus. The sooty gull is named in honour of the German naturalist Wilhelm Hemprich who died in 1825 while on a scientific expedition to Egypt and the Middle East with his friend Christian Gottfried Ehrenberg.", iucn: "LC" },
  "whegul2": { extract: "The white-eyed gull (Ichthyaetus leucophthalmus) is a small gull that is endemic to the Red Sea. Its closest relative is the sooty gull. The species is classed as Least Concern by the IUCN; human pressure and oil pollution are deemed the major threats. As is the case with many gulls, it has traditionally been placed in the genus Larus.", iucn: "" },
  "lbbgul": { extract: "The lesser black-backed gull (Larus fuscus) is a large gull that breeds on the Atlantic and Arctic coasts of Europe. It is migratory, wintering from the British Isles south to West Africa. However, it has increased dramatically in North America, especially along the east coast. Formerly just a winter visitor to North America, it now occurs in large numbers some winters and birds are recorded year-round. However, there is serious concern about decline in many parts of its range. The species is on the UK Amber List because the UK is home to 40 per cent of the European population and more than half of these are found at fewer than ten breeding sites.", iucn: "LC" },
  "indski1": { extract: "The Indian skimmer (Rynchops albicollis) or Indian scissors-bill, is one of the three species that belong to the skimmer genus Rynchops in the family Laridae. They are somewhat tern-like but like other skimmers, have a short upper mandible and the longer lower mandible that is ploughed along the surface of water as the bird flies over the water to pick aquatic prey. It is found in southern Asia, where it is patchily distributed and declining in numbers. They are mainly found in rivers or estuaries. They are very brightly marked in black, white and orange, making them difficult to miss.", iucn: "EN" },
  "brnnod": { extract: "The brown noddy, common noddy or noddy tern (Anous stolidus) is a seabird in the family Laridae. The largest of the noddies, it can be told from the closely related black noddy by its larger size and plumage, which is dark brown rather than black. The brown noddy is a tropical seabird with a worldwide distribution, ranging from Hawaii to the Tuamotu Archipelago and Australia in the Pacific Ocean, from the Red Sea to the Seychelles and Australia in the Indian Ocean and in the Caribbean to Tristan da Cunha in the Atlantic Ocean. The brown noddy is colonial, usually nesting on elevated situations on cliffs or in short trees or shrubs. It only occasionally nests on the ground. A single egg is laid by the female of a pair each breeding season. In India, the brown noddy is protected in the PM Sayeed Marine Birds Conservation Reserve.", iucn: "LC" },
  "lesnod1": { extract: "The lesser noddy (Anous tenuirostris), also known as the sooty noddy, is a seabird in the family Laridae. It is found near the coastlines of Comoros, Kenya, India, Maldives, Mauritius, Seychelles, Somalia, Sri Lanka and United Arab Emirates. The lesser noddy was at one time considered as a subspecies of the black noddy (Anous minutus). The close relationship between the two species was confirmed by a molecular phylogenetic study published in 2016.", iucn: "LC" },
  "sooter1": { extract: "The sooty tern (Onychoprion fuscatus) is a tern in the family Laridae. It is a seabird of the tropical oceans and can fly for years at a time, skimming the sea surface for food, and returning to land only to breed, on islands throughout the equatorial zone.", iucn: "LC" },
  "briter1": { extract: "The bridled tern (Onychoprion anaethetus) is a seabird of the family Laridae. It is a bird of the tropical oceans. The scientific name is from Ancient Greek. The genus comes from onux meaning \"claw\" or \"nail\", and prion, meaning \"saw\". The specific anaethetus means \"senseless, stupid\", in reference to its tameness around humans.", iucn: "LC" },
  "litter1": { extract: "The little tern (Sternula albifrons) is a small seabird of the family Laridae. It is widely distributed breeding on the coasts and inland waterways of Europe, Asia, north and west Africa, and eastern Australia. It winters in the subtropical and tropical oceans as far south as South Africa and Australia.", iucn: "LC" },
  "sauter2": { extract: "Saunders's tern (Sternula saundersi), sometimes known as the black-shafted tern, is a species of bird in the family Laridae. It is sparsely resident along the shores of the north-western Indian Ocean (namely southern Somalia, Arabian Peninsula, Socotra, Pakistan, Andaman and Nicobar Islands and northern Sri Lanka). It is a close relative of the little tern, least tern, yellow-billed tern, and Peruvian tern. In non-breeding plumages, the Saunder's tern and the little tern may be almost indistinguishable. The two have been considered by some to be conspecific.", iucn: "LC" },
  "gubter2": { extract: "The gull-billed tern (Gelochelidon nilotica) is a tern in the family Laridae. It is widely distributed and breeds in scattered localities in Europe, Asia, northwest Africa, and the Americas. The Australian gull-billed tern was previously considered a subspecies.", iucn: "LC" },
  "caster1": { extract: "The Caspian tern (Hydroprogne caspia) is the world's largest species of tern, with a subcosmopolitan but scattered distribution. Despite its extensive range, it is monotypic of its genus, and has no accepted subspecies. The genus name is from Ancient Greek hudro-, \"water-\", and Latin progne, \"swallow\". The specific caspia is from Latin and, like the English name, refers to the Caspian Sea.", iucn: "LC" },
  "whiter2": { extract: "The whiskered tern (Chlidonias hybrida) is a tern in the family Laridae. The genus name is from Ancient Greek khelidonios, \"swallow-like\", from khelidon, \"swallow\". The specific hybridus is Latin for hybrid; Peter Simon Pallas thought it might be a hybrid of white-winged black tern and common tern, writing \"Sterna fissipes [Chlidonias leucopterus] et Hirundine [Sterna hirundo] natam\".", iucn: "LC" },
  "blkter": { extract: "The black tern (Chlidonias niger) is a small tern generally found in or near inland water that breeds in Europe, Western Asia and North America. In winter the birds migrate to coastal areas of Africa and South America.", iucn: "LC" },
  "whwter": { extract: "The white-winged tern or white-winged black tern (Chlidonias leucopterus) is a species of tern in the family Laridae. It is a small species generally found in or near bodies of fresh water across much of the world, including Europe, Africa, Asia, and Australia. The genus name is from Ancient Greek khelidonios, \"swallow-like\", from khelidon, \"swallow\". The name 'white-winged tern' is the standard in most English-speaking countries; in the United Kingdom, this name is also the one used by the formal ornithological recording authorities, but the older alternative 'white-winged black tern' is still frequent in popular use.", iucn: "LC" },
  "rivter1": { extract: "The river tern or Indian river tern (Sterna aurantia) is a tern in the family Laridae, the largest species currently included in the genus Sterna of typical terns. It is a resident breeder along inland rivers from Pakistan east through the Indian subcontinent, to Myanmar, Thailand, and Cambodia, where it is uncommon. Unlike most Sterna terns, it is almost exclusively found on freshwater, rarely venturing even to tidal creeks.", iucn: "VU" },
  "comter": { extract: "The common tern (Sterna hirundo) is a seabird in the family Laridae. This bird has a circumpolar distribution, its four subspecies breeding in temperate and subarctic regions of Europe, Asia and North America. It is strongly migratory, wintering in coastal tropical and subtropical regions. Breeding adults have light grey upperparts, white to very light grey underparts, a black cap, orange-red legs, and a narrow pointed bill. Depending on the subspecies, the bill may be mostly red with a black tip or all black. There are several similar species, including the partly sympatric Arctic tern, which can be separated on plumage details, leg and bill colour, or vocalisations.", iucn: "LC" },
  "whcter1": { extract: "The white-cheeked tern (Sterna repressa) is a species of tern in the family Laridae. It is found around the coasts on the Red Sea, around the Horn of Africa to Kenya, in the Persian Gulf and along the Iranian coast to Pakistan and western India.", iucn: "LC" },
  "blbter1": { extract: "The black-bellied tern (Sterna acuticauda) is a tern found near large rivers in the Indian subcontinent, its range extending from Pakistan, Nepal and India to Myanmar. It has become very scarce in the eastern part of its range and the International Union for Conservation of Nature has assessed its conservation status as being endangered. They have a black belly in the summer and a deep forked tail. They can sometimes resemble whiskered terns (Chlidonias hybrida), but the deeper fork of the tail and the black on the lower belly distinguish them from the shallow fork and black closer to the breast on the whiskered tern. Considering that sequence analysis supports moving the similar black-fronted tern (\"Sterna\" albostriata) into Chlidonias, this species might also be better placed in that genus, but no research has yet been conducted.", iucn: "EN" },
  "santer1": { extract: "The Sandwich tern (Thalasseus sandvicensis) is a tern in the family Laridae. It is very closely related to the lesser crested tern (T. bengalensis), Chinese crested tern (T. bernsteini), Cabot's tern (T. acuflavidus), and elegant tern (T. elegans) and has been known to interbreed with both elegant and lesser crested terns. It breeds in the Palearctic from Europe to the Caspian Sea, and winters in the Mediterranean and on the coasts of Africa, India, and Sri Lanka. The Sandwich tern is a medium-large tern with pale silvery-grey upperparts, white underparts, a yellow-tipped black bill, and a shaggy black crest which becomes less extensive in winter with a white crown. Young birds bear grey and blackish scalloped plumage on their backs and wings. It is a vocal bird. It nests in a ground scrape and lays one to three eggs.", iucn: "LC" },
  "lecter2": { extract: "The lesser crested tern (Thalasseus bengalensis) is a tern in the family Laridae.", iucn: "LC" },
  "grcter1": { extract: "The greater crested tern (Thalasseus bergii), also called crested tern, swift tern, or great crested tern, is a tern in the family Laridae that nests in dense colonies on coastlines and islands in the tropical and subtropical Old World. Its four or five subspecies breed in the area from South Africa around the Indian Ocean to the central Pacific and Australia, all populations dispersing widely from the breeding range after nesting. This large tern is closely related to other species in its genus, but can be distinguished by its darker, battleship-grey upperparts, white forehead even in full breeding plumage, and greenish-tinged yellow (not orange or black) bill colour. The greater crested tern has dark grey upperparts, white underparts, a yellow bill, and a shaggy black crest that recedes in winter.", iucn: "LC" },
  "grefla3": { extract: "The greater flamingo (Phoenicopterus roseus) is the largest and most widespread species of the flamingo family. Common in the Old World, they are found in Northern (coastal) and Sub-Saharan Africa, the Indian subcontinent (south of the Himalayas), Central Asia, the Middle East, the Levant, the Persian Gulf, the Gulf of Aden, the Red Sea, and the Mediterranean countries of Southern Europe.", iucn: "LC" },
  "lesfla1": { extract: "The lesser flamingo (Phoeniconaias minor) is a species of flamingo occurring in sub-Saharan Africa and western India. Birds are occasionally reported from farther north, but these are generally considered vagrants.", iucn: "NT" },
  "litgre1": { extract: "The little grebe (Tachybaptus ruficollis), also known as the dabchick, is a member of the grebe family of water birds. The genus name is from Ancient Greek takhus \"fast\" and bapto \"to sink under\". The specific ruficollis is from Latin rufus \"red\" and Modern Latin -collis, \"-necked\", itself derived from Latin collum \"neck\". At 23 to 29 centimetres (9 to 11+1⁄2 inches) in length it is the smallest European, Asian, and African member of its family. It is commonly found in open bodies of water across most of its range.", iucn: "LC" },
  "rebtro": { extract: "The red-billed tropicbird (Phaethon aethereus) is a tropicbird, one of three closely related species of seabird of tropical oceans. Superficially resembling a tern in appearance, it has mostly white plumage with some black markings on the wings and back, a black mask and, as its common name suggests, a red bill. Most adults have tail streamers that are about two times their body length, with those in males being generally longer than those in females. The red-billed tropicbird itself has three subspecies recognized, including the nominate. The subspecies mesonauta is distinguished from the nominate by the rosy tinge of its fresh plumage, and the subspecies indicus can be differentiated by its smaller size, more restricted mask, and more orange bill. This species ranges across the tropical Atlantic, eastern Pacific, and Indian Oceans.", iucn: "LC" },
  "wispet": { extract: "Wilson's storm petrel (Oceanites oceanicus), also known as Wilson's petrel, is a small seabird of the austral storm petrel family Oceanitidae. It is one of the most abundant bird species in the world and has a circumpolar distribution mainly in the seas of the southern hemisphere but extending northwards during the summer of the northern hemisphere. The world population was estimated in 2022 as stable at 8–20 million birds. In 2010 it had been estimated at 12–30 million. A 1998 book had estimated more than 50 million pairs. The name commemorates the Scottish-American ornithologist Alexander Wilson. The genus name Oceanites refers to the mythical Oceanids, the three thousand daughters of Tethys. The species name is from Latin oceanus, \"ocean\".", iucn: "LC" },
  "wfspet": { extract: "The white-faced storm petrel (Pelagodroma marina), (Māori: takahikare) also known as white-faced petrel or frigate petrel, is a small seabird of the austral storm petrel family Oceanitidae. It is the only member of the monotypic genus Pelagodroma. It is widely distributed across the northern and southern hemisphere, especially around the coastal and open ocean waters of southern Australia, New Zealand, Tristan da Cunha, Cabo Verde, the Canary islands and the Selvagens islands.", iucn: "LC" },
  "swspet": { extract: "Swinhoe's storm petrel or Swinhoe's petrel (Hydrobates monorhis) is a small, all-brown seabird of the storm petrel family Hydrobatidae.", iucn: "NT" },
  "joupet": { extract: "Jouanin's petrel (Bulweria fallax) is a species of seabird in the family Procellariidae. It is found throughout the northwestern Indian Ocean and has also been found in New Zealand. Its natural habitats are open seas and shallow seas. It has been recorded breeding on Socotra, with a known breeding colony on Samhah island. It is threatened by illegal killing.", iucn: "NT" },
  "strshe": { extract: "The streaked shearwater (Calonectris leucomelas) is a species of seabird in the petrel family Procellariidae. It is native to the Western Pacific and ranges from Japan to Australia.", iucn: "NT" },
  "flfshe": { extract: "The flesh-footed shearwater (Ardenna carneipes), also called sable shearwater, is a medium-large shearwater that mainly inhabits the Indo-Pacific. Its plumage is black with pale pinkish feet, and a pale bill with a distinct black tip. Together with the equally light-billed pink-footed shearwater, it forms the Hemipuffinus group, a superspecies which may or may not have an Atlantic relative in the great shearwater. These large shearwaters are among those that have been separated into the genus Ardenna. Recent genetic analysis indicates evidence of strong divergence between Pacific colonies relative to those in South and Western Australia, thought to be explained by philopatry and differences in foraging strategies during the breeding season.", iucn: "NT" },
  "sooshe": { extract: "The sooty shearwater (Ardenna grisea) is a medium-large shearwater in the seabird family Procellariidae. In New Zealand, it is also known by its Māori name tītī, and is harvested by Māori people for muttonbird, like its relatives the wedge-tailed shearwater (A. pacificus) and the Australian short-tailed shearwater (A. tenuirostris).", iucn: "NT" },
  "pershe1": { extract: "The Persian shearwater (Puffinus persicus) is a seabird in the family Procellariidae formerly lumped in with Audubon's shearwater (Puffinus lherminieri).", iucn: "LC" },
  "asiope1": { extract: "The Asian openbill or Asian openbill stork (Anastomus oscitans) is a large wading bird in the stork family Ciconiidae. This distinctive stork is found mainly in the Indian subcontinent and Southeast Asia. It is greyish or white with glossy black wings and tail. Adults have a gap between the arched upper mandible and recurved lower mandible which is thought to be an adaptation that aids in the handling of snails, their main prey. Young birds are born without this gap. Although resident within their range, they make long distance movements in response to weather and food availability.", iucn: "LC" },
  "blasto1": { extract: "The black stork (Ciconia nigra) is a large bird in the stork family Ciconiidae. It was first described by Carl Linnaeus in the 10th edition of his Systema Naturae. Measuring on average 95 to 100 cm (37 to 39 in) from beak tip to end of tail with a 145-to-155 cm (57-to-61 in) wingspan, the adult black stork has mainly black plumage, with white underparts, long red legs and a long pointed red beak. A widespread but uncommon species, it breeds in scattered locations across Europe (predominantly in Portugal and Spain, and central and eastern parts), and east across the Palearctic to the Pacific Ocean. It is a long-distance migrant, with European populations wintering in tropical Sub-Saharan Africa, and Asian populations in the Indian subcontinent.", iucn: "LC" },
  "wonsto1": { extract: "The woolly-necked stork has been split into two species: Asian woolly-necked stork, Ciconia episcopus African woolly-necked stork, Ciconia microscelis", iucn: "" },
  "whisto1": { extract: "The white stork (Ciconia ciconia) is a large bird in the stork family, Ciconiidae. Its plumage is mainly white, with black on the bird's wings. Adults have long red legs and long pointed red beaks, and measure on average 100–115 cm (39–45 in) from beak tip to end of tail, with a 155–215 cm (61–85 in) wingspan. The two subspecies, which differ slightly in size, breed in Europe north to Finland, northwestern Africa, Palearctic east to southern Kazakhstan and southern Africa. The white stork is a long-distance migrant, wintering in Africa from tropical Sub-Saharan Africa to as far south as South Africa, or on the Indian subcontinent. When migrating between Europe and Africa, it avoids crossing the Mediterranean Sea and detours via the Levant in the east or the Strait of Gibraltar in the west, because the air thermals on which it depends for soaring do not form over water.", iucn: "LC" },
  "lesadj1": { extract: "The lesser adjutant (Leptoptilos javanicus) is a large wading bird in the stork family Ciconiidae. Like other members of its genus, it has a bare neck and head. It is however more closely associated with wetland habitats where it is solitary and is less likely to scavenge than the related greater adjutant. It is a widespread species found from India through Southeast Asia.", iucn: "VU" },
  "paisto1": { extract: "The painted stork (Mycteria leucocephala) is a large wader in the stork family. It is found in the wetlands of the plains of tropical Asia south of the Himalayas in the Indian subcontinent and extending into Southeast Asia. Their distinctive pink tertial feathers of the adults give them their name. They forage in flocks in shallow waters along rivers or lakes. They immerse their half open beaks in water and sweep them from side to side and snap up their prey of small fish that are sensed by touch. As they wade along they also stir the water with their feet to flush hiding fish. They nest colonially in trees, often along with other waterbirds. The only sounds they produce are weak moans or bill clattering at the nest. They are not migratory and only make short-distance movements in some parts of their range in response to changes in weather or food availability or for breeding.", iucn: "NT" },
  "lesfri": { extract: "The lesser frigatebird (Fregata ariel) is a seabird of the frigatebird family Fregatidae. Around 75 cm (30 in) in length, it is the smallest species of frigatebird. It occurs over tropical and subtropical waters across the Indian and Pacific Oceans, as well as off the Atlantic coast of Brazil. The lesser frigatebird is a lightly built seabird with brownish-black plumage, long, narrow wings, and a deeply forked tail. The male has a striking red gular sac, which he inflates to attract a mate. The female is slightly larger than the male and has a white breast and belly. Frigatebirds feed on fish taken in flight from the ocean's surface (often flying fish), and sometimes indulge in kleptoparasitism, harassing other birds to force them to regurgitate their food.", iucn: "LC" },
  "chifri1": { extract: "The Christmas frigatebird (Fregata andrewsi) or Christmas Island frigatebird is a seabird of the frigatebird family Fregatidae which is an endemic breeder to Christmas Island in the Indian Ocean. Apart from the Ascension frigatebird, the three other species of frigatebird have much more widely distributed breeding locations. The Christmas frigatebird is a large lightly built seabird with brownish-black plumage, long narrow wings and a deeply forked tail. It has a wingspan of around 2.15 m (7.1 ft). The male has an egg shaped white patch on his belly and a striking red gular sac which he inflates to attract a mate. The female is slightly larger than the male and has a white breast and belly. They feed on fish taken in flight from the ocean's surface (mostly flying fish), and sometimes indulge in kleptoparasitism, harassing other birds to force them to regurgitate their food.", iucn: "VU" },
  "brnboo": { extract: "The brown booby (Sula leucogaster) is a large seabird in the booby and gannet family Sulidae, of which it is one of the most common and widespread species. It has a pantropical range, which overlaps with that of other booby species. The gregarious brown booby commutes and forages at low height over inshore waters. Flocks plunge-dive to take small fish, especially when these are driven near the surface by their predators. They nest only on the ground, and roost on solid objects rather than the water surface.", iucn: "LC" },
  "masboo": { extract: "The masked booby (Sula dactylatra), also called the masked gannet or the blue-faced booby, is a large seabird of the booby and gannet family, Sulidae. First described by the French naturalist René-Primevère Lesson in 1831, the masked booby is one of six species of booby in the genus Sula. It has a typical sulid body shape, with a long pointed yellowish bill, long neck, aerodynamic body, long slender wings and pointed tail. The adult is bright white with black wings, a black tail and a dark face mask; at 75–85 cm (30–33 in) long, it is the largest species of booby. The sexes have similar plumage. This species ranges across tropical oceans, except in the eastern Atlantic and eastern Pacific. In the latter, it is replaced by the Nazca booby (Sula granti), which was formerly regarded as a subspecies of masked booby.", iucn: "LC" },
  "darter2": { extract: "The Oriental darter (Anhinga melanogaster) is a water bird of tropical South Asia and Southeast Asia. It has a long and slender neck with a straight, pointed bill and, like the cormorant, it hunts for fish while its body is submerged in water. It spears a fish underwater, bringing it above the surface, tossing and juggling it before swallowing the fish head first. The body remains submerged as it swims, and the slender neck alone is visible above the water, which accounts for the colloquial name of snakebird. Like the cormorants, it has wettable feathers and it is often found perched on a rock or branch with its wings held open to dry.", iucn: "LC" },
  "litcor1": { extract: "The little cormorant (Microcarbo niger) is a member of the cormorant family of seabirds. Slightly smaller than the Indian cormorant it lacks a peaked head and has a shorter beak. It is widely distributed across the Indian subcontinent and extends east to Java, where it is sometimes called the Javanese cormorant. It forages singly or sometimes in loose groups in lowland freshwater bodies, including small ponds, large lakes, streams and sometimes coastal estuaries. Like other cormorants, it is often found perched on a waterside rock with its wings spread out after coming out of the water. The entire body is black in the breeding season but the plumage is brownish, and the throat has a small whitish patch in the non-breeding season. These birds breed gregariously in trees, often joining other waterbirds at heronries.", iucn: "LC" },
  "grecor": { extract: "The great cormorant (Phalacrocorax carbo), also known as just cormorant in Britain, as black shag or kawau in New Zealand, formerly also known as the great black cormorant across the Northern Hemisphere, the black cormorant in Australia, and the large cormorant in India, is a widespread member of the cormorant family of seabirds. It breeds in much of the Old World, Australasia, and the Atlantic coast of North America.", iucn: "LC" },
  "indcor1": { extract: "The Indian cormorant or Indian shag (Phalacrocorax fuscicollis) is a member of the cormorant family. It is found mainly along the inland waters of the Indian subcontinent but extends west to Sind and east to Thailand and Cambodia. It is a gregarious species that can be easily distinguished from the similar sized little cormorant by its blue eyes, small head with a sloping forehead and a long narrow bill ending in a hooked tip.", iucn: "LC" },
  "gloibi": { extract: "The glossy ibis (Plegadis falcinellus) is a water bird in the order Pelecaniformes and the ibis and spoonbill family Threskiornithidae. The scientific name derives from Ancient Greek plegados and Latin, falcis, both meaning \"sickle\" and referring to the distinctive shape of the bill. The historical name black curlew was used for the glossy ibis in Norfolk at least until the early 19th century, and this name also appears in Anglo-Saxon literature. Yalden and Albarella do not mention this species as occurring in medieval England.", iucn: "LC" },
  "blhibi1": { extract: "The black-headed ibis (Threskiornis melanocephalus), also known as the Oriental white ibis, Indian white ibis, and black-necked ibis, is a species of wading bird of the ibis family Threskiornithidae which breeds in the South and Southeast Asia from India to the west and as far east as Japan. It is the only native ibis species in its range that has an overall white plumage with a black neck and head. The down-curved beak and legs are also black. Though often referred to as a wetland species, the black-headed ibis forages in a range of natural and man-made habitats. This species of ibis nests only during the rainy season.", iucn: "NT" },
  "renibi1": { extract: "The red-naped ibis (Pseudibis papillosa), also known as the Indian black ibis or black ibis, is a species of ibis found in the plains, agriculture fields and cities of the Indian subcontinent. Unlike other ibises in the region it is not found very often in waterbodies and is often found in dry fields, but are attracted more to areas that have more wetlands. It is usually seen in pairs or loose groups and can be identified by the nearly all dark body with a white patch on the shoulder and a bare dark head with a patch of crimson red warty skin on the crown and nape. It has a loud call and is noisy when breeding. It builds its nest most often on the top of a large tree or palm, and an increasing number of pairs are building on cell phone towers and electricity pillion towers.", iucn: "LC" },
  "eurspo1": { extract: "The Eurasian spoonbill (Platalea leucorodia), or common spoonbill, is a wading bird of the ibis and spoonbill family Threskiornithidae, native to Europe, Africa and Asia. The species is partially migratory with the more northerly breeding populations mostly migrating south for the winter.", iucn: "LC" },
  "grebit1": { extract: "The Eurasian bittern or great bittern (Botaurus stellaris) is a wading bird in the bittern subfamily (Botaurinae) of the heron family Ardeidae. There are two subspecies, the northern race (B. s. stellaris) breeding in parts of Europe and across the Palearctic, as well as on the northern coast of Africa, while the southern race (B. s. capensis) is endemic to parts of southern Africa. It is a secretive bird, seldom seen in the open as it prefers to skulk in reed beds and thick vegetation near water bodies. Its presence is apparent in the spring, when the booming call of the male during the breeding season can be heard. It feeds on fish, small mammals, fledgling birds, amphibians, crustaceans and insects. The nest is usually built among reeds at the edge of bodies of water. The female incubates the clutch of eggs and feeds the young chicks, which leave the nest when about two weeks old.", iucn: "LC" },
  "blabit1": { extract: "The black bittern (Botaurus flavicollis) is a bittern of Old World origin, breeding in tropical Asia from Pakistan, India, Bangladesh and Sri Lanka east to China, Indonesia, and Australia. It is mainly resident, but some northern birds migrate short distances. This species was formerly placed in the genus Ixobrychus.", iucn: "LC" },
  "cinbit1": { extract: "The cinnamon bittern (Botaurus cinnamomeus) or chestnut bittern is a small Old World bittern, breeding in tropical and subtropical Asia from India east to China and Indonesia. It is mainly resident, but some northern birds migrate short distances. This species was formerly placed in the genus Ixobrychus.", iucn: "LC" },
  "litbit1": { extract: "The little bittern (Botaurus minutus) is a wading bird in the heron family, Ardeidae. This species was formerly placed in the genus Ixobrychus.", iucn: "LC" },
  "yelbit": { extract: "The yellow bittern (Botaurus sinensis) is a small bittern of Old World origins that breeds in the northern Indian subcontinent, east to the Russian Far East, Japan, and Indonesia. It is mainly a resident bird, but some northern birds migrate short distances. It has been recorded as a vagrant in Alaska.", iucn: "LC" },
  "bcnher": { extract: "The black-crowned night heron (Nycticorax nycticorax) or black-capped night heron, commonly shortened to just night heron in Eurasia, is a medium-sized heron found throughout a large part of the world, including parts of Africa, Asia, Europe, and North and South America. In Australasia it is replaced by the closely related Nankeen night heron (N. caledonicus), with which it has hybridised in the area of contact.", iucn: "LC" },
  "manher1": { extract: "The Malayan night heron (Gorsachius melanolophus), also known as Malaysian night heron and tiger bittern, is a medium-sized heron. It is distributed in southern and eastern Asia.", iucn: "LC" },
  "litegr": { extract: "The little egret (Egretta garzetta) is a species of small heron in the family Ardeidae. It is a white bird with a slender black beak, long black legs and, in the western race, yellow feet. As an aquatic bird, it feeds in shallow water and on land, consuming a variety of small creatures. It breeds colonially, often with other species of water birds, making a platform nest of sticks in a tree, bush or reed bed. A clutch of three to five bluish-green eggs is laid and incubated by both parents for about three weeks. The young fledge at about six weeks of age. It is a polytypic species with two or arguably more subspecies. Its breeding distribution comprises the wetlands, waterways and shorelines of warm temperate to tropical parts of Asia, Africa, Australia, and Europe.", iucn: "LC" },
  "werher": { extract: "The western reef heron (Egretta gularis), also called the western reef egret, is a medium-sized heron found in Africa and parts of Asia, with vagrancy occurring in Europe and the Americas. It has a mainly coastal distribution and occurs in several plumage forms: a slaty-grey plumage which can only be confused with the rather uncommon dark morph of the little egret (Egretta garzetta); a white form which can look very similar to the little egret, although the reef heron's bill tends to be paler and larger; and a black form with a white throat, E. g. gularis, found in West Africa. There are also differences in size, structure and foraging behaviour. There have been suggestions that the species hybridizes with the little egret, and based on this, some authors treat schistacea and gularis as subspecies of Egretta garzetta.", iucn: "LC" },
  "strher1": { extract: "The little heron (Butorides atricapilla) is a small heron, about 44 cm tall. It is mostly sedentary and frequents both fresh and salt water habitats. It is found in the Old World tropics from west Africa to Japan and Australia. The little heron was formerly considered to be conspecific with the striated heron.", iucn: "" },
  "inpher1": { extract: "The Indian pond heron or paddybird (Ardeola grayii) is a small heron. It is of Old World origins, breeding in southern Iran and east to the Indian subcontinent, Burma, and Sri Lanka. They are widespread and common but can be easily missed when they stalk prey at the edge of small water-bodies or even when they roost close to human habitations. They are distinctive when they take off, with bright white wings flashing in contrast to the cryptic streaked olive and brown colours of the body. Their camouflage is so excellent that they can be approached closely before they take to flight, a behaviour which has resulted in folk names and beliefs that the birds are short-sighted or blind.", iucn: "LC" },
  "categr2": { extract: "The eastern cattle egret (Ardea coromanda) is a species of heron (family Ardeidae) found in the tropics, subtropics and warm temperate zones. Formerly, most taxonomic authorities lumped this species and the western cattle egret together (called the cattle egret), but the two cattle egrets are now treated as separate species. Despite the similarities in plumage to the egrets of the genus Egretta, it is more closely related to the herons of Ardea. It is native to southern and eastern Asia, and Australasia. It is a white bird adorned with buff plumes in the breeding season. It nests in colonies, usually near bodies of water and often with other wading birds. The nest is a platform of sticks in trees or shrubs. Eastern cattle egrets exploit drier and open habitats more than other heron species.", iucn: "" },
  "greegr": { extract: "The great egret (Ardea alba), also known as the common egret, large egret, great white egret, or great white heron, is a large, widely distributed egret. The four subspecies are found in Asia, Africa, the Americas, and southern Europe. Recently, it has also been spreading to more northern areas of Europe. Distributed across most of the tropical and warmer temperate regions of the world, it builds tree nests in colonies close to water.", iucn: "LC" },
  "integr1": { extract: "The medium egret (Ardea intermedia), median egret, smaller egret or intermediate egret, is a medium-sized heron. Some taxonomists put the species in the genus Egretta or Mesophoyx. It is a resident breeder in southern and eastern Asia.", iucn: "LC" },
  "graher1": { extract: "The grey heron (Ardea cinerea) is a long-legged wading bird of the heron family, Ardeidae, native throughout temperate Europe and Asia, and also parts of Africa. It is resident in much of its range, but some populations from the more northern parts migrate southwards in autumn. A bird of wetland areas, it can be seen around lakes, rivers, ponds, marshes and on the sea coast. It feeds mostly on aquatic creatures which it catches after standing stationary beside or in the water, or stalking its prey through the shallows. Standing up to 1 metre (3 ft 3 in) tall, adults weigh from 1 to 2 kg (2 to 4 lb). They have a white head and neck with a broad black stripe that extends from the eye to the black crest. The body and wings are grey above and the underparts are greyish-white, with some black on the flanks. The long, sharply pointed beak is pinkish-yellow and the legs are brown.", iucn: "LC" },
  "purher1": { extract: "The purple heron (Ardea purpurea) is a wide-ranging heron species. It breeds in Africa, central and southern Europe, and southern and eastern Palearctic. The Western Palearctic populations migrate between breeding and wintering habitats whereas the African and tropical-Asian populations are primarily sedentary, except for occasional dispersive movements. It is similar in appearance to the more common grey heron but is slightly smaller, more slender and has darker plumage. It is also a more evasive bird, favouring densely vegetated habitats near water, particularly reed beds. It hunts for a range of prey including fish, rodents, frogs and insects, either stalking them or standing waiting in ambush. Purple herons are colonial breeders and build a bulky nest out of dead reeds or sticks close to the water' edge among reeds or in dense vegetation.", iucn: "LC" },
  "grwpel1": { extract: "The great white pelican (Pelecanus onocrotalus), also known as the eastern white pelican (in contrast to the western pelican of the Americas), rosy pelican or simply white pelican, is a bird in the pelican family. It breeds from southeastern Europe through Asia and Africa, in swamps and shallow lakes. The great white pelican has been rated as a species of least concern on the IUCN Red List of Endangered Species (IUCN). It is listed under Appendix I of the Convention on the Conservation of Migratory Species of Wild Animals, Annexure I under the EU Birds Directive on the Conservation of Wild Birds, and Appendix II of the Berne Convention on the Conservation of European Wildlife and Natural Habitats. It is also listed within 108 Special Protection Areas in the European Union. It occurs within 43 Important Bird Areas (IBAs) in its European range.", iucn: "LC" },
  "spbpel1": { extract: "The spot-billed pelican (Pelecanus philippensis) or gray pelican is a member of the pelican family. It breeds in southern Asia from southern Iran across India east to Indonesia. It is a bird of large inland and coastal waters, especially large lakes. At a distance they are difficult to differentiate from other pelicans in the region although it is smaller but at close range the spots on the upper mandible, the lack of bright colours and the greyer plumage are distinctive. In some areas these birds nest in large colonies close to human habitations.", iucn: "NT" },
  "osprey": { extract: "The osprey (; Pandion haliaetus), historically known as sea hawk, river hawk, and fish hawk, is a diurnal, fish-eating bird of prey with a cosmopolitan range. It is a large raptor, reaching more than 60 cm (24 in) in length and a wingspan of 180 cm (71 in). It is brown on the upperparts and predominantly greyish on the head and underparts. The osprey is distributed on all continents except Antarctica, but in South America, it occurs only as a nonbreeding migrant. It lives in a wide variety of habitats and nests in locations near a body of water providing an adequate food supply. It has specialised physical characteristics and unique behaviour in hunting its prey, which consists almost exclusively of fish.", iucn: "LC" },
  "bkskit1": { extract: "The black-winged kite (Elanus caeruleus), also known as the black-shouldered kite (not to be confused with the closely related Australian species of the same name), is a small diurnal bird of prey in the family Accipitridae best known for its habit of hovering over open grasslands in the manner of the much smaller kestrels. This Palearctic and Afrotropical species was sometimes combined with the Australian black-shouldered kite (Elanus axillaris) and the white-tailed kite (Elanus leucurus) of North and South America which together form a superspecies. This kite is distinctive, with long wings; white, grey and black plumage; and owl-like forward-facing eyes with red irises. The owl-like behaviour is even more pronounced in the letter-winged kite (Elanus scriptus), a nocturnal relative in Australia.", iucn: "LC" },
  "egyvul1": { extract: "The Egyptian vulture (Neophron percnopterus), also called the white scavenger vulture or pharaoh's chicken, is a small Old World vulture in the monotypic genus Neophron. It is widely distributed from the Iberian Peninsula, North Africa, West Asia and India. The contrasting underwing pattern and wedge-shaped tail make it distinctive in flight as it soars in thermals during the warmer parts of the day. Egyptian vultures feed mainly on carrion but are opportunistic and will prey on small mammals, birds, and reptiles. They also feed on the eggs of other birds, breaking larger ones by tossing a large pebble onto them. The use of tools is rare in birds and apart from the use of a pebble as a hammer, Egyptian vultures also use twigs to roll up wool for use in their nest.", iucn: "EN" },
  "jerbaz1": { extract: "Jerdon's baza (Aviceda jerdoni) is a moderate sized brown hawk with a thin white-tipped black crest usually held erect. It is found in South-east Asia. It inhabits foothills in the terai and is rarer in evergreen forests and tea estates. The common name and Latin binomial commemorate the surgeon-naturalist Thomas C. Jerdon.", iucn: "LC" },
  "blabaz1": { extract: "The black baza (Aviceda leuphotes) is a small bird of prey found in the forests of Northeast India, the eastern Himalayas, China and Southeast Asia. Many populations are migratory, including those in the Indian region, which winter in the south of the Peninsula and Sri Lanka. Black bazas have short, stout legs and feet with strong talons, and a prominent crest. They are found in dense forest, often in small groups, and can often be found perched on bare branches of tall trees rising above the forest canopy.", iucn: "LC" },
  "euhbuz1": { extract: "The European honey buzzard (Pernis apivorus) is an insectivorous bird of prey in the family Accipitridae breeding in Europe and western Asia, and wintering in Africa.", iucn: "LC" },
  "orihob2": { extract: "The crested honey buzzard (Pernis ptilorhynchus), also known as the Oriental, Asiatic, or Eastern honey buzzard, is a bird of prey in the family Accipitridae, which also includes many other diurnal raptors such as kites, eagles, and harriers. It is a fairly large raptor, larger than the European honey buzzard. The name honey buzzard is derived from their diets, which consist mainly of the larvae of bees and wasps extracted from honey combs. It is sexually dimorphic and has six subspecies. Crested honey buzzards migrate for breeding to Siberia and Japan during the summer. They then spend the winter in Southeast Asia and the Indian subcontinent. They are also a year-round resident in these latter areas. They prefer well-forested areas with open spaces and are found from sea level up to 1,800 m (5,900 ft). The species has several adaptations for its specialist diet.", iucn: "LC" },
  "rehvul1": { extract: "The red-headed vulture (Sarcogyps calvus), also known as the Asian king vulture, Indian black vulture or Pondicherry vulture, is an Old World vulture mainly found in the Indian subcontinent, with small disjunct populations in some parts of Southeast Asia.", iucn: "CR" },
  "cinvul1": { extract: "The cinereous vulture (Aegypius monachus), also known as the black vulture, Eurasian black vulture, and monk vulture, is a very large raptor in the family Accipitridae distributed through much of temperate Eurasia. With a body length of 1.2 m (3 ft 11 in), 3.1 m (10 ft) across the wings and a maximum weight of 12.5 kg (28 lb), it is the largest Old World vulture and largest member of the family Accipitridae. Aegypius monachus is one of the largest birds of prey and it plays an important role in its various ecosystems by eating carcasses, which in turn reduces the spread of diseases. The vultures are constantly exposed to many pathogens because of their eating carrion. A study of the gastric and immune defense systems conducted in 2015 sequenced the bird's entire genome.", iucn: "NT" },
  "himgri1": { extract: "The Himalayan vulture (Gyps himalayensis) or Himalayan griffon vulture is an Old World vulture native to the Himalayas and foothills in North and Northeastern India, as well as the adjacent Tibetan Plateau. After the cinereous vulture (Aegypius monachus), it is the second-largest Old World vulture species, and among the world's largest true raptors. It is listed as Near Threatened on the IUCN Red List. It is not to be confused with the Eurasian griffon vulture (Gyps fulvus), which is a visually similar, sympatric species.", iucn: "NT" },
  "whrvul1": { extract: "The white-rumped vulture (Gyps bengalensis) is an Old World vulture native to South and Southeast Asia. It has been listed as Critically Endangered on the IUCN Red List since 2000, as the population severely declined. White-rumped vultures are threatened by diclofenac poisoning, which kills them by causing kidney failure. As of 2021, the global population was estimated at less than 6,000 mature individuals. In comparison, during the 1980s, the global population was estimated at several million individuals, and it was thought to be \"the most abundant large bird of prey in the world\". It is closely related to the European griffon vulture (Gyps fulvus). At one time it was believed to be closer to the white-backed vulture of Africa and was known as the Oriental white-backed vulture.", iucn: "CR" },
  "indvul1": { extract: "The Indian vulture or long-billed vulture (Gyps indicus) is a bird of prey native to the Indian subcontinent. It is an Old World vulture belonging to the family of Accipitridae. It is a medium-sized vulture with a small, semi-bald head with little feathers, long beak, and wide dark colored wings. It breeds mainly on small cliffs and hilly crags in central India and south India. The Indian vulture is a keystone species that has been listed as Critically Endangered on the IUCN Red List since 2002, as the population has severely declined during the Indian vulture crisis. It is estimated that there are 5,000-15,000 mature individuals in the wild. The main cause of the decline was identified as kidney failure caused by the drug diclofenac, which was commonly given to cattle to reduce joint pain. It is thought that diclofenac poisoned vultures that ate the flesh of dead cattle.", iucn: "CR" },
  "crseag1": { extract: "The crested serpent eagle (Spilornis cheela) is a medium-sized bird of prey that is found in forested habitats across tropical Asia. Within its widespread range across the Indian subcontinent, Southeast Asia and East Asia, there are considerable variations and some authorities prefer to treat several of its subspecies as completely separate species. In the past, several species including the Philippine serpent eagle (S. holospila), Andaman serpent eagle (S. elgini) and South Nicobar serpent eagle (S. klossi) were treated as subspecies of the crested serpent eagle. All members within the species complex have a large-looking head with long feathers on the back, giving them a maned and crested appearance. The face is bare and yellow joining up with the ceres while the powerful feet are unfeathered and heavily scaled.", iucn: "LC" },
  "shteag1": { extract: "The short-toed snake eagle (Circaetus gallicus), also known as the short-toed eagle, is a medium-sized bird of prey in the family Accipitridae, which also includes many other diurnal raptors such as kites, buzzards and harriers. The genus name Circaetus is from the Ancient Greek kirkos, a type of hawk, and aetos, \"eagle\". The specific gallicus means \"of Gallia\".", iucn: "LC" },
  "mouhae2": { extract: "Legge's hawk-eagle (Nisaetus kelaarti) is a bird of prey. Like all eagles, it is in the family Accipitridae. It breeds in the Indian subcontinent, from southern India to Sri Lanka. Its specific name kelaarti honors the physician-zoologist E.F. Kelaart. The English common name honours William Vincent Legge, who described the species in 1878. Legge's hawk-eagle is a medium-sized eagle and fairly large-sized raptor. The typical adult has brown upperparts and pale underparts, with barring on the undersides of the flight feathers and tail. The breast and belly are heavily streaked. The wings are broad with a curved trailing edge, and are held in a shallow V in flight. Sexes are similar, but young birds are often whiter-headed. Legge's hawk-eagle was formerly considered to be a subspecies of the mountain hawk-eagle, but it is smaller and has unstreaked buff underwing coverts.", iucn: "" },
  "y00839": { extract: "The changeable hawk-eagle (Nisaetus cirrhatus) or crested hawk-eagle is a large bird of prey species of the family Accipitridae. More informal or antiquated English common names include the marsh hawk-eagle or Indian crested hawk-eagle. It is a member of the subfamily Aquilinae, with signature feathers, absent in tropical raptors from outside this subfamily, covering the tarsus. It was formerly placed in the genus Spizaetus, but studies pointed to the group being paraphyletic resulting in the Old World members being placed in Nisaetus and separated from the New World species. It is a typical \"hawk-eagle\" in that it is an agile forest-dwelling predator and like many such eagles readily varies its prey selection between birds, mammals or reptiles as well as other vertebrates.", iucn: "LC" },
  "rubeag2": { extract: "The rufous-bellied eagle or rufous-bellied hawk-eagle (Lophotriorchis kienerii) is a bird of prey in the family Accipitridae that is found in the forested regions of tropical Asia. Relatively small for eagles and contrastingly patterned like a falcon, this species was earlier placed in the genus Hieraaetus and sometimes also in the genus Aquila but thought to be distinctive enough to belong to a separate genus.", iucn: "NT" },
  "blaeag1": { extract: "The black eagle (Ictinaetus malaiensis) is a bird of prey. Like all eagles, it is in the family Accipitridae, and it is the only member of the genus Ictinaetus. It soars over forests in the hilly regions of tropical and subtropical South and Southeast Asia, as well as southeastern China, hunting mammals and birds, particularly at their nests. It is easily identified by its widely splayed and long primary \"fingers\", the characteristic silhouette, slow flight and yellow ceres and legs that contrast with the dark feathers.", iucn: "LC" },
  "inseag1": { extract: "The Indian spotted eagle (Clanga hastata) is a large bird of prey native to South Asia. Like all typical eagles, it belongs to the family Accipitridae. The typical eagles are often united with the buteos, sea eagles and other more heavy-set Accipitridae, but more recently it appears as if they are less distinct from the more slender accipitrine hawks.", iucn: "VU" },
  "grseag1": { extract: "The greater spotted eagle (Clanga clanga), also called the spotted eagle, is a large migratory bird of prey in the family Accipitridae. It is a member of the subfamily Aquilinae, commonly known as \"booted eagles\". It was once classified as a member of the genus Aquila, but has been reclassified to the distinct genus Clanga, along with the two other species of spotted eagle. During breeding season, greater spotted eagles are widely distributed across Eastern Europe, parts of Central Europe, central Russia, central Asia and parts of China, along with other isolated areas. During winter, they migrate, primarily to South Asia, Southeast Asia, the Middle East, the upper Mediterranean Basin, and parts of East Africa.", iucn: "VU" },
  "booeag1": { extract: "The booted eagle (Hieraaetus pennatus) is a medium-sized mostly migratory bird of prey with a wide distribution in the Palearctic and southern Asia, wintering in the tropics of Africa and Asia, with a small, disjunct breeding population in south-western Africa. Like all eagles, it belongs to the family Accipitridae.", iucn: "LC" },
  "steeag1": { extract: "The steppe eagle (Aquila nipalensis) is a large bird of prey. Like all eagles, it belongs to the family Accipitridae. The steppe eagle's well-feathered legs illustrate it to be a member of the subfamily Aquilinae, also known as the \"Booted eagles\". This species was once considered to be closely related to the sedentary tawny eagle (Aquila rapax) and the two forms have previously been treated as conspecific. They were split based on pronounced differences in morphology and anatomy; two molecular studies, each based on a very small number of genes, indicate that the species are distinct but disagree over how closely related they are. The Steppe eagle is in many ways a peculiar species of eagle.", iucn: "EN" },
  "impeag1": { extract: "The eastern imperial eagle (Aquila heliaca) is a large bird of prey that breeds in southeastern Europe and extensively through West and Central Asia. Most populations are migratory and winter in northeastern Africa, the Middle East and South and East Asia. Like all eagles, the eastern imperial eagle is a member of the family Accipitridae. Furthermore, its feathered legs mark it as a member of the subfamily Aquilinae. It is a large, dark-colored eagle, with a resemblance to other members of the genus Aquila, but it is usually the darkest species in its range. It is an opportunistic predator that mostly selects smallish mammals as prey but also a fairly large proportion of birds, reptile and other prey types, including carrion.", iucn: "VU" },
  "taweag1": { extract: "The tawny eagle (Aquila rapax) is a large bird of prey. Like all eagles, it belongs to the family Accipitridae. Its heavily feathered legs mark it as a member of the subfamily Aquilinae, also known as booted eagles. Tawny eagles have an extensive but discontinuous breeding range that constitutes much of the African continent as well as the Indian subcontinent, with rare residency in the southern Middle East. Throughout its range, it favours open dry habitats such as semideserts, deserts steppes, or savanna plains. Despite its preference for arid areas, the species seldom occurs in areas where trees are entirely absent. It is a resident breeder which lays one to three eggs in a stick nest most commonly in the crown of a tree.", iucn: "VU" },
  "boneag2": { extract: "Bonelli's eagle (Aquila fasciata) is a large bird of prey. The common name of the bird commemorates the Italian ornithologist and collector Franco Andrea Bonelli. Bonelli is credited with gathering the type specimen, most likely from an exploration of Sardinia. Like all eagles, Bonelli's eagle belongs to the family Accipitridae. Its feathered legs marked it as member of the Aquilinae or booted eagle subfamily. This species breeds from southern Europe, Africa on the montane perimeter of the Sahara Desert, and across the Indian subcontinent to Indonesia. In Eurasia, this species may be found as far west as Portugal and as far east as southeastern China and Thailand. It is usually a resident breeder. Bonelli's eagle often occurs in hilly or mountainous habitats, with rocky walls or crags, from sea level to 1,500 m (4,900 ft).", iucn: "LC" },
  "cregos1": { extract: "The crested goshawk (Lophospiza trivirgata) is a bird of prey in the family Accipitridae that is widely distributed in tropical Asia. It was formerly placed in the genus Accipiter.", iucn: "LC" },
  "besra1": { extract: "The besra (Tachyspiza virgata), also called the besra sparrowhawk, is a bird of prey in the family Accipitridae. It was formerly placed in the genus Accipiter. The name \"besra\" is from the Hindi word for the species. The besra is a widespread resident breeder in dense forests throughout southern Asia, ranging from the Indian subcontinent eastwards across Southeast Asia and into East Asia. It nests in trees, building a new nest each year. It lays 2 to 5 eggs. It is a medium-sized raptor (29 to 36 cm) with short broad wings and a long tail, both adaptations to fast maneuvering through dense vegetation. The normal flight of this species is a characteristic \"flap–flap–glide\". This species is like a darker version of the widespread shikra with darker upperparts, strongly barred underwing, broader gular stripe and thin long legs and toes.", iucn: "LC" },
  "shikra1": { extract: "The shikra (Tachyspiza badia) is a small bird of prey in the family Accipitridae found widely distributed in Asia and Africa where it is also called the little banded goshawk. The African forms may represent a separate species but have usually been considered as subspecies of the shikra. The shikra is very similar in appearance, as well as behavior, at least to some degree, to other species including the Chinese sparrowhawk (Tachyspiza soloensis, formerly Accipiter soloensis), Eurasian goshawk (Astur gentilis) and Eurasian sparrowhawk (Accipiter nisus). They have a sharp two-note call and exhibit the flap-and-glide flight style typical of Tachyspiza and Accipiter hawks. Their calls are imitated by drongos and the common hawk-cuckoo resembles it in plumage. This species was formerly placed in the genus Accipiter.", iucn: "LC" },
  "levspa1": { extract: "The Levant sparrowhawk (Tachyspiza brevipes) is a small bird of prey. It measures 32–38 cm (13–15 in) in length with a wingspan of 65–75 cm (26–30 in). The female is larger than the male, but the difference is not as marked as with Eurasian sparrowhawk. The adult male is blue-grey above, with dark wingtips, and barred reddish below. It breeds in forests from Greece and the Balkans east to southern Russia. It is migratory, wintering from Egypt across to southwestern Iran. It will migrate in large flocks, unlike the more widespread Eurasian sparrowhawk.", iucn: "LC" },
  "eurspa1": { extract: "The Eurasian sparrowhawk (Accipiter nisus), also known as the northern sparrowhawk or simply the sparrowhawk, is a small bird of prey in the family Accipitridae. Adult male Eurasian sparrowhawks have bluish grey upperparts and orange-barred underparts; females and juveniles are brown above with brown barring below. The female is up to 25% larger than the male – one of the greatest size differences between the sexes in any bird species. Though it is a predator which specialises in catching woodland birds, the Eurasian sparrowhawk can be found in any habitat and often hunts garden birds in towns and cities. Males tend to take smaller birds, including tits, finches and sparrows; females catch primarily thrushes and starlings but are capable of killing birds weighing 500 g (18 oz) or more.", iucn: "LC" },
  "wemhar1": { extract: "The western marsh harrier (Circus aeruginosus) is a large harrier, a bird of prey from temperate and subtropical western Eurasia and adjacent Africa. It is also known as the Eurasian marsh harrier. Formerly, a number of relatives were included in C. aeruginosus, which was then known as \"marsh harrier\". The related taxa are now generally considered to be separate species: the eastern marsh harrier (C. spilonotus), the Papuan harrier (C. spilothorax) of eastern Asia and the Wallacea, the swamp harrier (C. approximans) of Australasia and the Madagascar marsh harrier (C. maillardi) of the western Indian Ocean islands. The western marsh harrier is often divided into two subspecies, the widely migratory C. a. aeruginosus which is found across most of its range, and C. a. harterti which is resident all-year in north-west Africa.", iucn: "LC" },
  "easmah1": { extract: "The eastern marsh harrier (Circus spilonotus) is a bird of prey belonging to the marsh harrier group of harriers. It was previously considered to be conspecific with the western marsh harrier (Circus aeruginosus) but is now usually classified as a separate species. It has two subspecies: C. s. spilonotus in eastern Asia and C. s. spilothorax (Papuan harrier, perhaps a separate species) in New Guinea.", iucn: "LC" },
  "norhar1": { extract: "The hen harrier (Circus cyaneus) is a bird of prey. It breeds in open areas such as marshes and grasslands in Eurasia and is migratory, moving further south outside of the breeding season. Birds in milder regions, such as France and Great Britain, may be resident year-round, but the higher altitudes are largely deserted in winter. The species is sexually dimorphic; males are smaller and mostly grey and white with black wingtips, whereas females average larger and are predominantly brown and have buff underparts with brown barring. Both sexes have a white rump patch, although it is more noticeable on females and juveniles. The term \"hen harrier\" refers to its former habit of preying on free-ranging fowl. The northern harrier (Circus hudsonius) was formerly considered to be a subspecies of the hen harrier.", iucn: "LC" },
  "palhar1": { extract: "The pallid harrier (Circus macrourus) is a species of harrier, a bird of prey in the family Accipitridae. It breeds in southern parts of eastern Europe and central Asia and Iran and winters mainly in India and southeast Asia. It is a rare but increasing vagrant to Great Britain and western Europe. In 2017 a pair of pallid harriers nested in a barley field in the Netherlands; they raised four chicks, the first recorded breeding of the species in the country. In 2019, a pair bred in Spain for the first time. This medium-sized raptor breeds on open plains, bogs and heathland. In winter it is a bird of open country.", iucn: "NT" },
  "piehar1": { extract: "The pied harrier (Circus melanoleucos) is a bird of prey in the family Accipitridae, named for the male's distinctive white and black colouration. It is a migratory bird endemic to Asia, ranging roughly from southern Siberia to the Philippines. They are primarily solitary although will sometimes form loose groups. They mostly live in open country and eat small mammals.", iucn: "LC" },
  "monhar1": { extract: "Montagu's harrier (Circus pygargus) is a species of harrier, a bird of prey in the family Accipitridae. It breeds in large open areas in the Palearctic and is migratory, wintering in Africa, the Indian subcontinent and parts of the Arabian Peninsula. Its common name commemorates the British naturalist George Montagu.", iucn: "LC" },
  "blakit1": { extract: "The black kite or fire kite (Milvus migrans) is a medium-sized bird of prey in the family Accipitridae, which also includes many other diurnal raptors. It is thought to be the world's most abundant species of Accipitridae, although some populations have experienced dramatic declines or fluctuations. Current global population estimates run up to 6.7 million individuals. Unlike others of the group, black kites are opportunistic hunters and are more likely to scavenge. They spend much of their time gliding in thermals in search of food. Their angled wing and distinctive forked tail make them easy to identify. They are vociferous with a distinct shrill whinnying call. The black kite is widely distributed through temperate and tropical parts of Eurasia and parts of Australasia and Oceania. Temperate populations tend to be migratory.", iucn: "LC" },
  "brakit1": { extract: "The brahminy kite (Haliastur indus), also known as the red-backed sea-eagle, is a medium-sized bird of prey in the family Accipitridae, which also includes many other diurnal raptors, such as eagles, buzzards, and harriers, found in the Indian subcontinent, Southeast Asia, and Australia. The brahminy kite is found mainly on the coast and in inland wetlands, where it feeds on dead fish and other prey. Adults have a reddish-brown body plumage contrasting with their white head and breast which make them easy to distinguish from other birds of prey.", iucn: "LC" },
  "wbseag1": { extract: "The white-bellied sea eagle (Icthyophaga leucogaster), also known as the white-breasted sea eagle, is a large diurnal bird of prey in the family Accipitridae. Originally described by Johann Friedrich Gmelin in 1788, it is closely related to Sanford's sea eagle of the Solomon Islands, and the two are considered a superspecies. A distinctive bird, the adult white-bellied sea eagle has a white head, breast, under-wing coverts and tail. The upper parts are grey and the black under-wing flight feathers contrast with the white coverts. The tail is short and wedge-shaped as in all Haliaeetinae species. Like many raptors, the female is larger than the male, and can measure up to 90 cm (35 in) long with a wingspan of up to 2.2 m (7.2 ft), and weigh 4.5 kg (9.9 lb). Immature birds have brown plumage, which is gradually replaced by white until the age of five or six years.", iucn: "LC" },
  "lefeag1": { extract: "The lesser fish eagle (Icthyophaga humilis) is a species of Icthyophaga found in the Indian subcontinent, primarily in the foothills of the Himalayas, and south-east Asia. There are records from Gujarat, Central India and in more recent times from the Kaveri river valley in southern India, although the south Indian records are now thought to come from an isolated population, disjunct from the species' normal range. Some taxonomic authorities place this species in the genus Icthyophaga. Others place it in the genus Haliaeetus. Lesser fish eagles are fish-eating birds that have feet adapted to aid in gripping slippery fish. They have strongly curved talons, and spicules along the underside of the birds' toes help to grip fish as they pull them from the water.", iucn: "NT" },
  "gyhfie1": { extract: "The grey-headed fish eagle (Icthyophaga ichthyaetus) is a fish-eating bird of prey from Southeast Asia. It is a large stocky raptor with adults having dark brown upper body, grey head and lighter underbelly and white legs. Juveniles are paler with darker streaking. It is often confused with the lesser fish eagle (Icthyophaga humilis) and the Pallas's fish eagle. The lesser fish eagle is similar in plumage but smaller and the Pallas's fish eagle shares the same habitat and feeding behaviour but is larger with longer wings and darker underparts. Is often called tank eagle in Sri Lanka due to its fondness for irrigation tanks.", iucn: "NT" },
  "whebuz1": { extract: "The white-eyed buzzard (Butastur teesa) is a medium-sized hawk, distinct from the true buzzards in the genus Buteo, found in South Asia. Adults have a rufous tail, a distinctive white iris, and a white throat bearing a dark mesial stripe bordered. The head is brown and the median coverts of the upper wing are pale. They lack the typical carpal patches on the underside of the wings seen in true buzzards, but the entire wing lining appears dark in contrast to the flight feathers. They sit upright on perches for prolonged periods and soar on thermals in search of insect and small vertebrate prey. They are vociferous in the breeding season, and several birds may be heard calling as they soar together.", iucn: "LC" },
  "combuz1": { extract: "The common buzzard (Buteo buteo) is a medium-sized bird of prey with a large range. It is a member of the genus Buteo in the family Accipitridae. The species lives in most of Europe and extends its breeding range across much of the Palearctic as far as northwestern China (Tian Shan), far western Siberia and northwestern Mongolia. Over much of its range, it is a year-round resident. However, buzzards from the colder parts of the Northern Hemisphere as well as those that breed in the eastern part of their range typically migrate south for the northern winter, many journeying as far as South Africa. The common buzzard is an opportunistic predator that can take a wide variety of prey, but it feeds mostly on small mammals, especially rodents such as voles. It typically hunts from a perch.", iucn: "LC" },
  "lolbuz1": { extract: "The long-legged buzzard (Buteo rufinus) is a bird of prey found widely in several parts of Eurasia and in North Africa. This species ranges from Southeastern Europe down to East Africa to the northern part of the Indian subcontinent. The long-legged buzzard is a member of the genus Buteo, being one of the larger species therein. This species is simultaneously considered relatively powerful and aggressive for its taxonomic group as well as a relatively sluggish raptor overall. Like most buzzards, it prefers small mammals such as rodents, including gerbils, ground squirrels, voles and rats, also taking reptiles, birds and insects as well as carrion. Adaptable to a variety of habitats, long-legged buzzards may nest on a variety of surfaces, including rocks, cliffs and trees. It is a typical buzzard in its reproductive biology.", iucn: "LC" },
  "combuz9": { extract: "The Himalayan buzzard (Buteo refectus) is a medium to large bird of prey that was formerly considered a subspecies of the widespread common buzzard (Buteo buteo). It is native to the Himalayas in Nepal, India and adjacent mountains of southern China. It was formerly given the scientific name Buteo burmanicus, but this name is now known to have been previously applied to the migratory mainland Asian subspecies of the eastern buzzard (B. japonicus burmanicus), and the Himalayan buzzard was thus renamed Buteo refectus.", iucn: "LC" },
  "eabowl1": { extract: "The Eastern barn owl (Tyto javanica) is usually considered a subspecies group and together with the American barn owl group, the western barn owl group, and sometimes the Andaman masked owl make up the genus Tyto. The cosmopolitan barn owl is recognized by most taxonomic authorities. A few (including the International Ornithologists' Union) separate them into distinct species, as is done here. The eastern barn owl is native to southeastern Asia, New Zealand, and Australasia. The eastern barn owl is nocturnal over most of its range, but in some Pacific islands, it also hunts by day. They specialise in hunting animals on the ground, and nearly all of their food consists of small mammals which they locate by sound, their hearing being very acute. They mate for life unless one of the pair is killed, after which a new pair bond may be formed.", iucn: "" },
  "srlbao1": { extract: "The Sri Lanka bay owl (Phodilus assimilis) is a species of bay owl in the family Tytonidae. It is endemic to the island of Sri Lanka and the Western Ghats in Kerala, South Western India. It was considered a subspecies of the Oriental bay owl (Phodilus badius) but is now treated as a full species due to its distinctive call, plumage and disjunct distribution. Its natural habitats are subtropical or tropical moist montane forests and subtropical or tropical high-altitude grassland. It is threatened by habitat loss.", iucn: "LC" },
  "insowl1": { extract: "The Indian scops owl (Otus bakkamoena) is a species of owl native to South Asia.", iucn: "LC" },
  "pasowl3": { extract: "The pallid scops owl (Otus brucei) is a small scops owl ranging from the Middle East to west and central Asia, sometimes called the striated scops owl.", iucn: "LC" },
  "orsowl": { extract: "The oriental scops owl (Otus sunia) is a scops owl species native to South and Southeast Asia.", iucn: "LC" },
  "roeowl1": { extract: "The Indian eagle-owl (Bubo bengalensis), or the Bengal eagle-owl or rock eagle-owl, is a large horned owl species native to hilly and rocky scrub forests in the Indian subcontinent. It is splashed with brown and grey, and has a white throat patch with black small stripes. It was earlier treated as a subspecies of the Eurasian eagle-owl. It is usually seen in pairs. It has a deep resonant booming call that may be heard at dawn and dusk.", iucn: "LC" },
  "brfowl1": { extract: "The brown fish owl (Ketupa zeylonensis) is a fish owl species in the family known as typical owls, Strigidae. It is native from Turkey to South and Southeast Asia. Due its wide distribution it is listed as Least Concern on the IUCN Red List. It inhabits forests and wooded wetlands. Of the four living species of fish owl, it is the most widely distributed, most common and best-studied. It occupies a range of over 7,000 km (4,300 mi).", iucn: "LC" },
  "sbeowl1": { extract: "The spot-bellied eagle-owl (Ketupa nipalensis), also known as the forest eagle-owl, is a large bird of prey with a formidable appearance. It is a forest-inhabiting species found in the Indian subcontinent and Southeast Asia. This species is considered part of a superspecies with the barred eagle-owl (Ketupa sumatrana), which looks quite similar but is allopatric in distribution.", iucn: "LC" },
  "junowl1": { extract: "The jungle owlet (Glaucidium radiatum) or barred jungle owlet is native to the Indian Subcontinent. The species is often found singly, in pairs or small groups, and they are usually detected by their calls at dawn and dusk. There are two subspecies, with that found in the Western Ghats sometimes considered a full species.", iucn: "LC" },
  "spoowl1": { extract: "The spotted owlet (Athene brama) is a small owl which breeds in tropical Asia from North Pakistan to Southeast Asia. A common resident of open habitats including farmland and human habitation, it has adapted to living in cities. They roost in small groups in the hollows of trees or in cavities in rocks and buildings. It nests in a hole in a tree or building, laying 3–5 eggs. The species shows great variation including clinal variation in size and forms a superspecies with the very similar little owl.", iucn: "LC" },
  "mowowl1": { extract: "The mottled wood owl (Strix ocellata) is a species of large owl found in India and Nepal. They are found in gardens and thin deciduous forests adjacent to dry thorn forests or farmland. They are easily detected by their distinctive tremulous, eerie calls at dawn and dusk. The characteristic call is a duet of the male and female, while other notes include a low hoot and a screech. Their large size, lack of \"ear\" tufts and the concentric barring on the face make them easy to identify.", iucn: "LC" },
  "brwowl1": { extract: "The brown wood owl (Strix leptogrammica) is found in India, Bangladesh, Sri Lanka, Indonesia, Taiwan, and south China. The brown wood owl is a resident breeder in south Asia. This species is a part of the family of owls known as typical owls (Strigidae), which contains most species of owl. It belongs to the earless owl genus Strix. The brown wood owl is medium large (45–57 cm), with upperparts uniformly dark brown, with faint white spotting on the shoulders. The underparts are buff with brown streaking. The facial disc is brown or rufous, edged with white and without concentric barring, and the eyes are dark brown. There is a white neckband. The sexes are similar in appearance. Their call is a (hoo) hoo hoo HOO, or a deep goke-goke-ga-LOOO, or a loud scream. Their alarm call is a bark, wow-wow.", iucn: "LC" },
  "sheowl": { extract: "The short-eared owl (Asio flammeus) is a widespread grassland species in the family Strigidae. Owls belonging to genus Asio are known as the eared owls, as they have tufts of feathers resembling mammalian ears. These \"ear\" tufts may or may not be visible. The short-eared owl will display its tufts when in a defensive pose, although its very short tufts are usually not visible. The short-eared owl is found in open country and grasslands.", iucn: "LC" },
  "brnhao1": { extract: "The brown boobook (Ninox scutulata), also known as the brown hawk-owl, is a typical owl species. It has dark brown upperparts, whitish underparts with reddish-brown streaking, and a barred tail. It is a resident breeder in India, Nepal, Bangladesh, Bhutan, Sri Lanka, southern China and western Indonesia.", iucn: "LC" },
  "maltro1": { extract: "The Malabar trogon (Harpactes fasciatus) is a species of bird in the trogon family. It is found in the forests of India and Sri Lanka. In India, it is mainly found in the Western Ghats, hill forests of central India and in parts of the Eastern Ghats. They are insectivorous and although not migratory, may move seasonally in response to rain in hill forest regions. Like in other trogons, males and females vary in plumage. The birds utter low, guttural calls that can be heard only at close quarters, and perch still on a branch under the forest canopy, often facing away from the viewer, making them easy to miss despite their colourful plumage.", iucn: "LC" },
  "hoopoe": { extract: "The Eurasian hoopoe or common hoopoe (Upupa epops) is the most widespread species of hoopoe. It is a distinctive cinnamon coloured bird with black and white wings, a tall erectile crest, a broad white band across a black tail, and a long narrow downcurved bill. Its call is a soft \"oop-oop-oop\". The Eurasian hoopoe is native to Europe, Asia and Africa. It is migratory in the northern part of its range. Some ornithologists consider the Madagascar hoopoe (U. marginata) as a subspecies. The African hoopoe, subspecies U. e. africana, has sometimes been treated as a separate species.", iucn: "LC" },
  "grehor1": { extract: "The great hornbill (Buceros bicornis), also known as the concave-casqued hornbill, great Indian hornbill or great pied hornbill, is one of the larger members of the hornbill family. It occurs in the Indian subcontinent and Southeast Asia. It is predominantly frugivorous, but also preys on small mammals, reptiles, and birds. It has been listed as Vulnerable on the IUCN Red List since 2018. It is known to have lived for nearly 50 years in captivity. Due to its large size and colour, and importance in many tribal cultures and rituals, the Government of Kerala declared it as the official Kerala state bird. It is also the state bird of Arunachal Pradesh.", iucn: "VU" },
  "inghor2": { extract: "The Indian gray hornbill (Ocyceros birostris) is a common hornbill found on the Indian subcontinent. It is mostly arboreal and is commonly sighted in pairs. It has grey feathers all over the body with a light grey or dull white belly. The horn is black or dark grey with a casque extending to the point of curvature of the horn. It is one of the few hornbill species found in urban areas in many cities where they are able to make use of large trees in avenues.", iucn: "LC" },
  "maghor2": { extract: "The Malabar gray hornbill (Ocyceros griseus) is a hornbill endemic to the Western Ghats and associated hills of southern India. They have a large beak but lack the casque that is prominent in some other hornbill species. They are found mainly in dense forest and around rubber, arecanut or coffee plantations. They move around in pairs or small groups, feeding on figs and other forest fruits. Their loud cackling and laughing call makes them familiar to people living in the region.", iucn: "VU" },
  "maphor1": { extract: "The Malabar pied hornbill (Anthracoceros coronatus), also known as the lesser pied hornbill, is a bird in the hornbill family, a family of tropical near-passerine birds found in the Old World.", iucn: "NT" },
  "bbbeat1": { extract: "The blue-bearded bee-eater (Nyctyornis athertoni) is a species of bee-eater found in much of the Indian subcontinent and parts of Southeast Asia. This bee-eater is found in forest clearings. It is found mainly in the Malayan region but extends west into peninsular India. The blue feathers of its throat are elongated and often fluffed giving it its name. They have a loud call but are not as gregarious or active as the smaller bee-eaters, and their square ended tail lacks the typical \"wires\" made up of the shafts of the longer central tail feathers found in many other bee-eaters.", iucn: "LC" },
  "grnbee3": { extract: "The Asian green bee-eater (Merops orientalis), also known as the little green bee-eater, and just green bee-eater, is a bird species in the bee-eater family. It is resident or with short-distance seasonal movements, and is found widely distributed across Asia from coastal southern Iran east through the Indian subcontinent to Vietnam. Populations in Africa and the Arabian Peninsula that were formerly assigned to this species (under the name green bee-eater) are now considered to be distinct species, the African green bee-eater and the Arabian green bee-eater. They are mainly insect eaters and they are found in grassland, thin scrub and forest often quite far from water. Several regional plumage variations are known and several subspecies have been named.", iucn: "LC" },
  "bcbeat1": { extract: "The blue-cheeked bee-eater (Merops persicus) is a species of bee-eater that breeds in Northern Africa and the Middle East from eastern Turkey to Kazakhstan and India. It is generally strongly migratory, wintering in tropical Africa, although some populations are resident year-round in the Sahel. This species occurs as a rare vagrant north of its breeding range, with most vagrants occurring in Italy and Greece.", iucn: "LC" },
  "btbeat1": { extract: "The blue-tailed bee-eater (Merops philippinus) is a bee-eater species mostly seen in open habitats close to water. It is widely distributed across South and Southeast Asia where many populations are strongly migratory, and seen seasonally in many parts but breeding colonially in small areas across their range, mostly in river valleys, where they nest by tunneling into loamy sand banks.", iucn: "LC" },
  "eubeat1": { extract: "The European bee-eater (Merops apiaster) is a bird species in the bee-eater family, Meropidae. It has the largest range of any bee-eater species. It breeds in southern and central Europe, northern and southern Africa, and western Asia. Except for the resident southern African population, the species is strongly migratory, wintering in tropical Africa. This species occurs as a spring overshoot north of its usual range, with occasional breeding in northern Europe.", iucn: "LC" },
  "chbeat1": { extract: "The chestnut-headed bee-eater (Merops leschenaulti), or bay-headed bee-eater, is a bird in the bee-eater family Meropidae. It breeds on the Indian subcontinent and adjoining regions, ranging from India, Bangladesh and Sri Lanka across Southeast Asia to Indonesia. This species, like other bee-eaters, is a richly coloured, slender bird. It is predominantly green, with blue on the rump and lower belly. Its face and throat are yellow with a black eye stripe, and the crown and nape are rich chestnut. The thin curved bill is black. Sexes are alike, but young birds are duller. It is 18–20 cm long and lacks the two elongated central tail feathers possessed by most of its relatives.", iucn: "LC" },
  "comkin1": { extract: "The common kingfisher (Alcedo atthis), also known as the Eurasian kingfisher and river kingfisher, is a small kingfisher with seven subspecies recognized within its wide distribution across Eurasia and North Africa. It is resident in much of its range, but migrates from areas where rivers freeze in winter. This sparrow-sized bird has the typical short-tailed, large-headed kingfisher profile; it has blue upperparts, orange underparts and a long bill. It feeds mainly on fish, caught by diving, and has special visual adaptations to enable it to see prey under water. The glossy white eggs are laid in a nest at the end of a burrow in a riverbank.", iucn: "LC" },
  "blekin1": { extract: "The blue-eared kingfisher (Alcedo meninting) is found in Asia, ranging across the Indian subcontinent and Southeast Asia. It is found mainly in dense shaded forests where it hunts in small streams. It is darker crowned, with darker rufous underparts and lacking the rufous ear stripe of the common kingfisher (Alcedo atthis) which is found in more open habitats. A number of subspecies have been described that differ in measurement and colour shade. Adult males have an all dark bill while females have a reddish lower mandible.", iucn: "LC" },
  "bkbkin1": { extract: "The black-backed dwarf kingfisher (Ceyx erithaca), also known as the three-toed kingfisher, is a pocket-sized bird in the family Alcedinidae. It was formerly considered as conspecific with the rufous-backed dwarf kingfisher and together the species complex was known by the English name \"oriental dwarf kingfisher\". This tropical kingfisher is a partial migrant that is endemic to parts of the Indian Subcontinent and Mainland Southeast Asia. It resides in lowland forests, typically near streams or ponds, where it feeds upon insects, spiders, worms, crabs, fish, frogs, and lizards. It is easily distinguishable from other birds in its range due to its red bill, yellow-orange underparts, lilac-rufous upperparts, and blue-black back.", iucn: "NT" },
  "stbkin1": { extract: "The stork-billed kingfisher (Pelargopsis capensis), is a tree kingfisher which is widely but sparsely distributed in the tropical Indian subcontinent and Southeast Asia, from India to Indonesia. These kingfishers are large and have a heavy bill. The head is brown and the chin is paler coloured. The sexes are similar in coloration. This is found mostly in streams and ponds in lowland areas with tree cover. This kingfisher is sendentary throughout its range.", iucn: "LC" },
  "whtkin2": { extract: "The white-throated kingfisher (Halcyon smyrnensis) also known as the white-breasted kingfisher is a tree kingfisher, widely distributed in Asia from the Sinai east through the Indian subcontinent to China and Indonesia. This kingfisher is a resident over much of its range, although some populations may make short distance movements. It can often be found well away from water where it feeds on a wide range of prey that includes small reptiles, amphibians, crabs, small rodents and even birds. During the breeding season they call loudly in the mornings from prominent perches including the tops of buildings in urban areas or on wires.", iucn: "LC" },
  "blckin1": { extract: "The black-capped kingfisher (Halcyon pileata) is a tree kingfisher which is widely distributed in tropical Asia from India east to China, Korea and Southeast Asia. This most northerly of the tree kingfishers is resident over much of its range, but northern populations are migratory, wintering south of their range in Sri Lanka, Thailand, Borneo and Java. It is distinctive in having a black cap that contrasts with the whitish throat, purple-blue wings and the coral red bill. The species is mainly found in coastal and mangrove habitats but can sometimes be found far inland.", iucn: "VU" },
  "piekin1": { extract: "The pied kingfisher (Ceryle rudis) is a species of water kingfisher widely distributed across Africa and Asia. Originally described by Carl Linnaeus in 1758, it has five recognised subspecies, and is the only member of the genus Ceryle. Its black-and white-plumage and crest, as well as its habit of hovering over clear lakes and rivers before diving for fish, make it distinctive. Males have a double band across the breast, while females have a single broken breast band. They are usually found in pairs or small family groups. When perched, they often bob their heads and flick up their tails.", iucn: "LC" },
  "eurrol1": { extract: "The European roller (Coracias garrulus) is the only member of the roller family Coraciidae breeding in Europe. Its range extends into the Maghreb, West Asia and Central Asia. It winters in southern Africa, primarily in dry wooded savanna and bushy plains. It occurs in a wide variety of habitats, but avoids treeless plains. It usually nests in tree holes.", iucn: "LC" },
  "indrol2": { extract: "The Indian roller (Coracias benghalensis) is a bird of the family Coraciidae. It is 30–34 cm (12–13 in) long with a wingspan of 65–74 cm (26–29 in) and weighs 166–176 g (5.9–6.2 oz). The face and throat are pinkish, the head and back are brown, with blue on the rump and contrasting light and dark blue on the wings and tail. The bright blue markings on the wing are prominent in flight. The sexes are similar in appearance. Two subspecies are recognised. The Indian roller occurs widely from West Asia to the Indian subcontinent. Often found perched on roadside trees and wires, it is common in open grassland and scrub forest habitats, and has adapted well to human-modified landscapes. It mainly feeds on insects, especially beetles. The species is best known for the aerobatic displays of males during the breeding season. Adult males and females form pair bonds and raise the young together.", iucn: "LC" },
  "dollar1": { extract: "The Oriental dollarbird (Eurystomus orientalis) is a bird of the roller family, so named because of the distinctive pale blue or white, coin-shaped spots on its wings. It can be found from Australia to Korea, Japan and India.", iucn: "LC" },
  "crfbar1": { extract: "The Malabar barbet (Psilopogon malabaricus) is an Asian barbet native to the Western Ghats in India. It was formerly treated as a race of the crimson-fronted barbet (Psilopogon rubricapillus). It overlaps in some places with the range of the coppersmith barbet (Psilopogon haemacephala) and has a similar but more rapid call.", iucn: "LC" },
  "copbar1": { extract: "The coppersmith barbet (Psilopogon haemacephalus), also called crimson-breasted barbet and coppersmith, is an Asian barbet with crimson forehead and throat, known for its metronomic call that sounds similar to a coppersmith striking metal with a hammer. It is a resident bird in the Indian subcontinent and parts of Southeast Asia. It carves out holes inside a tree to build its nest. It is predominantly frugivorous, but has been observed eating insects, especially winged termites.", iucn: "LC" },
  "brhbar1": { extract: "The brown-headed barbet (Psilopogon zeylanicus) is an Asian barbet species native to the Indian subcontinent, where it inhabits tropical and subtropical moist broadleaf forests.", iucn: "LC" },
  "whcbar1": { extract: "The white-cheeked barbet or small green barbet (Psilopogon viridis) is a species of Asian barbet found in southern India. It is very similar to the more widespread brown-headed barbet (or large green barbet, Psilopogon zeylanicus), but this species has a distinctive supercilium and a broad white cheek stripe below the eye and is found in the forest areas of the Western Ghats, parts of the Eastern Ghats and adjoining hills. The brown-headed barbet has an orange eye-ring but the calls are very similar and the two species occur together in some of the drier forests to the east of the Western Ghats. Like all other Asian barbets, they are mainly frugivorous (although they may sometimes eat insects), and use their bills to excavate nest cavities in trees.", iucn: "LC" },
  "eurwry": { extract: "The Eurasian wryneck or northern wryneck (Jynx torquilla) is a species of wryneck in the woodpecker family. It mainly breeds in temperate regions of Europe and Asia. Most populations are migratory, wintering in tropical Africa and in southern Asia from Iran to the Indian subcontinent, but some are resident in northwestern Africa. It is a bird of open countryside, woodland and orchards. Eurasian wrynecks measure about 16–18 cm (6.3–7.1 in) in length and have bills shorter and less dagger-like than those of other woodpeckers. Their upperparts are barred and mottled in shades of pale brown with rufous and blackish bars and wider black streaks. Their underparts are cream speckled and spotted with brown. Their chief prey is ants and other insects, which they find in decaying wood or on the ground.", iucn: "LC" },
  "spepic1": { extract: "The speckled piculet (Picumnus innominatus) is a species of bird in the family Picidae. It is found in India, China and Southeast Asia.", iucn: "LC" },
  "heswoo1": { extract: "The heart-spotted woodpecker (Hemicircus canente) is a species of bird in the woodpecker family. It has a contrasting black and white plumage, a distinctively stubby body and a large wedge-shaped head making it easy to identify while its frequent calling make it easy to detect as it forage for invertebrates under the bark of the slender outer branches of trees. They move about in pairs or small groups and are often found in mixed-species foraging flocks. They have a wide distribution across Asia with populations in the forests of southwestern and central India which are slightly separated from their ranges in the Himalayas and Southeast Asia.", iucn: "LC" },
  "bncwoo3": { extract: "The brown-capped pygmy woodpecker or Indian pygmy woodpecker (Yungipicus nanus) is a species of very small woodpecker found in Nepal, India and Sri Lanka. Some taxonomic authorities continue to place this species in the genus Dendrocopos or Picoides. This species is non-migratory and often spotted in pairs or small family groups. They are known for being very active and are not often spotted, despite their constant foraging in the tree canopy.", iucn: "" },
  "yecwoo1": { extract: "The yellow-crowned woodpecker (Leiopicus mahrattensis) or Mahratta woodpecker is a species of small pied woodpecker found in the Indian subcontinent. It is the only species placed in the genus Leiopicus.", iucn: "LC" },
  "grefla4": { extract: "The Malabar flameback (Chrysocolaptes socialis) is a species of bird in the woodpecker family Picidae. It is endemic to the Western Ghats of India. It was previously considered a subspecies of the greater flameback (C. guttacristatus), but was split as a distinct species by the International Ornithological Congress in 2022 based on a 2021 study noting differences in plumage and vocalizations between both species.", iucn: "" },
  "whnwoo1": { extract: "The white-naped woodpecker (Chrysocolaptes festivus) is woodpecker which is a widespread but a scarce breeder in the Indian subcontinent. It is associated with open forest and scrub with some trees. It nests in a tree hole, laying one or two white eggs.", iucn: "LC" },
  "rufwoo2": { extract: "The rufous woodpecker (Micropternus brachyurus) is a medium-sized brown woodpecker native to South and Southeast Asia. It is short-billed, foraging in pairs on small insects, particularly ants and termites, in scrub, evergreen, and deciduous forests and is noted for building its nest within the carton nests of arboreal ants in the genus Crematogaster. It was for sometime placed in the otherwise Neotropical genus Celeus but this has been shown to be a case of evolutionary convergence and molecular phylogenetic studies support its placement in the monotypic genus Micropternus.", iucn: "LC" },
  "comfla1": { extract: "The common flameback (Dinopium javanense), also referred to as the common goldenback, is a small (28–30 cm), three-toed woodpecker in the family Picidae, found throughout South and Southeast Asia.", iucn: "LC" },
  "bkrfla1": { extract: "The black-rumped flameback (Dinopium benghalense), also known as the lesser golden-backed woodpecker or lesser goldenback, is a woodpecker found widely distributed in the Indian subcontinent. It is one of the few woodpeckers that are seen in urban areas. It has a characteristic rattling-whinnying call and an undulating flight. It is the only golden-backed woodpecker with a black throat and a black rump.", iucn: "LC" },
  "lesyel1": { extract: "The lesser yellownape (Picus chlorolophus) is a type of woodpecker which is a widespread and often common breeder in tropical and sub-tropical Asia, primarily the Indian subcontinent and Southeast Asia. It ranges from India, Bhutan, Nepal, Bangladesh and Sri Lanka eastwards to Thailand, Burma, Cambodia, Laos, Indonesia, Malaysia and Vietnam. Much of the scientific knowledge gathered about this species is sourced from formal studies in various parts of India.", iucn: "LC" },
  "sttwoo1": { extract: "The streak-throated woodpecker (Picus xanthopygaeus) is a species of woodpecker found in the Indian subcontinent. It occurs in drier woodland, from lowland to the foothills of mountains.", iucn: "LC" },
  "whbwoo2": { extract: "The white-bellied woodpecker or great black woodpecker (Dryocopus javensis) is a woodpecker species inhabiting evergreen forests in tropical Indian subcontinent and Southeast Asia. It is among the largest of the Asiatic woodpeckers and nests in large dead trees, often beside rivers. It has 14 subspecies, and many of its island forms are endangered, some are extinct. Populations differ in the distribution and extent of white. Its drums and calls are louder than those of the smaller woodpeckers.", iucn: "LC" },
  "leskes1": { extract: "The lesser kestrel (Falco naumanni) is a small falcon. This species breeds from the Mediterranean across Afghanistan and Central Asia, to China and Mongolia. It is a summer migrant, wintering in Africa and Pakistan and sometimes even to India and Iraq. It is rare north of its breeding range, and declining in its European range. The genus name derives from Late Latin falx, falcis, a sickle, referencing the claws of the bird, and the species name commemorates the German naturalist Johann Friedrich Naumann.", iucn: "LC" },
  "eurkes": { extract: "The common kestrel (Falco tinnunculus), also known as the European kestrel, Eurasian kestrel, Old World kestrel, or windfucker is a species of predatory bird belonging to the kestrel group of the falcon family Falconidae. In the United Kingdom, where no other kestrel species commonly occurs, it is generally just called the \"kestrel\". This species occurs over a large native range. It is widespread in Europe, Asia and Africa, as well as occasionally reaching the east coast of North America. It has colonized a few oceanic islands, but vagrant individuals are generally rare; in the whole of Micronesia for example, the species was only recorded twice each on Guam and Saipan in the Marianas.", iucn: "LC" },
  "renfal1": { extract: "The red-necked falcon (Falco chicquera) is a bird of prey in the falcon family with two disjunct populations, one in India and the other in Africa. This medium-sized falcon has bluish grey wings and upper body, a chestnut red cap with short chin straps passing through the eye. The primary feathers of the wing are black and a single black band at the tip of the tail are distinctive. The Indian subspecies Falco chicquera chicquera also known as the red-headed merlin or red-headed falcon is found mainly in the open plains of the India Subcontinent although it is thought to have occurred further west in southeastern Iran. The subspecies Falco chicquera ruficollis found in sub-Saharan Africa is sometimes treated as a full species, the rufous-necked falcon (Falco ruficollis), on the basis of its well-separated geographic range and distinctive pattern.", iucn: "NT" },
  "amufal1": { extract: "The Amur falcon (Falco amurensis) is a small raptor of the falcon family. It breeds in south-eastern Siberia and Northern China before migrating in large flocks across India and over the Arabian Sea to winter in Southern and East African coasts.", iucn: "LC" },
  "eurhob": { extract: "The Eurasian hobby (Falco subbuteo), or just hobby, is a small, slim falcon. It belongs to a group of similar falcons often considered a subgenus of Falco.", iucn: "LC" },
  "lagfal1": { extract: "The laggar falcon (Falco jugger) is a mid-sized bird of prey occurring in the Indian subcontinent from southeastern Iran, southeastern Afghanistan, Pakistan, through India, Nepal, Bhutan, Bangladesh and northwestern Myanmar. It used to be one of the most common falcons in the region, but numbers have declined so that is probably nowhere a common species anymore. The main threats are the intensification of pesticide use and use as a decoy to trap large falcons. Fledglings have an almost entirely dark underside, and first-year subadult birds still retain much dark on the belly. Adults are dark overall and have blackish tibiotarsus feathers. The laggar falcon belongs to a close-knit complex of falcons known as hierofalcons. This group exhibits evidence for rampant hybridization and incomplete lineage sorting which confounds analyses of DNA sequence.", iucn: "NT" },
  "perfal": { extract: "The peregrine falcon (Falco peregrinus), also referred to simply as the peregrine, is a bird of prey (raptor) in the family Falconidae known for its speed. A large, crow-sized falcon, it has a blue-grey back, barred white underparts and a black head. As is typical for bird-eating (avivore) raptors, peregrine falcons are sexually dimorphic, with females being considerably larger than males. Historically, the bird has also been known as the \"black-cheeked falcon\" in Australia and the \"duck hawk\" in North America. The breeding range includes land regions from the Arctic tundra to the tropics. It can be found nearly everywhere on Earth, except extreme polar regions, very high mountains, and most tropical rainforests.", iucn: "LC" },
  "cockat": { extract: "The cockatiel (Nymphicus hollandicus), also known as the weero/weiro or quarrion, is a species of small- to medium-sized parrot belonging to the cockatoo family (Cacatuidae), of which it is the smallest member. Native to Australia, it is the sole member of the genus Nymphicus. Cockatiels are widely recognized for their expressive crests, long tail feathers, and sociable, playful nature, and their strong affinity for human interaction has made them among the most commonly kept companion parrots worldwide and one of the five most popular pet bird species; an estimated 4.8 million US households keep them. However, insufficient knowledge of their care contributes to one of the highest surrender rates among pet bird species.", iucn: "LC" },
  "alepar2": { extract: "The Alexandrine parakeet (Psittacula eupatria), also known as the Alexandrine parrot, is a medium-sized parrot in the genus Psittacula of the family Psittaculidae, native to South Asia and Southeast Asia. It is named after Alexander the Great, who transported numerous birds from Punjab to various European and Mediterranean countries and regions, where they were prized by the royalty, nobility and warlords. The Alexandrine parakeet has established feral populations in Turkey, Iraq, Kuwait, Saudi Arabia, Bahrain, Qatar, the United Arab Emirates, Iran, Pakistan, Germany, The Netherlands and Belgium where it lives alongside feral populations of its close relative, the rose-ringed parakeet (Psittacula krameri).", iucn: "" },
  "rorpar": { extract: "The rose-ringed parakeet (Psittacula krameri), also known as the ring-necked parakeet, or colloquially as the Indian Ringneck, is a medium-sized parrot in the genus Psittacula, of the family Psittaculidae. It has a disjunct native range in tropical northern Africa and the Indian subcontinent, and is now introduced into many other parts of the world where populations have established themselves having been bred for the exotic pet trade and then escaped. The species is listed as least concern by the International Union for Conservation of Nature (IUCN) because its population appears to be increasing, but its popularity as a pet and unpopularity with farmers have reduced its numbers in some parts of its native range. One of the few parrot species that have successfully adapted to living in disturbed habitats, it has withstood the onslaught of urbanisation and deforestation.", iucn: "LC" },
  "plhpar1": { extract: "The plum-headed parakeet (Psittacula cyanocephala) is a species of parakeet in the family Psittacidae. It is endemic to the Indian subcontinent and was once thought to be conspecific with the blossom-headed parakeet (P. roseata) before being elevated to a full species. Plum-headed parakeets are found in flocks, the males having a pinkish purple head and the females, a grey head. They fly swiftly with twists and turns accompanied by their distinctive calls.", iucn: "LC" },
  "malpar1": { extract: "The blue-winged parakeet (Psittacula columboides), also known as the Malabar parakeet, is a species of parakeet endemic to the Western Ghats of southern India. Found in small flocks, they fly rapidly in forest clearings while making screeching calls that differ from those of other parakeet species within their distribution range. Their long blue tails tipped in yellow and the dark wings with blue contrast with the dull grey of their head and body. Adult males and females can be easily told apart from the colour of their beak.", iucn: "LC" },
  "rebpar4": { extract: "The red-breasted parakeet (Psittacula alexandri) is a parrot native to Southeast Asia. It is among the more widespread species of the genus and is the species which has the most geographical variations. It is easily identified by the large red patch on its breast. An alternative name is the moustached parakeet depending on subspecies. Most of the subspecies are confined to minuscule islands or a cluster of islands in Indonesia. One subspecies occurs in the Andaman Islands, and one subspecies occurs in continental Southeast Asia and partly extending to northeastern parts of South Asia along the foothills of the Himalayas. Some of the island races may be threatened by the wild bird trade. The nominate race, which occurs in Java, is close to extinction. Feral populations of this species have now established themselves in cities like Mumbai and Singapore.", iucn: "NT" },
  "budger": { extract: "The budgerigar ( BUJ-ər-ih-gar, -⁠ə-ree-; Melopsittacus undulatus), also known as the common parakeet, shell parakeet or budgie ( BUJ-ee), is a small, long-tailed, seed-eating parrot native to Australia. Naturally, the species is green and yellow with black, scalloped markings on the nape, back, and wings. Budgies are bred in captivity with colouring of blues, whites, yellows, greys, and even with small crests. Juveniles and chicks are monomorphic (the sexes are visually indistinguishable), while adults are told apart by their cere colouring and their behaviour. The species is monotypic, meaning it is the only member of the genus Melopsittacus, which is the only genus in the tribe Melopsittacini. The budgerigar is closely related to lories and the fig parrots. The origin of the budgerigar's name is unclear.", iucn: "LC" },
  "railor4": { extract: "The coconut lorikeet (Trichoglossus haematodus), also known as the green-naped lorikeet and Swainson’s lorikeet, is a parrot in the family Psittaculidae. Several species of lorikeets now recognised as distinct were once lumped together under Trichoglossus haematodus; together they form the \"rainbow lorikeet\" species complex. Trichoglossus haematodus as circumscribed today is largely restricted to Melanesia (except Fiji) and a few nearby regions. It is found from Maluku province of easternmost Indonesia across the lowlands of New Guinea, the Bismarck Archipelago, the Solomon Islands and Vanuatu to New Caledonia. Depending on the precise delimitation of species in the \"rainbow lorikeet\" complex, T.haematodus might barely reach Australian territory in the Torres Strait.", iucn: "LC" },
  "vehpar1": { extract: "The vernal hanging parrot (Loriculus vernalis) is a small parrot which is a resident breeder in the Indian subcontinent and some other areas of Southeast Asia. It undergoes local movements, driven mainly by the availability of the fruit, seeds, buds and blossoms that make up its diet. They frequent the banyan tree for the fruit and plantain trees for the nectar from the flowers. This is a small, mainly green hanging parrot, only 14 cm long with a short tail. The adult male has a red rump and bill, and blue throat patch. The female has a green patch. Vernal hanging parrot is a bird of dry jungle and cultivation. It nests in holes in trees, laying 2-4 white eggs. Immature birds have a duller rump, and lack the throat patch. Vernal hanging parrot is less gregarious than some of its relatives, and is usually in small groups outside the breeding season.", iucn: "LC" },
  "peflov": { extract: "The rosy-faced lovebird (Agapornis roseicollis), also known as the rosy-collared or peach-faced lovebird, is a species of lovebird native to the Namibian savanna woodlands. Loud and constant chirpers, these birds are very social animals and often congregate in small groups in the wild. They eat throughout the day and take frequent baths. Coloration can vary widely among populations. Plumage is identical in males and females. Lovebirds are renowned for their sleep position in which they sit side-by-side and turn their faces in towards each other. Also, females are well noted to tear raw materials into long strips, \"twisty-tie\" them onto their backs, and fly substantial distances back to make a nest. These birds are common in the pet industry.", iucn: "LC" },
  "orwpar": { extract: "The orange-winged amazon (Amazona amazonica), also known as orange-winged parrot and loro guaro, is a large amazon parrot. It is a resident breeding bird in tropical South America, from Colombia, Trinidad and Tobago south to Peru, Bolivia and central Brazil. Its habitat is forest and semi-open country. Although common, it is persecuted as an agricultural pest and by capture for the pet trade (over 66,000 captured from 1981 to 1985). It is also hunted as a food source. Introduced breeding populations have been reported in Puerto Rico and Tenerife in the Canary Islands.", iucn: "LC" },
  "gncpar": { extract: "The green-cheeked parakeet (Pyrrhura molinae), also sometimes known as the green-cheeked conure in aviculture, is a species of bird in subfamily Arinae of the family Psittacidae, aka the parrots. It is found in Argentina, Bolivia, Brazil, and Paraguay. It is also a popular pet bird.", iucn: "LC" },
  "indpit1": { extract: "The Indian pitta (Pitta brachyura) also known as Navrang, is a passerine bird native to the Indian subcontinent. It inhabits scrub jungle, deciduous and dense evergreen forest. It breeds in the forests of the Himalayas, hills of central and western India, and migrates to other parts of the peninsula in winter. Although very colourful, it is usually shy and hidden in the undergrowth where it picks insects on the forest floor. It has a distinctive two note whistling call which is heard at dawn and dusk. It is listed as least concern on the IUCN Red List as the population is considered large.", iucn: "LC" },
  "whbmin3": { extract: "The white-bellied minivet (Pericrocotus erythropygius) is a species of minivet found in India, mostly in dry deciduous forest.", iucn: "LC" },
  "smamin1": { extract: "The small minivet (Pericrocotus cinnamomeus) is a small passerine bird. This minivet is found in tropical southern Asia from the Indian subcontinent east to Indonesia.", iucn: "LC" },
  "scamin3": { extract: "The orange minivet (Pericrocotus flammeus) is a brightly colored bird in the cuckooshrike family, Campephagidae. It is found all along the Western Ghats and west coast of India and Sri Lanka. It was formerly considered a subspecies of the scarlet minivet which is considered to have a wider distribution in eastern and northern India and South-east Asia. Its natural habitats are temperate forests, subtropical or tropical moist lowland forest, and subtropical or tropical moist montane forest. The orange minivet is a species resident in southern India and Sri Lanka, that feeds primarily on insects while foraging in mixed-species bird flocks or in small single-species groups.", iucn: "LC" },
  "ashmin1": { extract: "The ashy minivet (Pericrocotus divaricatus) is a passerine bird of eastern Asia belonging to the minivet genus Pericrocotus in the cuckooshrike family Campephagidae. While most of the minivets have shades of yellow, orange and red in their plumage, this species has only greys, whites and blacks. The male is distinctive with a white face and black nape although females can be confused with the female of the brown-rumped minivet. They forage in the canopy, often along with other minivets and join mixed-species foraging flocks.", iucn: "LC" },
  "brrmin1": { extract: "Swinhoe's minivet or the brown-rumped minivet (Pericrocotus cantonensis) is a bird in the cuckooshrike family, Campephagidae. The species was first described by Robert Swinhoe in 1861. It breeds in China and winters in Indochina. Its natural habitats are temperate forest, subtropical or tropical moist lowland forest, and subtropical or tropical moist montane forest.", iucn: "LC" },
  "larcuc1": { extract: "The Indian cuckooshrike (Coracina macei) is a species of bird in the cuckooshrike family Campephagidae that is found on the Indian subcontinent. Formerly under the English name \"large cuckooshrike\" this species included many subspecies and had a large range that included Southeast Asia.", iucn: "LC" },
  "bkwcus1": { extract: "The black-winged cuckooshrike (Lalage melaschistos), also known as lesser grey cuckooshrike or dark grey cuckooshrike, is a species of cuckooshrike found in South to Southeast Asia. Despite the name, they (cuckooshrikes) are unrelated to either shrikes or cuckoos. They have broad based bills with grey upper parts, black wings, white vent, graduated white-tipped tails, black bills and legs. Females are overall lighter in all taxa.", iucn: "LC" },
  "bkhcus1": { extract: "The black-headed cuckooshrike (Lalage melanoptera) is a species of cuckooshrike found in the Indian subcontinent and Southeast Asia.", iucn: "LC" },
  "ingori1": { extract: "The Indian golden oriole (Oriolus kundoo) is a species of oriole found in the Indian subcontinent and Central Asia. The species was formerly considered to be a subspecies of the Eurasian golden oriole, but is now considered a full species. Adults can be told apart from the Eurasian golden oriole by the black of the eye stripe extending behind the eye.", iucn: "LC" },
  "blnori1": { extract: "The black-naped oriole (Oriolus chinensis) is a passerine bird in the oriole family that is found in many parts of Asia. There are several distinctive populations within the wide distribution range of this species and in the past the slender-billed oriole (Oriolus tenuirostris) was included as a subspecies. Unlike the Indian golden oriole which only has a short and narrow eye-stripe, the black-naped oriole has the stripe broadening and joining at the back of the neck. Males and females are very similar although the wing lining of the female is more greenish. The bill is pink and is stouter than in the golden oriole.", iucn: "LC" },
  "blhori1": { extract: "The black-hooded oriole (Oriolus xanthornus) is a member of the oriole family of passerine birds and is a resident breeder in tropical southern Asia from India and Sri Lanka east to Indonesia. It is a bird of open woodland and cultivation. The nest is built in a tree, and contains two eggs. Its food is insects and fruit, especially figs, found in the tree canopies where they spend much of their time.", iucn: "LC" },
  "ashwoo2": { extract: "The ashy woodswallow (Artamus fuscus), sometimes also called the ashy swallow-shrike, is a woodswallow which is found in south Asia. Like other woodswallows, it has a short curved bill, a short square tail and long wings. It is usually seen perched in groups, high on powerlines, tall bare trees and most often in areas with a predominance of tall palm trees.", iucn: "LC" },
  "malwoo1": { extract: "The Malabar woodshrike (Tephrodornis sylvicola) is a species of bird usually placed in the family Vangidae. It is found in western India. It is sometimes considered a subspecies of the large woodshrike.", iucn: "LC" },
  "comwoo1": { extract: "The common woodshrike (Tephrodornis pondicerianus) is a species of bird found in Asia. It is now usually considered a member of the family Vangidae. It is small and ashy brown with a dark cheek patch and a broad white brow. It is found across Asia mainly in thin forest and scrub habitats where they hunt insects, often joining other insectivorous birds. The form found in Sri Lanka which was treated as a subspecies is now usually considered a separate species, the Sri Lanka woodshrike.", iucn: "LC" },
  "bwfshr1": { extract: "The bar-winged flycatcher-shrike (Hemipus picatus) is a small passerine bird usually placed in the Vangidae. It is found in the forests of tropical southern Asia from the Himalayas and hills of southern India to Indonesia. Mainly insectivorous it is found hunting in the mid-canopy of forests, often joining mixed-species foraging flocks. They perch upright and have a distinctive pattern of black and white, males being more shiny black than the females. In some populations the colour of the back is brownish while others have a dark wash on the underside.", iucn: "LC" },
  "comior1": { extract: "The common iora (Aegithina tiphia) is a small passerine bird found across the tropical Indian subcontinent and Southeast Asia, with populations showing plumage variations, some of which are designated as subspecies. A species found in scrub and forest, it is easily detected from its loud whistles and the bright colours. During the breeding season, males display by fluffing up their feathers and spiral in the air appearing like a green, black, yellow, and white ball.", iucn: "LC" },
  "whtior1": { extract: "Marshall's iora (Aegithina nigrolutea), also known as the white-tailed iora, is a songbird in the genus Aegithina found in parts of India and Sri Lanka.", iucn: "LC" },
  "spbfan1": { extract: "The white-spotted fantail or spot-breasted fantail (Rhipidura albogularis) is a small passerine bird. It is found in forest, scrub and cultivation in southern and central India. It was formerly considered a subspecies of the white-throated fantail.", iucn: "LC" },
  "whbfan2": { extract: "The white-browed fantail (Rhipidura aureola) is a small passerine bird belonging to the family Rhipiduridae.", iucn: "LC" },
  "bladro1": { extract: "The black drongo (Dicrurus macrocercus) is a small Asian passerine bird of the drongo family Dicruridae. It is a common resident breeder in much of tropical southern Asia from southwest Iran through Pakistan, India, Bangladesh and Sri Lanka east to southern China and Indonesia and accidental visitor of Japan. It is an all black bird with a distinctive forked tail and measures 28 cm (11 in) in length. It feeds on insects, and is common in open agricultural areas and light forest throughout its range, perching conspicuously on a bare perch or along power or telephone lines. The species is known for its aggressive behaviour towards much larger birds, such as crows, never hesitating to dive-bomb any bird of prey that invades its territory. This behaviour earns it the informal name of king crow. Smaller birds often nest in the well-guarded vicinity of a nesting black drongo.", iucn: "LC" },
  "ashdro1": { extract: "The ashy drongo (Dicrurus leucophaeus) is a species of bird in the drongo family Dicruridae. It is found widely distributed across eastern and Southeast Asia, with several populations that vary in the shade of grey, migration patterns and in the size or presence of white patches around the eye.", iucn: "LC" },
  "whbdro1": { extract: "The white-bellied drongo (Dicrurus caerulescens) is a species of drongo found across the Indian Subcontinent. Like other members of the family Dicruridae, they are insectivorous and mainly black in colour, but with a white belly and vent. Young birds are, however, all black and may be confused with the black drongo, which is smaller and more compact in appearance. The subspecies found in Sri Lanka has white restricted to the vent.", iucn: "LC" },
  "brodro1": { extract: "The bronzed drongo (Dicrurus aeneus) is a small Indomalayan bird belonging to the drongo group. They are resident in the forests of the Indian subcontinent and Southeast Asia. They capture insects flying in the shade of the forest canopy by making aerial sallies from their perches. They are very similar to the other drongos of the region but are somewhat smaller and compact with differences in the fork depth and the patterns of gloss on their feathers.", iucn: "LC" },
  "hacdro1": { extract: "The hair-crested drongo (Dicrurus hottentottus) is an Asian bird of the family Dicruridae. This species was formerly considered conspecific with Dicrurus bracteatus, for which the name \"spangled drongo\" – formerly used for both – is now usually reserved. Some authorities include the Sumatran drongo (D. sumatranus) in D. hottentottus as subspecies. It is native from Pakistan, Bangladesh, India, and Bhutan through Indochina to China, Indonesia, and Brunei. Hair-crested drongos move in small flocks and are very noisy. The \"spangled drongo\", Dicrurus bracteatus, is native on the east coast of Australia and its name is a pejorative slang for a silly person. This may be due to its strange chattering and cackling.", iucn: "LC" },
  "grtdro1": { extract: "The greater racket-tailed drongo (Dicrurus paradiseus) is a medium-sized Asian bird which is distinctive in having elongated outer tail feathers with webbing restricted to the tips. They are placed along with other drongos in the family Dicruridae. They are conspicuous in the forest habitats often perching in the open and by attracting attention with a wide range of loud calls that include perfect imitations of many other birds. One hypothesis suggested is that these vocal imitations may help in the formation of mixed-species foraging flocks, a feature seen in forest bird communities where many insect feeders forage together. These drongos will sometimes steal insect prey caught or disturbed by other foragers in the flock and another idea is that vocal mimicry helps them in diverting the attention of smaller birds to aid their piracy.", iucn: "LC" },
  "blnmon1": { extract: "The black-naped monarch (Hypothymis azurea) is a passerine bird belonging to the family of monarch flycatchers found in southern and south-eastern Asia. They are sexually dimorphic, with the male having a distinctive black patch on the back of the head and a narrow black half collar (\"necklace\"), while the female is duller with olive brown wings and lacking the black markings on the head. They have a call that is similar to that of the Asian paradise flycatcher, and in tropical forest habitats, pairs may join mixed-species foraging flocks. Populations differ slightly in plumage colour and sizes.", iucn: "LC" },
  "aspfly1": { extract: "The Indian paradise flycatcher (Terpsiphone paradisi) is a medium-sized passerine bird in the monarch flycatcher family, Monarchidae. As the global population is considered stable, it has been listed as Least Concern on the IUCN Red List since 2004. It is native to the Indian subcontinent, with resident and breeding populations in most of Bangladesh, India and Sri Lanka, as well as parts of Afghanistan, Bhutan, China, Myanmar, Nepal, Pakistan, Tajikistan and Turkmenistan. The Indian paradise flycatcher has a length of 20–50 cm (7.9–19.7 in) from beak to tail. Males have elongated central tail feathers, and a black and rufous plumage in some populations, while others have white plumage. Females are short-tailed with rufous wings and a black head. Indian paradise flycatchers feed on insects, including grasshoppers, butterflies and praying mantises, as well as flies.", iucn: "LC" },
  "isashr1": { extract: "The isabelline shrike or Daurian shrike (Lanius isabellinus) is a member of the shrike family (Laniidae). It was previously considered conspecific with the red-backed shrike and red-tailed shrike. It is found in an extensive area between the Caspian Sea and north and central China southeast to the Qaidam Basin. Overwinters in Africa and Arabia.", iucn: "LC" },
  "brnshr": { extract: "The brown shrike (Lanius cristatus) is a bird in the shrike family that is found mainly in Asia. It is closely related to the red-backed shrike (L. collurio) and isabelline shrike (L. isabellinus). The genus name, Lanius, is derived from the Latin word for \"butcher\", and some shrikes are also known as \"butcher birds\" because of their feeding habits. The specific cristatus is Latin for \"crested\", used in a broader sense than in English. The common English name \"shrike\" is from Old English scríc, \"shriek\", referring to the shrill call. Like most other shrikes, it has a distinctive black \"bandit-mask\" through the eye and is found mainly in open scrub habitats, where it perches on the tops of thorny bushes in search of prey. Several populations of this widespread species form distinctive subspecies which breed in temperate Asia and migrate to their winter quarters in tropical Asia.", iucn: "LC" },
  "babshr1": { extract: "The bay-backed shrike (Lanius vittatus) is a member of the bird family Laniidae, the shrikes, resident in South Asia.", iucn: "LC" },
  "lotshr1": { extract: "The long-tailed shrike or rufous-backed shrike (Lanius schach) is a member of the bird family Laniidae, the shrikes. They are found widely distributed across Asia and there are variations in plumage across the range. The species ranges across much of Asia, both on the mainland and the eastern archipelagos. The eastern or Himalayan subspecies, L. s. tricolor, is sometimes called the black-headed shrike. Although there are considerable differences in plumage among the subspecies, they all have a long and narrow black tail, have a black mask and forehead, rufous rump and flanks and a small white patch on the shoulder. It is considered to form a superspecies with the grey-backed shrike (Lanius tephronotus) which breeds on the Tibetan Plateau.", iucn: "LC" },
  "norshr1": { extract: "The great grey shrike (Lanius excubitor) is a large and predatory songbird species in the shrike family (Laniidae). It forms a superspecies with its parapatric southern relatives, the Iberian grey shrike (L. meridionalis), the Chinese grey shrike (L. sphenocerus) and the American loggerhead shrike (L. ludovicianus). Males and females are similar in plumage, pearly grey above with a black eye-mask and white underparts. Breeding takes place generally north of 50° northern latitude in northern Europe and Asia. Most populations migrate south in winter to temperate regions. The great grey shrike is carnivorous, with rodents making up over half its diet.", iucn: "LC" },
  "ruftre2": { extract: "The rufous treepie (Dendrocitta vagabunda) is a treepie, native to the Indian subcontinent and adjoining parts of Southeast Asia. It is a member of the crow family, Corvidae. It is long tailed and has loud musical calls making it very conspicuous. It is found commonly in open scrub, agricultural areas, forests as well as urban gardens. Like other corvids it is very adaptable, omnivorous and opportunistic in feeding.", iucn: "LC" },
  "whbtre1": { extract: "The white-bellied treepie (Dendrocitta leucogastra) is a bird of the crow family endemic to the forests of southern India. They overlap in distribution in some areas with the rufous treepie but are easy to tell apart both from appearance and call.", iucn: "LC" },
  "houcro1": { extract: "The house crow (Corvus splendens), also known as the Indian, greynecked, Ceylon or Colombo crow, is a common bird of the crow family that is of Asian origin but now found in many parts of the world, where they arrived assisted by shipping. It is between the jackdaw and the carrion crow in size (40 cm (16 in) in length) but is slimmer than either. The forehead, crown, throat and upper breast are a richly glossed black, whilst the neck and breast are a lighter grey-brown in colour. The wings, tail and legs are black. There are regional variations in the thickness of the bill and the depth of colour in areas of the plumage.", iucn: "LC" },
  "labcro1": { extract: "The large-billed crow (Corvus macrorhynchos), formerly referred to widely as the jungle crow, is a widespread Asian species of crow. It is very adaptable and is able to survive on a wide range of food sources, making it capable of colonizing new areas, due to which it is often considered a nuisance, especially on islands. It has a large bill, which is the source of its scientific name macrorhynchos (Ancient Greek for \"long-billed\") and it is sometimes known by the common name thick-billed crow. It can also be mistaken for a common raven. The eastern jungle crow and Indian jungle crow were once considered conspecific and together called the jungle crow.", iucn: "LC" },
  "gyhcaf1": { extract: "The grey-headed canary-flycatcher (Culicicapa ceylonensis), sometimes known as the grey-headed flycatcher, is a species of small flycatcher-like bird found in tropical Asia. It has a square crest, a grey hood and yellow underparts. They are found mainly in forested habitats where they often join other birds in mixed-species foraging flocks. Pairs are often seen as they forage for insects by making flycatcher-like sallies and calling aloud. Several subspecies are recognized within their wide distribution range. In the past the genus Culicicapa was considered to be an Old World flycatcher but studies have found them to belong to a new family designated as the Stenostiridae or fairy flycatchers that include the African genera Stenostira and Elminia.", iucn: "LC" },
  "cintit13": { extract: "The cinereous tit or Asian tit (Parus cinereus) is a species of bird in the tit family Paridae. This species is made up of several populations that were earlier treated as subspecies of the great tit (Parus major). These birds are grey backed with white undersides. The great tit in the new sense is distinguishable by the greenish-back and yellowish underside. The distribution of this species extends from parts of West Asia across South Asia and into Southeast Asia. The Japanese tit was formerly treated as a separate species but is now grouped together with the cinereous tit.", iucn: "" },
  "whwtit2": { extract: "The white-naped tit (Machlolophus nuchalis), sometimes called white-winged tit, is a passerine bird in the tit family Paridae. It is endemic to India where it is found in dry thorn scrub forest in two disjunct populations, in western India and southern India. Its specific name nuchalis means 'of the nuchal, nape'. This species is hard to mistake with its contrasting black and white patterns without the grey wing coverts and back of the partly sympatric cinereous tit (Parus cinereus). This species is very patchily distributed and is considered to be Near Threatened especially because loss of its preferred acacia habitats and continuing incursion of invasive Neltuma chilensis and Lantana camara trees.", iucn: "VU" },
  "indtit1": { extract: "The Indian black-lored tit, Indian tit, or Indian yellow tit (Grimmett et al., 2011) (Machlolophus aplonotus) is a passerine bird in the tit family Paridae. The yellow-cheeked tit is probably its closest relative, and both may be related to the yellow tit. These three tits almost certainly form a distinct lineage as evidenced by morphology, and mtDNA cytochrome b sequence analysis (Gill et al., 2005). The subgenus name Macholophus may apply for them. This species is a resident breeder on the Indian subcontinent. It is a common bird in open tropical forests, but does not occur in Sri Lanka. It is an active and agile feeder, taking insects and spiders from the canopy, and sometimes fruit. It is an easy tit to recognise in most of India, large in size at 13 cm, with a broad black line (broader in the male) down its otherwise yellow front.", iucn: "" },
  "rutlar2": { extract: "The rufous-tailed lark (Ammomanes phoenicura), also sometimes called the rufous-tailed finch-lark, is a ground bird found in the drier open stony habitats of India and parts of Pakistan. Like other species in the genus it has a large finch-like bill with a slightly curved edge to the upper mandible. The dull brown colour matches the soil as it forages for grass seeds, grain and insects. Males and females are indistinguishable in the field but during the breeding season, the male has a courtship display that involves flying up steeply and then nose-diving and pulling up in a series of stepped wavy dips accompanied by calling. They forage on the ground in pairs or small groups.", iucn: "LC" },
  "ascspl1": { extract: "The ashy-crowned sparrow-lark (Eremopterix griseus) is a small sparrow-sized member of the lark family. It is found in the plains in open land with bare ground, grass and scrub across South Asia. The males are well marked with a contrasting black-and-white face pattern, while females are sandy brown, looking similar to a female sparrow. Males are easily detected during the breeding season by the long descending whistle that accompanies their undulating and dive-bombing flight displays.", iucn: "LC" },
  "jerbus2": { extract: "Jerdon's bush lark (Plocealauda affinis) or Jerdon's lark is a species of lark in the family Alaudidae found in south Asia. This was formerly placed in the genus Mirafra and considered as a subspecies of Mirafra assamica and termed as the Madras bushlark. Two other species in the complex include Mirafra marionae and Mirafra microptera. Jerdon's bush lark is typically very pale on the underside", iucn: "LC" },
  "indbus2": { extract: "The Indian bush lark (Plocealauda erythroptera) is a species of lark in the family Alaudidae found in South Asia.", iucn: "LC" },
  "sinbus6": { extract: "The singing bush lark or Horsfield's bush lark (Mirafra javanica) is a species of lark which inhabits grassland throughout most of Australia and much of Southeast Asia. It was described by the American naturalist Thomas Horsfield.", iucn: "LC" },
  "orisky1": { extract: "The Oriental skylark (Alauda gulgula) is a species of skylark found in the Sino-Indian region and parts of central Asia. Like other skylarks, it is found in open grassland where it feeds on seeds and insects.", iucn: "LC" },
  "tawlar1": { extract: "Sykes's lark (Galerida deva) is a species of lark found in the dry open country of India. Its distribution is mainly restricted to central India, although stray records have been found elsewhere on the sub-continent. It is identified by its prominent crest and its overall rufous colouration. It has streaks on its breast which are less prominent than those found in the Oriental skylark. It can imitate the calls of 34 other birds within its habitat.", iucn: "LC" },
  "mallar1": { extract: "The Malabar lark, or Malabar crested lark (Galerida malabarica) is a species of lark in the family Alaudidae found in western India.", iucn: "LC" },
  "sstlar4": { extract: "The Mongolian short-toed lark or Sykes's short-toed lark (Calandrella dukhunensis) is a species of lark in the family Alaudidae. It breeds in China and Mongolia and winters in southern Asia.", iucn: "LC" },
  "bimlar1": { extract: "The bimaculated lark (Melanocorypha bimaculata) breeds in warm temperate countries eastwards from Turkey into Central Asia. It is the eastern counterpart of its relative, the calandra lark.", iucn: "LC" },
  "comtai1": { extract: "The common tailorbird (Orthotomus sutorius) is a songbird found across tropical and subtropical Asia. Popular for its nest made of leaves \"sewn\" together and immortalized by Rudyard Kipling as Darzee in his Jungle Book, it is a common resident in urban gardens. Although shy birds that are usually hidden within vegetation, their loud calls are familiar and give away their presence. They are distinctive in having a long upright tail, greenish upper body plumage and rust coloured forehead and crown. This passerine bird is typically found in open farmland, scrub, forest edges and gardens. Tailorbirds get their name from the way their nest is constructed. The edges of a large leaf are pierced and sewn together with plant fibre or spider silk to make a cradle in which the actual nest is built.", iucn: "LC" },
  "rufpri2": { extract: "The rufous-fronted prinia (Prinia buchanani) is a species of bird in the family Cisticolidae. It is found in India and Pakistan. Its natural habitat is subtropical or tropical dry forest. The species was described by Edward Blyth on the basis of an illustration of the bird from Bengal in the collections of Buchanan Hamilton.", iucn: "LC" },
  "gybpri1": { extract: "The grey-breasted prinia or Franklin's prinia (Prinia hodgsonii) is a wren-warbler belonging to the family of small passerine birds found mainly in warmer southern regions of the Old World. This prinia is a resident breeder in the Indian subcontinent, Sri Lanka and southeast Asia. Like other prinias, it often holds the tail upright but it is easily told by a smoky grey band across the breast which contrasts with a white throat. The beak is all black while the legs are pink. The tail is graduated as in other prinias and the grey feathers are tipped in white. In the breeding plumage the upperparts are grey while non-breeding birds are pale above with rufous wings and a weak supercilium. It is found in scrub, forest clearings and other open but well vegetated habitats. It can be confused with the rufescent prinia.", iucn: "LC" },
  "junpri1": { extract: "The jungle prinia (Prinia sylvatica) is a small passerine bird, a warbler in the family Cisticolidae.", iucn: "LC" },
  "ashpri1": { extract: "The ashy prinia or ashy wren-warbler (Prinia socialis) is a small warbler in the family Cisticolidae. This prinia is a resident breeder in the Indian subcontinent, ranging across most of India, Nepal, Bangladesh, eastern Pakistan, Bhutan, Sri Lanka and western Myanmar. It is a common bird in urban gardens and farmlands in many parts of India and its small size, distinctive colours and upright tail make it easy to identify. The northern populations have a rufous rump and back and have a distinct breeding and non-breeding plumage while other populations lack such variation.", iucn: "LC" },
  "plapri1": { extract: "The plain prinia (Prinia inornata), also known as the plain wren-warbler or white-browed wren-warbler, is a small cisticolid warbler found in Southeast Asia. It is a resident breeder from Pakistan and India to south China and southeast Asia. It was formerly included in the tawny-flanked prinia (Prinia subflava), resident in Africa south of the Sahara. The two are now usually considered to be separate species.", iucn: "LC" },
  "zitcis1": { extract: "The zitting cisticola, formerly also fan-tailed warbler or streaked fantail warbler (Cisticola juncidis), is a widely distributed Old World warbler in the family Cisticolidae, whose breeding range includes western and southern Europe, Africa outside the deserts and rainforest, and southern Asia down to northern Australia. A small bird found mainly in grasslands, it is best identified by its rufous rump; in addition it lacks any gold on the collar and the brownish tail is tipped with white. During the breeding season males have a zigzagging flight display accompanied by regular \"zit\" calls that give it its English name. They build their pouch nest suspended within a clump of grass.", iucn: "LC" },
  "gohcis1": { extract: "The golden-headed cisticola (Cisticola exilis), also known as the bright-capped cisticola, is a species of warbler in the family Cisticolidae, found in Australia and thirteen Asian countries. Growing to 9–11.5 cm (3.5–4.5 in) long, it is usually brown and cream in colour, but has a different appearance during the mating season, with a gold-coloured body and a much shorter tail. It is an omnivore and frequently makes a variety of vocalizations. Known as the \"finest tailor of all birds\", it constructs nests out of plants and spider threads. It mates in the rainy season. It has a very large range and population, which is thought to be increasing.", iucn: "LC" },
  "thbwar1": { extract: "The thick-billed warbler (Arundinax aedon) breeds in the temperate east Palearctic, from south Siberia to west Mongolia. It is migratory, wintering in tropical South Asia and South-east Asia. It is a very rare vagrant to western Europe. This passerine bird is a species found in dense vegetation such as reeds, bushes and thick undergrowth. Five or six eggs are laid in a nest in a low tree. This is a large warbler, at 16–17.5 cm (6.3–6.9 in) long, which is nearly as big as the great reed warbler. The adult has an unstreaked brown back and buff underparts, with few obvious distinctive plumage features. The forehead is rounded, and the bill is short and pointed. The sexes are identical, as with most warblers, but young birds are richer buff below. Like most warblers, it is insectivorous, but will take other small prey items.", iucn: "LC" },
  "boowar1": { extract: "The booted warbler (Iduna caligata) is a species of passerine bird belonging to the family Acrocephalidae, the reed and tree warblers. This species breeds in Eastern Europe and western Asia, wintering in south Asia. it is a regular vagrant to Western Europe.", iucn: "LC" },
  "sykwar2": { extract: "Sykes's warbler (Iduna rama) is an Old World warbler in the tree warbler family. It was formerly considered a subspecies of the booted warbler, but is now considered a full species. Its breeding range is from northeast Arabia to Turkestan, west China and Afghanistan. Like the booted warbler, many populations of the species migrate in winter to the Indian subcontinent as far south as Sri Lanka.", iucn: "LC" },
  "padwar1": { extract: "The paddyfield warbler (Acrocephalus agricola) is a species of marsh warbler (family Acrocephalidae). It was formerly included in the \"Old World warbler\" assemblage. The Manchurian reed warbler (A. tangorum) was (and sometimes still is) included in A. agricola as a subspecies. The genus name Acrocephalus is from Ancient Greek akros, \"highest\", and kephale, \"head\". It is possible that Naumann and Naumann thought akros meant \"sharp-pointed\". The specific agricola is from Latin and means \"farmer\". It breeds in the temperate central Palearctic. It is migratory, wintering in Bangladesh, India and Pakistan. It is a rare vagrant to western Europe although there are small breeding populations along the western shores of the Black Sea around the border between Bulgaria and Romania. This passerine bird is a species found in low vegetation such as long grass, reeds and rice.", iucn: "LC" },
  "blrwar1": { extract: "Blyth's reed warbler (Acrocephalus dumetorum) is a species of reed warbler belonging to the family Acrocephalidae, which also includes the tree warblers. Blyth's reed warbler breeds across the Palearctic zoogeographical region and winters in South Asia. The species has been expanding its range westwards in Europe.", iucn: "LC" },
  "clrwar1": { extract: "The clamorous reed warbler (Acrocephalus stentoreus) is an Old World warbler in the genus Acrocephalus. It breeds from Egypt eastwards through Pakistan, Afghanistan and northernmost India to south China and southeast Asia. A. s. meridionalis is an endemic race in Sri Lanka.", iucn: "LC" },
  "pagwar1": { extract: "Pallas's grasshopper warbler (Helopsaltes certhiola), also known as the rusty-rumped warbler, is an Old World warbler in the genus Helopsaltes. It breeds in the eastern Palearctic: from the Altai Mountains, Mongolia and Transbaikalia to northeastern China, the Korean Peninsula, and islands in the Sea of Okhotsk (Sakhalin and Kuril Islands). It is migratory, wintering from India eastward to Indonesia. It is a rare migrant in Sri Lanka.", iucn: "" },
  "cogwar1": { extract: "The common grasshopper warbler or just grasshopper warbler (Locustella naevia) is a species of Old World warbler in the genus Locustella. It breeds across much of temperate Europe and the western Palearctic. It is migratory, wintering across northern tropical Africa just south of the Sahara, and also locally in India. This small passerine bird is found in dense grassland vegetation, often close to water, and usually with a few small scattered shrubs. It is a medium-sized warbler about 13 cm (5 in) long. The adult has a streaked brown back and whitish grey underparts which are unstreaked except on the undertail coverts. The sexes are identical, as with most warblers, but young birds are yellower below. Like most warblers, it is insectivorous. Four to seven eggs are laid in a nest on or near the ground in thick vegetation or in a tussock of grass.", iucn: "LC" },
  "brtgra2": { extract: "The broad-tailed grassbird (Schoenicola platyurus) is a species of Old World warbler in the family Locustellidae. It is endemic to the Western Ghats of India with a possibility of occurrence in Sri Lanka. A small, mostly brown bird, it has a broad rounded and graduated tail. It is found only on the higher altitude grassy hills where it usually skulks, except during the breeding season when males fly up into the air to sing in their display. The species is believed to be a resident although it is possible that they make local movements.", iucn: "NT" },
  "brigra2": { extract: "The bristled grassbird (Schoenicola striatus) is a small passerine bird in the genus Schoenicola. Also known as the bristled grass warbler, this species is endemic to the Indian subcontinent, where it is patchily distributed in Bangladesh, India, Nepal and Pakistan. These insectivorous birds skulk in dense and tall grasslands, often in marshy areas, habitats that are threatened by human activities. Formerly considered to be sedentary, the species may be migratory, moving south and east in the Indian peninsula during winter and returning to their breeding grounds in the northern plains south of the Himalayas.", iucn: "VU" },
  "gytmar1": { extract: "The grey-throated martin or Asian plain martin (Riparia chinensis) is a small passerine bird in the swallow family. The grey-throated martin is found in open habitats such as farmland, grassland and savannah, usually near water. It is found from Tajikistan, Afghanistan and Indian subcontinent to southern China, Taiwan, and the northern Philippines. It was formerly considered a subspecies of the plain martin, since renamed the brown-throated martin.", iucn: "LC" },
  "banswa": { extract: "The sand martin (Riparia riparia), also known as the collared sand martin or common sand martin, and in the Americas as the bank swallow, is a migratory passerine bird in the swallow family Hirundinidae. It has a wide range in summer, embracing practically the whole Holarctic area, from Europe, across Asia to the Pacific Ocean, and throughout North America. It winters in eastern and southern Africa, southern Asia, and South America.", iucn: "LC" },
  "eurcrm1": { extract: "The Eurasian crag martin or just crag martin (Ptyonoprogne rupestris) is a small passerine bird in the swallow family. It is about 14 cm (5.5 in) long with ash-brown upperparts and paler underparts, and a short, square tail that has distinctive white patches on most of its feathers. It breeds in the mountains of southern Europe, northwestern Africa and across the Palearctic. It can be confused with the three other species in its genus, but is larger with brighter tail spots and different plumage tone. Many European birds are resident, but some northern populations and most Asian breeders are migratory, wintering in northern Africa, the Middle East or India. The Eurasian crag martin builds a nest adherent to the rock under a cliff overhang or increasingly onto a man-made structure. It makes a neat half-cup mud nest with an inner soft lining of feathers and dry grass.", iucn: "LC" },
  "duscrm1": { extract: "The dusky crag martin (Ptyonoprogne concolor) is a small passerine bird in the swallow family. It is about 13 cm (5 in) long with a broad body and wings, and a short square tail that has small white patches near the tips of most of its feathers. This martin has sooty-brown upperparts and slightly paler underparts. The two subspecies are resident breeding birds in South Asia from the Indian subcontinent to southwestern China and the northern parts of Thailand, Vietnam and Laos. This martin nests under a cliff overhang or on a man-made structure, building a neat half-cup mud nest with a soft lining. Both adults incubate the two to four eggs and feed the chicks. This species does not form large breeding colonies, but it is more gregarious outside the breeding season. It feeds a wide variety of insects that are caught as the martin flies near to cliff faces.", iucn: "LC" },
  "pacswa3": { extract: "The hill swallow (Hirundo domicola) is a small passerine bird in the swallow family. It breeds in southern India and Sri Lanka. It is resident apart from some local seasonal movements. This bird is associated with coasts, but is increasingly spreading to forested uplands. It was formerly considered to be a subspecies of the Pacific swallow.", iucn: "" },
  "barswa": { extract: "The barn swallow (Hirundo rustica) is the most widespread species of swallow in the world, occurring on all continents, with vagrants reported even in Antarctica. It is a distinctive passerine bird with blue upperparts and a long, deeply forked tail. In Anglophone Europe, it is just called the swallow; in northern Europe, it is the only member of family Hirundinidae called a \"swallow\" rather than a \"martin\". There are eight subspecies of barn swallow, which breed across the Northern Hemisphere. Two subspecies (H. r. savignii and H. r. transitiva) have fairly restricted ranges in the Nile valley and eastern Mediterranean, respectively. The other six are more widespread, with winter ranges covering much of the Southern Hemisphere. The barn swallow is a bird of open country that normally nests in man-made structures and consequently has spread with human expansion.", iucn: "LC" },
  "witswa1": { extract: "The wire-tailed swallow (Hirundo smithii) is a small passerine bird in the swallow family. It has two subspecies: H. s. smithii, which occurs throughout Africa, and H. s. filifera, which is found in southern and southeastern Asia. It is mainly resident, but populations in Pakistan and northern India migrate further south in winter. The genus name Hirundo is the Latin word for swallow. The species name smithii commemorates Christen Smith, a Norwegian botanist and geologist.", iucn: "LC" },
  "comhom1": { extract: "The western house martin (Delichon urbicum), sometimes called the common house martin, northern house martin or, particularly in Europe, just house martin, is a migratory passerine bird of the swallow family which breeds in Europe, north Africa and west-central Asia; and winters in sub-Saharan Africa and southwestern Asia. It feeds on insects which are caught in flight, and it migrates to climates where flying insects are plentiful. It has a blue head and upperparts, white rump and pure white underparts, and is found in both open country and near human habitation. It is similar in appearance to the two other martin species of the genus Delichon, which are both endemic to eastern and southern Asia. It has two accepted subspecies. Both the scientific and colloquial name of the bird are related to its use of human-made structures.", iucn: "LC" },
  "ashmar1": { extract: "The Asian house martin (Delichon dasypus) is a migratory passerine bird of the swallow family Hirundinidae. It has mainly blue-black upperparts, other than its white rump, and has pale grey underparts. Its three subspecies breed in the Himalayas and in central and eastern Asia, and spend the winter lower in the mountains or in Southeast Asia. This species is locally abundant and is expanding northward in Siberia, so there are no concerns about its conservation status. This martin breeds in colonies, building mud nests under an overhang on a vertical cliff or the wall of a building. Both sexes build the nest, incubate the three or four white eggs and feed the chicks. The Asian house martin feeds on small insects taken in flight, usually caught high in the air.", iucn: "LC" },
  "y00621": { extract: "The eastern red-rumped swallow (Cecropis daurica) is a small passerine bird in the swallow family Hirundinidae. It is found in open, often hilly, areas with clearings and cultivation across eastern and southeastern Asia to north-eastern India and Taiwan. The European red-rumped swallow and the African red-rumped swallow were formerly considered as subspecies of the eastern red-rumped swallow.", iucn: "LC" },
  "sttswa2": { extract: "The streak-throated swallow or the Indian cliff swallow (Petrochelidon fluvicola) is a passerine bird, which includes a large number of other species including many swallows. It is native of South Asia where it is a breeder, year-round resident or winter visitor in the countries of Afghanistan, India, Nepal and Pakistan. It occurs as a vagrant in the Maldives, Sri Lanka, and the Middle East.", iucn: "LC" },
  "yebbul3": { extract: "The yellow-browed bulbul (Acritillas indica), or golden-browed bulbul, is a species of songbird in the bulbul family, Pycnonotidae. It is found in the forests of southern India and Sri Lanka. The yellow-browed bulbul is mainly yellow on the underside and olive above with a distinct yellow brow. They are easily located by their loud calls but tend to skulk within foliage below the forest canopy. While its taxonomic classification has changed over time, it is currently the sole species within the monotypic genus Acritillas which is closely related to Hemixos.", iucn: "LC" },
  "sqtbul1": { extract: "The square-tailed bulbul (Hypsipetes ganeesa) is a species of songbird in the bulbul family, Pycnonotidae. It is found in south-western India and Sri Lanka. Its natural habitat is subtropical or tropical moist montane forests. It was previously classified as a subspecies of the black bulbul.", iucn: "LC" },
  "gyhbul1": { extract: "The grey-headed bulbul (Microtarsus priocephalus) is a member of the bulbul family, Pycnonotidae. It is endemic to the Western Ghats in south-western India, and found from Goa south to Tamil Nadu at altitudes up to 1200m. It is found in dense reeds or thickets mainly near rivers and swampy areas inside forests. They have a distinctive call that reveals their presence inside dense vegetation where they are hard to spot.", iucn: "NT" },
  "bkcbul1": { extract: "The flame-throated bulbul (Rubigula gularis) is a member of the bulbul family of passerine birds and the state bird of Goa. It is found only in the forests of the Western Ghats in southern India. Formerly included as a subspecies of Pycnonotus flaviventris, it has since been elevated to the status of a full species. They are olive-backed with yellow undersides, a triangular orange-red throat and a white iris that stands out against the contrasting black head. They are usually seen foraging in groups in the forest canopy for berries and small insects. They have a call often with two or three tinkling notes that can sound similar to those produced by the red-whiskered bulbul. The species has been referred to in the past by names such as ruby-throated bulbul and black-headed bulbul, but these are ambiguous and could apply to other species such as Rubigula flaviventris and R. dispar.", iucn: "LC" },
  "whbbul2": { extract: "The white-browed bulbul (Pycnonotus luteolus) is a member of the bulbul family of passerine birds. It is a resident breeder in Sri Lanka and peninsular India. Largely olive coloured above with whitish underparts, it has a pale supercilium and a yellow vent. They are found in dense scrub habitats, where they skulk within vegetation and can be difficult to see although their loud and distinct burst of calls is distinctive.", iucn: "LC" },
  "yetbul1": { extract: "The yellow-throated bulbul (Pycnonotus xantholaemus) is a species of songbird in the bulbul family of passerine birds. The species is endemic to southern peninsular India. They are found on scrub habitats on steep, rocky hills many of which are threatened by granite quarrying. It is confusable only with the white-browed bulbul with which its range overlaps but is distinctively yellow on the head and throat apart from the yellow vent. The calls of this species are very similar to that of the white-browed bulbul.", iucn: "LC" },
  "rewbul": { extract: "The red-whiskered bulbul (Pycnonotus jocosus), or crested bulbul, is a passerine bird native to Asia. It is a member of the bulbul family. It is a resident frugivore found mainly in tropical Asia. It has been introduced in many tropical areas of the world where populations have established themselves. It has a loud three or four note call, feeds on fruits and small insects and perches conspicuously on trees. It is common in hill forests and urban gardens.", iucn: "LC" },
  "revbul": { extract: "The red-vented bulbul (Pycnonotus cafer) is a member of the bulbul family of passerines. It is a resident breeder across South Asia extending east to Burma. It has been introduced in many other parts of the world and has established itself in Argentina, Tonga and Fiji, as well as parts of Samoa, USA and Cook Islands. It is included in the list of the world's 100 worst invasive alien species. In New Zealand they were the target of a successful extermination campaign in 1955, however they are still sporadically reported.", iucn: "LC" },
  "yebwar3": { extract: "The yellow-browed warbler (Phylloscopus inornatus) is a leaf warbler (family Phylloscopidae) which breeds in the east Palearctic. This warbler is strongly migratory and winters mainly in tropical South Asia and South-east Asia, but also in small numbers in western Europe. Like the rest of Phylloscopidae, it was formerly included in the Old World warbler assemblage. It was formerly considered to comprise three subspecies, but P. i. humei and P. i. mandellii are now split as a separate species, Hume's leaf warbler P. humei, leaving P. inornatus monotypic. The two sister species differ slightly but consistently in morphology, bioacoustics, and molecular characters. Before the species was split, the names yellow-browed willow warbler and inornate warbler were used by a few authors.", iucn: "LC" },
  "humwar1": { extract: "Hume's leaf warbler or Hume's warbler (Phylloscopus humei) is a small leaf warbler which breeds in the mountains of inner Asia. This warbler is migratory and winters mainly in India. The English name and the specific humei commemorate Allan Octavian Hume, a British civil servant and ornithologist based in India. The genus name Phylloscopus is from Ancient Greek phullon, \"leaf\", and skopos, \"seeker\" (from skopeo, \"to watch\"). Like most similar songbirds, it was formerly included in the \"Old World warbler\" assemblage.", iucn: "LC" },
  "tylwar1": { extract: "Tytler's leaf warbler (Phylloscopus tytleri) is a songbird species. Like all leaf warblers, it was formerly placed in the \"Old World warbler\" assemblage, but now belongs to the new leaf-warbler family Phylloscopidae. It is found in Afghanistan, Pakistan, Nepal, and India. It passes through the Western Himalayas to winter in southern India, particularly in the Western Ghats and the Nilgiris. Its natural habitat is subtropical or tropical moist montane forests. It is threatened by habitat loss. It breeds in the Northwestern Himalayan region and is suspected to breed in the Garhwal and Kumaon Himalayas. The name commemorates the British naturalist Robert Christopher Tytler.", iucn: "LC" },
  "subwar2": { extract: "The sulphur-bellied warbler (Phylloscopus griseolus) is a species of leaf-warbler found in the Palearctic region (Afghanistan, Kazakhstan, Kyrgyzstan, Mongolia, Russian Federation [Central Asian Russia], Tajikistan and Turkmenistan). It was earlier also known by the name of olivaceous leaf-warbler. Like other leaf-warblers, it gleans insects from small branches and leaves. It is found in rocky hill and scrub forest habitats. The species is found in small groups and has a tendency to forage low in the vegetation, sometimes even hopping on the ground. It has a single note cheep call.", iucn: "LC" },
  "y00989": { extract: "Tickell's leaf warbler (Phylloscopus affinis) is a leaf warbler found in Asia in the countries of Bangladesh, Bhutan, China, India, Myanmar, Nepal, Pakistan and Thailand. The species has a yellowish underside and supercilium. Like other leaf warblers it feeds mostly on insects by gleaning and short sallies. An active bird, it prefers the canopy and low shrubbery and can be difficult to track as it moves actively from branch to branch, acrobatically exploring the underside of leaves and twigs. The clear yellowish undersides and lack of a wing bar can be used to tell it apart from similar species. It has slim dark legs with largely pale lower mandible and grayish wing panel.", iucn: "LC" },
  "comchi1": { extract: "The common chiffchaff (Phylloscopus collybita), or simply the chiffchaff, is a common and widespread leaf warbler which breeds in open woodlands throughout northern and temperate Europe and the Palearctic. It is a migratory passerine which winters in southern and western Europe, southern Asia and north Africa. Greenish-brown above and off-white below, it is named onomatopoeically for its simple chiff-chaff song. It has a number of subspecies, some of which are now treated as full species. The female builds a domed nest on or near the ground, and assumes most of the responsibility for brooding and feeding the chicks, whilst the male has little involvement in nesting, but defends his territory against rivals, and attacks potential predators. A small insectivorous bird, it is subject to predation by mammals, such as cats and mustelids, and birds, particularly hawks of the genus Accipiter.", iucn: "LC" },
  "grnwar1": { extract: "The green warbler (Phylloscopus nitidus), also known as green willow warbler or green leaf warbler, is a leaf warbler found in the Caucasus Mountains in southeastern Europe. Like all leaf warblers, it was formerly placed in the \"Old World warbler\" assemblage, but now belongs to the new leaf-warbler family Phylloscopidae. The genus name Phylloscopus is from Ancient Greek phullon, \"leaf\", and skopos, \"seeker\" (from skopeo, \"to watch\"). The specific nitidus is from Latin and means \"shining\". It is most closely related to the greenish warbler but is brighter in colour, and the underside is much more yellow. It has one strong and one faint wing bar, especially in young birds.", iucn: "LC" },
  "grewar3": { extract: "The greenish warbler (Phylloscopus trochiloides) is a widespread leaf warbler with a breeding range in northeastern Europe, and temperate to subtropical continental Asia. This warbler is strongly migratory and winters in India. It is not uncommon as a spring or early autumn vagrant in Western Europe and is annually seen in Great Britain. In Central Europe large numbers of vagrant birds are encountered in some years; some of these may stay to breed, as a handful of pairs does each year in Germany. Like all leaf warblers, it was formerly placed in the \"Old World warbler\" assemblage, but now belongs to the new leaf-warbler family Phylloscopidae. The genus name Phylloscopus is from Ancient Greek phullon, \"leaf\", and skopos, \"seeker\" (from skopeo, \"to watch\").", iucn: "LC" },
  "lblwar1": { extract: "The large-billed leaf warbler (Phylloscopus magnirostris) is a species of migratory leaf warbler (family Phylloscopidae) found in Asia. This is a somewhat large leaf warbler with a single wing bar and a prominent yellowish-whitesupercilium. A contrasting broad and dark eye stripe extending behind the eye, a large darkish upper mandible and a distinctive call set it apart from most other leaf warblers in its range. It has a dark crown and greyish ear-coverts. It can be confused with an Arctic warbler. Breeding in central China and the Himalayas, it winters in Sri Lanka, the Western Ghats and associated hill ranges. It is found in dense vegetation. It has also been observed in urban areas on occasion. It is more often heard than seen. The two note dir-tee call with the second note much higher is distinctive.", iucn: "LC" },
  "weclew1": { extract: "The western crowned warbler (Phylloscopus occipitalis) is a leaf warbler which breeds in Central Asia. It winters in the forests of the Western Ghats. It prefers forests with high foliage complexity and tree density. The nest is built in a hole, and the typical clutch is four eggs. The species has a distinctive crown stripe and two wing-bars. It often moves in small flocks or in mixed hunting parties.", iucn: "LC" },
  "leswhi4": { extract: "The lesser whitethroat (Curruca curruca) is a common and widespread Old World warbler which breeds in temperate Europe, except the southwest, and in the western and central Palearctic. This small passerine bird is strongly migratory, wintering in Africa just south of the Sahara, Arabia and India. Unlike many sylviid warblers, the sexes are almost identical. This is a small species with a grey back, whitish underparts, a grey head with a darker \"bandit mask\" through the eyes and a white throat. It is slightly smaller than the common whitethroat, and lacks the chestnut wings and uniform head-face colour of that species. The lesser whitethroat's song is a fast and rattling sequence of tet or che calls, quite different from the common whitethroat's scolding song. Like most \"warblers\", it is insectivorous, but will also take berries and other soft fruit.", iucn: "LC" },
  "eaowar2": { extract: "The eastern Orphean warbler (Curruca crassirostris) is an Old World warbler of the genus Curruca. This species occurs in summer around the Mediterranean, through the Balkans via Turkey, the Caucasus and surrounding regions to Central Asia. It is migratory, wintering in sub-Saharan Africa. At 15–16 cm length—somewhat larger than a blackcap—this is one of the largest species of typical warblers. The adult males have a plain grey back. The bill is long and pointed and the legs black. The male has a dark grey head, black eye mask, and white throat. The iris is white. Females and immatures have a paler head and reddish underparts; their grey back has a brownish tinge. The iris is dark in young birds. It is difficult to visually distinguish from the Western Orphean warbler. The song is a series of warbling liroo-liroo and scolding notes.", iucn: "LC" },
  "yeebab1": { extract: "The yellow-eyed babbler (Chrysomma sinense) is a passerine bird native to South and Southeast Asia. It inhabits shrubland, grassland and wetland habitats. On the IUCN Red List, it is listed as Least Concern because of its wide distribution and stable population. Its common name refers to the traditional placement in the Old World babbler family Timaliidae although the genus Chrysomma forms a clade along with the parrotbills within the family Paradoxornithidae.", iucn: "LC" },
  "indwhe1": { extract: "The Indian white-eye (Zosterops palpebrosus), formerly the Oriental white-eye, is a small species of passerine bird in the white-eye family. It is a resident breeder in open woodland on the Indian subcontinent. They forage in small groups, feeding on nectar and small insects. The distinctive white eye-ring and overall yellowish upperparts easily identify them. The range previously extended eastwards to Southeast Asia, Indonesia, and Malaysia. Their name was recently changed because previous members of Zosterops palpebrosus in Southeast Asia were reclassified as a new species, making the Indian White-eye a more geographically accurate term for this species.", iucn: "LC" },
  "tabbab1": { extract: "The tawny-bellied babbler (Dumetia hyperythra) also known in older Indian works as the rufous-bellied babbler is a small babbler that forages in small groups in low scrub forests. Like other members of the large Old World babbler family they are passerine birds characterised by soft fluffy plumage. There are three subspecies within the Indian subcontinent. The nominate hyperythra found in northern and eastern India is uniformly brown underneath while albogularis of the western Indian peninsula is white throated. The population in Sri Lanka, phillipsi, is also white throated but is paler underneath and has a larger bill.", iucn: "LC" },
  "dafbab1": { extract: "The dark-fronted babbler (Dumetia atriceps) is an Old World babbler found in the Western Ghats of India and the forests of Sri Lanka. They are small chestnut brown birds with a dark black cap, a whitish underside and pale yellow iris. They forage in flocks in the undergrowth of forests constantly making calls and uttering alarm calls when disturbed.", iucn: "LC" },
  "insbab1": { extract: "The Indian scimitar babbler (Pomatorhinus horsfieldii) is an Old World babbler. It is found in peninsular India in a range of forest habitats. They are most often detected by their distinctive calls, which include an antiphonal duet by a pair of birds. They are often hard to see as they forage through dense vegetation. The long, curved yellow, scimitar-shaped bills give them their name. It has been treated in the past as a subspecies of the white-browed scimitar babbler which is found along the Himalayas but now separated into two species, the peninsular Indian species and the Sri Lanka scimitar babbler (Pomatorhinus melanurus).", iucn: "LC" },
  "putbab1": { extract: "The puff-throated babbler or spotted babbler (Pellorneum ruficeps) is a species of passerine bird found in Asia. They are found in scrub and moist forest mainly in hilly regions. They forage in small groups on the forest floor, turning around leaf litter to find their prey and usually staying low in the undergrowth where they can be hard to spot. However, they have loud and distinct calls, including a morning song, contact and alarm calls. It is the type species of the genus Pellorneum which may, however, currently include multiple lineages.", iucn: "LC" },
  "brcful1": { extract: "The brown-cheeked fulvetta (Alcippe poioicephala) is a babbler-like bird belonging to the family Leiothrichidae found in the forests of South and Southeast Asia. It was formerly called the quaker babbler in India and common nun babbler in Malaya. They forage on trees for insects, sometimes hanging from the branches in a tit-like manner, and visiting flowers for nectar. They are often hard to see in vegetation but they have loud multi-note whistling calls in the morning and afternoon.", iucn: "LC" },
  "bkclau1": { extract: "The Banasura laughingthrush or Banasura chilappan (Montecincla jerdoni) is a species of bird in the family Leiothrichidae. It is found in shola habitat in a small section of the Western Ghats in southwestern Karnataka and northern Kerala, India. It was formerly considered a subspecies of the black-chinned laughingthrush.", iucn: "EN" },
  "lagbab2": { extract: "The large grey babbler (Argya malcolmi) is a member of the family Leiothrichidae found across India and far western Nepal. They are locally common in the scrub, open forest and gardenland. They are usually seen in small groups and are easily distinguished from other babblers in the region by their nasal call and the whitish outer feathers to their long tail. It is one of the largest babblers in the region.", iucn: "LC" },
  "rufbab3": { extract: "The rufous babbler (Argya subrufa) is an endemic species of bird found in the Western Ghats of southern India of the family Leiothrichidae It is dark brown and long tailed, and is usually seen foraging in noisy groups along open hillsides with a mixture of grass, bracken and forest.", iucn: "LC" },
  "junbab2": { extract: "The jungle babbler (Argya striata) is a member of the family Leiothrichidae found in the Indian subcontinent. Jungle babblers are gregarious birds that forage in small groups of six to ten birds, a habit that has given them the popular name of \"seven sisters\" in urban Northern India, and (seven brothers) in Bengali, with cognates in other regional languages which also mean \"seven brothers\". The jungle babbler is a common resident breeding bird in most parts of the Indian subcontinent and is often seen in gardens within large cities as well as in forested areas. In the past, the orange-billed babbler Argya rufescens of Sri Lanka was considered to be a subspecies of jungle babbler, but has now been elevated to a species.", iucn: "LC" },
  "yebbab1": { extract: "The yellow-billed babbler (Argya affinis) is a member of the family Leiothrichidae endemic to southern India and Sri Lanka. The yellow-billed babbler is a common resident breeding bird in Sri Lanka and southern India. Its habitat is scrub, cultivation and garden land. This species, like most babblers, is not migratory, and has short rounded wings and a weak flight and is usually seen calling and foraging in groups. It is often mistaken for the jungle babbler, whose range overlaps in parts of southern India, although it has a distinctive call and tends to be found in more vegetated habitats. Its name is also confused with Turdoides leucocephala, which is also known as white-headed babbler.", iucn: "LC" },
  "combab3": { extract: "The common babbler (Argya caudata) is a member of the family of Leiothrichidae. They are found in dry open scrub country mainly in India. Two populations are recognized as subspecies and the populations to the west of the Indus river system are now usually treated as a separate species, the Afghan babbler (Turdoides huttoni). The species is distinctly long-tailed, slim with an overall brown or greyish colour, streaked on the upper plumage and having a distinctive whitish throat.", iucn: "LC" },
  "wynlau1": { extract: "The Wayanad laughingthrush (Pterorhinus delesserti) is a species of laughingthrush in the family Leiothrichidae. It is endemic to the Western Ghats south of Goa in India. These laughingthrushes move in groups in dense forests, producing loud calls but tend to be hard to spot in the undergrowth. They have brown upperparts, a white throat, a broad black mask through the eye and a heavy bill with pale yellow on the lower mandible. Despite the name, derived from the Wayanad region, this species has a wider range than the four other south Indian species of laughingthrush that are restricted to the higher elevation hills.", iucn: "LC" },
  "vefnut1": { extract: "The velvet-fronted nuthatch (Sitta frontalis) is a small passerine bird in the nuthatch family Sittidae found in southern Asia, from Nepal, India, Sri Lanka ‍and Bangladesh east to southwestern China and Indonesia. Like other nuthatches, it feeds on insects in the bark of trees, foraging on the trunks and branches and their strongly clawed toes allow them to climb down tree trunks or move on the undersides of horizontal branches. They are found in forests with good tree cover and are often found along with other species in mixed-species foraging flocks. Adult males can be told apart by the black stripe that runs behind and above the eyes. They have a rapid chipping call note. They breed in tree cavities and holes, often created by woodpeckers or barbets.", iucn: "LC" },
  "chbnut2": { extract: "The Indian nuthatch (Sitta castanea) is a species of bird in the family Sittidae. It is found in Bangladesh, India and Nepal. Its natural habitats are subtropical or tropical dry forests, subtropical or tropical moist lowland forests, and subtropical or tropical moist montane forests. This species has been split by Rasmussen and Anderton (2005) from the chestnut-bellied nuthatch. The Indian nuthatch (including the older prateri of the Eastern Ghats) is found south of the Ganges river. It is the only grey-backed, rufous-bellied nuthatch in the peninsula. Similar to the chestnut-bellied nuthatch but has a smaller bill and a frosty crown that is paler than the mantle. The wing and tail patterns lack contrast and has grey centres to the chestnut undertail coverts.", iucn: "LC" },
  "sohmyn1": { extract: "The southern hill myna (Gracula indica) is a member of the starling family. It is a resident of the forested regions of south India and Sri Lanka. This species moves around in flocks in the forest, and members of a flock keep in contact with a wide range of vocalizations.", iucn: "LC" },
  "eursta": { extract: "The common starling (Sturnus vulgaris), also known simply as the starling in Great Britain and Ireland, and as the European starling in North America, is a medium-sized passerine bird in the starling family, Sturnidae. It is about 20 cm (8 in) long and has glossy black plumage with a metallic sheen, which is speckled with white at some times of the year. The legs are pink and the bill is black in winter and yellow in summer; young birds have browner plumage than the adults. Its gift for mimicry has been noted in literature including the Mabinogion and the works of Pliny the Elder and William Shakespeare.", iucn: "LC" },
  "rossta2": { extract: "The rosy starling (Pastor roseus), also known as the rose-coloured starling, is a passerine bird in the starling family Sturnidae. The species was restored to its own monotypic genus Pastor in 2008, formerly being included in a wide interpretation of the genus Sturnus. This split is supported by further studies, with its closest relative now thought to be the wattled starling (Creatophora cinerea) of tropical Africa, with these two then closest to a large group of Asian starlings and mynas.", iucn: "LC" },
  "aspsta2": { extract: "The Indian pied myna (Gracupica contra) is a species of starling found in the Indian subcontinent. It is usually found in small groups mainly on the plains and low foothills. It is often seen within cities and villages although it is not as bold as the common myna. It produces a range of calls made up of liquid notes.", iucn: "LC" },
  "brasta1": { extract: "The brahminy starling or brahminy myna (Sturnia pagodarum) is a member of the starling family of birds. It is usually seen in pairs or small flocks in open habitats on the plains of the Indian subcontinent.", iucn: "LC" },
  "chtsta2": { extract: "The chestnut-tailed starling (Sturnia malabarica), also called grey-headed starling and grey-headed myna is a member of the starling family. It is a resident or partially migratory species found in wooded habitats in India and Southeast Asia. The species name is after the distribution of a former subspecies in the Malabar region. While the chestnut-tailed starling is a winter visitor to peninsular India, the closely related resident breeding population with a white head is now treated as a full species, the Malabar starling (Sturnia blythii).", iucn: "LC" },
  "malsta1": { extract: "The Malabar starling (Sturnia blythii) is a species of starling found in southwestern India. It was previously considered a subspecies of the chestnut-tailed starling. They nest in tree holes 3-15 mm above the ground. Nestlings eat insects, lepidopteran larvae, beetles, small vertebrates, and nectar.", iucn: "" },
  "commyn": { extract: "The common myna or Indian myna (Acridotheres tristis), sometimes spelled mynah, is a bird in the family Sturnidae, native to Asia. An omnivorous open woodland bird with a strong territorial instinct, the common myna has adapted extremely well to urban environments. The range of the common myna is increasing at such a rapid rate that in 2000 the IUCN Species Survival Commission declared it one of the world's most invasive species and one of only three birds listed among \"100 of the World's Worst Invasive Species\" that pose a threat to biodiversity, agriculture and human interests. In particular, the species poses a serious threat to the ecosystems of Australia, where it was named \"The Most Important Pest/Problem\" in 2008.", iucn: "LC" },
  "banmyn1": { extract: "The bank myna (Acridotheres ginginianus) is a myna found in the northern parts of South Asia. It is smaller but similar in colouration to the common myna, only differing in having brick-red naked skin behind the eyes instead of yellow. It is greyer on the underside and in this and in the presence of a slight tuft of feathers bears some resemblance to the jungle myna. They are found in flocks on the plains of northern and central India, often within towns and cities. Their range appears to be extending southwards into India. The name is derived from their habit of nesting almost exclusively in the earthen banks of rivers, where they excavate burrows and breed in large colonies.", iucn: "LC" },
  "junmyn1": { extract: "The jungle myna (Acridotheres fuscus) is a myna, a member of the starling family. It is found patchily distributed across much of the mainland of the Indian Subcontinent but absent in the arid zones of India. It is easily recognized by the tuft of feathers on its forehead that form a frontal crest, a feature also found in the closely related Javan myna and the pale-bellied myna which were treated as a subspecies in the past. The eyes are pale, yellow or blue depending on the population and the base of the orange-yellow bill is dark. It has also been introduced either intentionally or accidentally into many other parts of the world including Fiji, Taiwan, the Andaman Islands, and parts of Japan. The species has also spread out on its own to some islands in the Pacific.", iucn: "LC" },
  "scathr4": { extract: "The Nilgiri thrush (Zoothera neilgherriensis) is a member of the thrush family.", iucn: "" },
  "piethr1": { extract: "The pied thrush (Geokichla wardii) is a member of the thrush family found in India and Sri Lanka. The males are conspicuously patterned in black and white while the females are olive brown and speckled. They breed in the central Himalayan forests and winter in the hill forests of southern India and Sri Lanka. Like many other thrushes, they forage on leaf litter below forest undergrowth and fly into trees when disturbed and sit still making them difficult to locate.", iucn: "LC" },
  "orhthr1": { extract: "The orange-headed thrush (Geokichla citrina) is a bird in the thrush family. It is common in well-wooded areas of the Indian subcontinent and Southeast Asia. Most populations are resident. The species shows a preference for shady damp areas, and like many Geokichla and Zoothera thrushes, can be quite secretive. The orange-headed thrush is omnivorous, eating a wide range of insects, earthworms and fruit. It nests in trees but does not form flocks. The male of this small thrush has uniform grey upperparts, and an orange head and underparts. The females and young birds have browner upper parts.", iucn: "LC" },
  "eurbla2": { extract: "The Indian blackbird (Turdus simillimus) is a member of the thrush family Turdidae. It was formerly considered a subspecies of the common blackbird. It is found only in India and Sri Lanka. The subspecies from most of the Indian subcontinent, simillimus, nigropileus, bourdilloni and spencei, are small, only 19–20 centimetres (7.5–7.9 inches) long, and have broad eye-rings. They also differ in proportions, wing formula, egg colour and voice from the common blackbird.", iucn: "LC" },
  "ticthr1": { extract: "Tickell's thrush (Turdus unicolor) is a passerine bird in the thrush family Turdidae. It is common in open forest in the Himalayas, and migrates seasonally into peninsular India, Nepal and rarely to Bangladesh. The name commemorates the British ornithologist Samuel Tickell who collected in India and Burma.", iucn: "LC" },
  "eyethr": { extract: "The eyebrowed thrush (Turdus obscurus) is a member of the thrush family Turdidae. It breeds in dense coniferous forest and taiga eastwards from Siberia and Mongolia to Japan. It is strongly migratory, wintering south to China and Southeast Asia. It is a rare vagrant to western Europe.", iucn: "LC" },
  "dasfly": { extract: "The dark-sided flycatcher (Muscicapa sibirica) is a small passerine bird belonging to the genus Muscicapa in the Old World flycatcher family Muscicapidae. It has a wide breeding distribution in the East Palearctic with northern birds migrating south for the winter. It is also known as the Siberian flycatcher or sooty flycatcher, the latter name is also used for the sooty flycatcher (Artomyias infuscata) of Africa.", iucn: "LC" },
  "asbfly": { extract: "The Asian brown flycatcher (Muscicapa dauurica) is a small passerine bird in the flycatcher family Muscicapidae. The word Muscicapa comes from the Latin musca, a fly and capere, to catch. The specific dauurica refers to Dauria, an area of south-eastern Siberia named after a local nomadic tribe. This is an insectivorous species which breeds in Japan, eastern Siberia and the Himalayas. It is migratory and winters in tropical southern Asia from southern India and Sri Lanka east to Indonesia. The correct specific epithet for this species is disputed.", iucn: "LC" },
  "brbfly2": { extract: "The brown-breasted flycatcher or Layard's flycatcher (Muscicapa muttui) is a small passerine bird in the flycatcher family Muscicapidae. The species breeds in north eastern India, central and Southern China and northern Burma and Thailand, and migrates to southern India and Sri Lanka. It forages for insects below the forest canopy, often close to the forest floor.", iucn: "LC" },
  "spofly1": { extract: "The spotted flycatcher (Muscicapa striata) is a small passerine bird in the Old World flycatcher family. It breeds in most of Europe and in the Palearctic to Siberia, and is migratory, wintering in Africa and south western Asia. It is declining in parts of its range. This is an undistinguished looking bird with long wings and tail. The adults have grey-brown upperparts and whitish underparts, with a streaked crown and breast, giving rise to the bird's common name. The legs are short and black, and the bill is black and has the broad but pointed shape typical of aerial insectivores. Juveniles are browner than adults and have spots on the upperparts.", iucn: "LC" },
  "indrob1": { extract: "The Indian robin (Copsychus fulicatus) is a species of passerine bird in the family Muscicapidae. It is widespread in the Indian subcontinent and ranges across Bangladesh, Bhutan, India, Nepal, Pakistan and Sri Lanka. The males of the northern subspecies have brown backs whose extent gradually reduces southwards, with the males of the southern subspecies having all-black backs. They are commonly found in open scrub areas and often seen running along the ground or perching on low thorny shrubs and rocks. The long tail is usually held up and the chestnut undertail coverts and dark body make them easily distinguishable from pied bushchats and Oriental magpie-robins.", iucn: "LC" },
  "magrob": { extract: "The Oriental magpie-robin (Copsychus saularis) is a small passerine bird that was formerly classed as a member of the thrush family Turdidae, but now considered an Old World flycatcher. The males are distinctive black and white birds with a long tail that is held upright as they forage on the ground or perch conspicuously. Occurring across most of the Indian subcontinent and parts of Southeast Asia, they are common birds in urban gardens as well as forests. They are particularly well known for their songs and are popular as cagebirds. The oriental magpie-robin is considered the national bird of Bangladesh.", iucn: "LC" },
  "whrsha": { extract: "The white-rumped shama (Copsychus malabaricus) is a passerine bird in the Old World flycatcher family Muscicapidae. Native to densely vegetated habitats in the Indian subcontinent and Southeast Asia, its popularity as a cage-bird and songster has led to it being introduced elsewhere. The Larwo shama, the Kangean shama and the Sri Lanka shama were formerly considered to be conspecific with the white-rumped shama.", iucn: "LC" },
  "whbsho1": { extract: "The Nilgiri blue robin (Sholicola major), also known as Nilgiri shortwing, white-bellied shortwing, Nilgiri sholakili or rufous-bellied shortwing is a species of passerine bird in the family Muscicapidae endemic to the Shola forests of the higher hills of southern India, mainly north of the Palghat Gap. This small bird is found on the forest floor and undergrowth of dense forest patches sheltered in the valleys of montane grassland, a restricted and threatened habitat. The white-bellied blue robin was formerly considered conspecific with this species but in 2005 the two taxa were split by Pamela C. Rasmussen, a treatment that is followed by some authorities. Their genus remained uncertain until a 2017 molecular phylogenetic study found that these two south Indian species formed a sister group to a clade containing the genera Eumyias, Niltava and Cyornis.", iucn: "EN" },
  "bawfly2": { extract: "The blue-and-white flycatcher (Cyanoptila cyanomelana) is a migratory songbird in the Old World flycatcher family Muscicapidae. The species is also known as the Japanese flycatcher. It breeds in Japan, Korea, and in parts of north eastern China and the Russian Far East. It winters in South East Asia, especially in Vietnam, Cambodia, Thailand, Sumatra and Borneo. This species has been recorded as a vagrant from the Sinharaja Rainforest in Sri Lanka in 2014.", iucn: "LC" },
  "nilfly2": { extract: "The Nilgiri flycatcher (Eumyias albicaudatus) is an Old World flycatcher with a very restricted range in the hills of southern India. It was formerly referred to as the Nilgiri verditer flycatcher because of its similarity to the verditer flycatcher, a winter migrant to the Nilgiris, which, however, has distinct dark lores and a lighter shade of blue. There are two small white patches at the base of the tail. It is found mainly in the higher altitude shola forests of the Western Ghats and the Nilgiris.", iucn: "LC" },
  "verfly4": { extract: "The verditer flycatcher (Eumyias thalassinus) is an Old World flycatcher. It is found from the Himalayas through Southeast Asia to Sumatra. This species is named after its distinctive shade of copper-sulphate blue and has a dark patch between the eyes and above the bill base. The adult males are intense blue on all areas of the body, except for the black eye-patch and grey vent. Adult females and sub-adults are lighter blue. The verditer flycatcher is also interesting among the flycatchers in that they forage above the canopy level and perch on electric wires or exposed tree top branches. This species was earlier placed in the genus Muscicapa and it has been suggested that it is closer to the Niltava flycatchers.", iucn: "LC" },
  "wbbfly1": { extract: "The white-bellied blue flycatcher (Cyornis pallidipes) is a small passerine bird in the flycatcher family Muscicapidae. It is endemic to the Western Ghats (including the Nilgiris) of southwest India. Males are dark blue with a lighter shade of blue on the brow and have a greyish white belly. Females have a rufous breast, a white face and olive grey above.", iucn: "LC" },
  "butfly1": { extract: "The blue-throated blue flycatcher (Cyornis rubeculoides) is a small passerine bird in the flycatcher family, Muscicapidae. It resembles Cyornis tickelliae but easily separated by the blue throat. The habitat of this species is a thicker forest than other species of flycatchers. The blue-throated flycatcher is found in much of the Indian subcontinent, all through the Himalayas, the plains and Western Ghats of India in the cold months, and also extends eastwards into Bangladesh, and to Arakan and the Tenasserim Hills in Myanmar.", iucn: "LC" },
  "tibfly3": { extract: "Tickell's blue flycatcher (Cyornis tickelliae) is a small passerine bird in the flycatcher family. This is an insectivorous species which breeds in tropical Asia, from the Indian subcontinent eastwards to Bangladesh and western Myanmar. The Indochinese blue flycatcher was formerly considered conspecific. They are blue on the upperparts and the throat and breast are rufous. They are found in dense scrub to forest habitats. The name commemorates the wife of the British ornithologist Samuel Tickell who collected in India and Burma.", iucn: "LC" },
  "inbrob1": { extract: "The Indian blue robin (Larvivora brunnea) is a small bird found in the Indian subcontinent. Formerly considered a thrush, it is now considered one of the Old World flycatchers in the family Muscicapidae. It was earlier also called the Indian blue chat. It is migratory, breeding in the forests along the Himalayas of Nepal, India, Myanmar and Bangladesh. They winter in the hill forests of the Western Ghats of India and in Sri Lanka.", iucn: "LC" },
  "blueth": { extract: "The bluethroat (Luscinia svecica) is a small passerine bird in the Old World flycatcher family. It is a migratory insectivorous species breeding in wet birch wood or bushy swamp in Europe and across the Palearctic with a foothold in western Alaska. It nests in tussocks or low in dense bushes. It winters in the Iberian Peninsula, the northern half of Africa, and in southern Asia (among others including the Indian subcontinent). The bluethroat, and similar small European flycatchers, are often called chats. The bluethroat is similar in size to the European robin at 13–14 cm. It is plain brown above except for the distinctive tail, brown with black outer corners and red basal side patches. It has a strong white supercilium.", iucn: "LC" },
  "mawthr1": { extract: "The Malabar whistling thrush (Myophonus horsfieldii) is a whistling thrush in the family Muscicapidae. The bird has been called whistling schoolboy for the whistling calls that they make at dawn that have a very human quality. The species is a resident in the Western Ghats and associated hills of peninsular India including central India and parts of the Eastern Ghats.", iucn: "LC" },
  "sibrub": { extract: "The Siberian rubythroat (Calliope calliope) is a small passerine bird first described by Peter Simon Pallas in 1776. It was formerly classed as a member of the thrush family, Turdidae, but is now more generally considered to be an Old World flycatcher of the family Muscicapidae. The Siberian rubythroat and similar small European species are often called chats.", iucn: "LC" },
  "himrub1": { extract: "The Himalayan rubythroat (Calliope pectoralis) is a species of passerine bird in the family Muscicapidae. It is closely related to the Siberian rubythroat which however lacks the distinctive white tail-tips and white tail bases. It was also previously considered conspecific with the Chinese rubythroat, together called the white-tailed rubythroat. It is found along the Tien Shan and Himalayan ranges from Afghanistan to Myanmar. Three subspecies are recognized across its wide range.", iucn: "LC" },
  "korfly1": { extract: "The yellow-rumped flycatcher (Ficedula zanthopygia), also known as Korean flycatcher or tricolor flycatcher, is a species of flycatcher found in eastern Asia. A distinctive species with almost no look-alike other than the narcissus flycatcher. It breeds in eastern Asia including parts of Mongolia, Transbaikal, southern China, Korea and western Japan. They winter in parts of the Malay Peninsula and South Asia.", iucn: "LC" },
  "barfly1": { extract: "The black-and-orange flycatcher (Ficedula nigrorufa) or black-and-rufous flycatcher is a species of flycatcher endemic to the central and southern Western Ghats, the Nilgiris and Palni hill ranges in southern India. It is unique among the Ficedula flycatchers in having rufous coloration on its back and prior to molecular studies was suggested to be related to the chats and thrushes.", iucn: "LC" },
  "ultfly1": { extract: "The ultramarine flycatcher or the white-browed blue flycatcher (Ficedula superciliaris) is a small arboreal Old World flycatcher in the Ficedula genus. Its breeding range extends from eastern Afghanistan to the Hengduan Mountains; it winters in India and northwestern Indochina.", iucn: "LC" },
  "rutfly6": { extract: "The rusty-tailed flycatcher (Ficedula ruficauda) is a small passerine bird in the flycatcher family Muscicapidae. It is found mainly in the northern regions of the Indian subcontinent and some parts of southwest India, as well as pockets of Central Asia including Uzbekistan and Tajikistan. The species is partially migratory, with the Central Asian populations migrating to India, as far as the southwest Indian coast along the Arabian Sea, to Karnataka and Kerala. Other populations, especially those across the lower Himalayas, remain in their native regions year-round and breed there. The species is also an occasional vagrant to other areas in India. The rusty-tailed flycatcher is 14 cm (5.5 in) in length and weighs 11–16 g (0.39–0.56 oz). The sexes have similar plumage.", iucn: "LC" },
  "taifly1": { extract: "The taiga flycatcher or red-throated flycatcher (Ficedula albicilla) is a migratory bird in the family Muscicapidae. The species was first described by Peter Simon Pallas in 1811. The female has brown upper parts with a blackish tail flanked by white. The breast is buffish with underparts mostly white. The male has ear coverts and sides of the neck blue-tinged grey with breeding males having orange-red coloration on the throats. Unlike the taiga flycatcher, the female of the similar red-breasted flycatcher has a brown tail while the red colour in breeding males extends to the breast in the red-breasted flycatcher. It breeds in northern Eurasia from eastern Russia to Siberia and Mongolia. It is a winter visitor to South and South-east Asia in Bangladesh, Bhutan, India, Cambodia, Laos, Myanmar, Nepal, Malaysia, Thailand, China, Vietnam, and Japan. Its natural habitat is taiga forest.", iucn: "LC" },
  "kasfly1": { extract: "The Kashmir flycatcher (Ficedula subrubra) is a small passerine bird in the flycatcher family Muscicapidae. It breeds in the Northwest Himalayas and winters in southern India and Sri Lanka. It was formerly considered to be a subspecies of the red-breasted flycatcher, Ficedula parva, which is its closest living relative. Males are distinctive in having a blackish border to the reddish throat while the females can easily be confused with those of F. parva.", iucn: "VU" },
  "rebfly": { extract: "The red-breasted flycatcher (Ficedula parva) is a small passerine bird in the Old World flycatcher family. It breeds in eastern Europe and across Central Asia and is migratory, wintering in south Asia. The breeding male is mainly muted brown above and white below, with a grey head and an orange throat. Females and immatures are similarly colored but lack the orange throat patch. The red-breasted flycatcher is a regular passage migrant in western Europe, whereas the collared flycatcher, which has a different migration route (wintering in Sub-Saharan Africa), is scarce. It forms a superspecies with the closely related taiga flycatcher and Kashmir flycatcher and can be distinguished from the former by its different song, warmer-toned plumage and the more extensive orange throat patch.", iucn: "LC" },
  "blared1": { extract: "The black redstart (Phoenicurus ochruros) is a small passerine bird in the Old World flycatcher family. It is a widespread breeder in rocky habitats across Eurasia and North Africa, from the British Isles south to Morocco and east to central China. It is resident in the milder parts of its range, but northern and eastern birds migrate.", iucn: "LC" },
  "bcrthr1": { extract: "The blue-capped rock thrush (Monticola cinclorhyncha) is a species of bird in the family Muscicapidae.", iucn: "LC" },
  "rtrthr1": { extract: "The common rock thrush (Monticola saxatilis), also known as the rufous-tailed rock thrush or simply rock thrush, is a species of chat that breeds in southern Europe across Central Asia to northern China. This species is strongly migratory, all populations wintering in Africa south of the Sahara. It is an uncommon visitor to northern Europe. Its range has contracted somewhat at the periphery in recent decades due to habitat destruction. For example, in the early 20th century it bred in the Jura Krakowsko-Częstochowska (Poland) where none occur today, but it is not considered globally endangered.", iucn: "LC" },
  "burthr": { extract: "The blue rock thrush (Monticola solitarius) is a species of chat. This thrush-like Old World flycatcher was formerly placed in the family Turdidae. It breeds in southern Europe, northwest Africa, and from Central Asia to northern China and Malaysia. The blue rock thrush is the official national bird of Malta.", iucn: "LC" },
  "whinch1": { extract: "The whinchat (Saxicola rubetra) is a small migratory passerine bird breeding in Europe and western Asia and wintering in central Africa. At one time considered to be in the thrush family, Turdidae, it is now placed in the Old World flycatcher family, Muscicapidae. Both sexes have a strong supercilium, brownish upper parts mottled darker, a pale throat and breast, a pale buff to whitish belly, and a blackish tail with white bases to the outer tail feathers, but in the breeding season, the male has an orange-buff throat and breast. The whinchat is a solitary species, favouring open grassy country with rough vegetation and scattered small shrubs. It perches in elevated locations ready to pounce on the insects and other small invertebrates that form its diet. The nest is built by the female on the ground in coarse vegetation, with a clutch of four to seven eggs being laid.", iucn: "LC" },
  "sibsto1": { extract: "The Siberian stonechat or Asian stonechat (Saxicola maurus) is a recently validated species of the Old World flycatcher family (Muscicapidae). Like the other thrush-like flycatchers, it was often placed in the Turdidae in the past. It breeds in the East Palearctic including in easternmost Europe and winters in the Old World tropics.", iucn: "" },
  "piebus1": { extract: "The pied bush chat (Saxicola caprata) is a small passerine bird found ranging from West Asia and Central Asia to the Indian subcontinent and Southeast Asia. About sixteen subspecies are recognized through its wide range with many island forms. It is a familiar bird of countryside and open scrub or grassland where it is found perched at the top of short thorn trees or other shrubs, looking out for insect prey. They pick up insects mainly from the ground, and were, like other chats, placed in the thrush family Turdidae, but are now considered as Old World flycatchers. They nest in cavities in stone walls or in holes in an embankment, lining the nest with grass and animal hair. The males are black with white shoulder and vent patches whose extent varies among populations. Females are predominantly brownish while juveniles are speckled.", iucn: "LC" },
  "grybus1": { extract: "The grey bush chat (Saxicola ferreus) is a species of passerine bird in the family Muscicapidae. It is found in the Himalayas, southern China, Taiwan, Nepal and mainland Southeast Asia. Its natural habitats are subtropical or tropical moist lowland forest and subtropical or tropical moist montane forest.", iucn: "LC" },
  "norwhe": { extract: "The northern wheatear or wheatear (Oenanthe oenanthe) is a small passerine bird in the Old World flycatcher family. It is the most widespread member of the wheatear genus Oenanthe in Europe and North and Central Asia. The northern wheatear is a migratory insectivorous species breeding in open stony country in Europe and east across the Palearctic with footholds in northeastern Canada and Greenland as well as in northwestern Canada and Alaska. It nests in rock crevices and rabbit burrows. All birds spend most of their winter in Africa.", iucn: "LC" },
  "isawhe1": { extract: "The isabelline wheatear (Oenanthe isabellina) is a small passerine bird that was formerly classed as a member of the thrush family Turdidae, but is now more generally considered to be an Old World flycatcher in the family Muscicapidae. It is a migratory insectivorous bird. Its habitat is steppe and open countryside and it breeds in southern Russia and Central Asia to northern Pakistan, wintering in Africa and northwestern India. It is a very rare vagrant to western Europe. In colouring it resembles a female northern wheatear but it is larger at 15–16.5 centimetres (5.9–6.5 in) in length, more upright and more tawny in colour, and has more black on its tail. The term isabelline refers to the parchment-like colouration. The axillaries and underwing coverts are white, whereas in the commoner bird they are mottled with grey. The sexes are similar.", iucn: "LC" },
  "deswhe1": { extract: "The desert wheatear (Oenanthe deserti) is a wheatear, a small passerine bird that was formerly classed as a member of the thrush family Turdidae, but is now more generally considered to be an Old World flycatcher (Muscicapidae). It is a migratory insectivorous species, 14.5 to 15 cm (5.7 to 5.9 in) in length. Both western and eastern forms of the desert wheatear are rare vagrants to western Europe. The western desert wheatear breeds in the Sahara and the northern Arabian Peninsula. The eastern race is found in the semi-deserts of Central Asia and in winter in Pakistan and northeast Africa. The plumage of the upper parts of the male in summer is buff. The underparts are white with a buff tinge on the breast. The black on the face and throat extends to the shoulders, and there is distinct white superciliary stripe.", iucn: "LC" },
  "piewhe1": { extract: "The pied wheatear (Oenanthe pleschanka) is a wheatear, a small insectivorous passerine bird that was formerly classed as a member of the thrush family Turdidae, but is now more generally considered to be an Old World flycatcher (family Muscicapidae). This migratory central Asiatic wheatear occurs from the extreme southeast of Europe to China, and has been found wintering in India and northeastern Africa. It is a very rare vagrant to western Europe. The male is a boldly marked white-and-black bird. The white crown tinged with brown contrasts with the black face and throat and white rump. The female is browner, and the head is washed with sandy buff. Females are darker than the females of the northern wheatear, look smaller and show less white on the rump.", iucn: "LC" },
  "indcha1": { extract: "The brown rock chat (Oenanthe fusca) or Indian chat is a bird species of the family Muscicapidae. It is found mainly in northern and central India. It is often found in old buildings and rocky areas. It resembles a female Indian robin but lacks the reddish vent and differs in posture and behaviour apart from being larger. In flight it bears some resemblance to thrushes and redstarts. It feeds on insects, captured mainly on the ground. It was formerly placed as the sole species in the genus Cercomela but is now included with the wheatears in the genus Oenanthe. In central India, the local name of Shama has been noted.", iucn: "LC" },
  "thbflo1": { extract: "The thick-billed flowerpecker (Pachyglossa agilis) is a tiny bird in the flowerpecker group. They feed predominantly on fruits and are active birds that are mainly seen in the tops of trees in forests. It is a resident bird with a wide distribution across tropical southern Asia from India east to Indonesia and Timor with several populations recognized as subspecies some of which are sometimes treated as full species. This species was formerly placed in the genus Dicaeum.", iucn: "LC" },
  "pabflo1": { extract: "The pale-billed flowerpecker or Tickell's flowerpecker (Dicaeum erythrorhynchos) is a tiny bird that feeds on nectar and berries, found in India, Sri Lanka, Bangladesh and western Myanmar. The bird is common especially in urban gardens with berry bearing trees. They have a rapid chipping call and the pinkish curved beak separates it from other species in the region.", iucn: "LC" },
  "plaflo1": { extract: "The Nilgiri flowerpecker (Dicaeum concolor) is a tiny bird in the flowerpecker family. Formerly a subspecies of what used to be termed as the plain flowerpecker although that name is now reserved for Dicaeum minullum. Like others of the group, it feeds predominantly on nectar and fruits. They forage within the canopy of forests and are found in India. They are non-migratory and the widespread distribution range includes several populations that are non-overlapping and morphologically distinct, some of which are recognized as full species. They are important pollinators and dispersers of mistletoes in forests.", iucn: "LC" },
  "pursun3": { extract: "The purple-rumped sunbird (Leptocoma zeylonica) is a sunbird endemic to the Indian Subcontinent. Like other sunbirds, they are small in size, feeding mainly on nectar but sometimes take insects, particularly when feeding young. They can hover for short durations but usually perch to lap nectar from flowers. They build a hanging pouch nest made up of cobwebs, lichens and plant material. Males are contrastingly coloured but females are olive above and yellow to buff below. Males are easily distinguished from the purple sunbird by the light coloured underside while females can be told apart from males by their whitish throats.", iucn: "LC" },
  "crbsun2": { extract: "The crimson-backed sunbird or small sunbird (Leptocoma minima) is a sunbird endemic to the Western Ghats of India. Like other sunbirds, they feed mainly on nectar although they take insects, especially to feed their young. They are tiny birds that are resident and are found in forests but are particularly attracted to gardens at the edge of the forest where people grow suitable flower-bearing plants. They usually perch while taking nectar.", iucn: "LC" },
  "pursun4": { extract: "The purple sunbird (Cinnyris asiaticus) is a small bird in the sunbird family. It occurs in parts of the Arabian peninsula and South and Southeast Asia. It has a fast and direct flight and can take nectar by hovering like a hummingbird but often perches at the base of flowers. It feeds mainly on nectar and insects, especially when feeding young. The males can appear all black in harsh sunlight but the purple iridescence is visible on closer observation or under good light conditions. Females are olive above and yellowish below.", iucn: "LC" },
  "lobsun2": { extract: "Loten's sunbird (Cinnyris lotenius), also known as the long-billed sunbird or maroon-breasted sunbird, is a sunbird endemic to peninsular India and Sri Lanka. Named after Joan Gideon Loten, who was the Dutch governor of colonial Ceylon, it is very similar to the purple sunbird that is found in the same areas and also tends to hover at flowers for nectar, but can be distinguished by the longer bill, the maroon band on the breast and brownish wings. Like other sunbirds, it is also insectivorous and builds characteristic hanging nests.", iucn: "LC" },
  "wecsun1": { extract: "Vigors's sunbird (Aethopyga vigorsii), Sahyadri sunbird, or western crimson sunbird, is a species of sunbird which is endemic to the Western Ghats of India. It has been considered as a subspecies of the crimson sunbird (Aethopyga siparaja) but it does not have the central tail as elongated and is restricted in its distribution. The male has a scarlet throat and breast, while the rest of its under parts are uniformly grey. Its wings are grey-brown and lack yellowish-olive edges. However, it is yellow on the lower back and tail is bottle green. The female's upperparts are dark olive, while its underparts are grey. A male who has not yet matured is similar to the female, but it has a dull scarlet throat and breast. The species is distributed mainly in the northern Western Ghats but has been reported from the Nilgiris.", iucn: "LC" },
  "litspi1": { extract: "The little spiderhunter (Arachnothera longirostra) is a species of long-billed nectar-feeding bird in the family Nectariniidae found in the moist forests of South and Southeast Asia. Unlike typical sunbirds, males and females are very similar in plumage. They are usually seen in ones or twos and frequently make a tzeck call. They are most often found near flowering plants where they obtain nectar.", iucn: "LC" },
  "asfblu1": { extract: "The Asian fairy-bluebird (Irena puella) is a medium-sized, arboreal passerine bird. This fairy-bluebird is found in forests across tropical southern Asia, Indochina and the Greater Sundas. Two or three eggs are laid in a small cup nest in a tree. It was described by British ornithologist John Latham in 1790. The only other member of the genus and family is the Philippine fairy-bluebird, I. cyanogastra, which replaces the Asian fairy-bluebird in most of the Philippines. Both species are considered as sacred to the Tagalog people as they are perceived as tigmamanukan omens. The adult Asian fairy bluebird is about 24 to 27 centimetres (9.4 to 10.6 in). The male has glossy, iridescent blue upperparts, and black underparts and flight feathers. The female and first year male are entirely dull blue-green. The Asian fairy bluebird eats fruits, nectar and some insects.", iucn: "LC" },
  "jerlea1": { extract: "Jerdon's leafbird (Chloropsis jerdoni) is a species of leafbird found in forest and woodland in India and Sri Lanka. Its name honours Thomas C. Jerdon. It has traditionally been considered a subspecies of the blue-winged leafbird (C. cochinchinensis), but differ in measurements and morphology, it lacking the blue flight feathers for which the blue-winged leafbird was named. It builds its nest in a tree, and lays 2–3 eggs. This species eats insects, fruit and nectar. The male is green-bodied with a yellow-tinged head, black face and throat. It has a blue moustachial line. The female differs in that it has a greener head and blue throat, and young birds are like the female but without the blue throat patch. Like other leafbirds, the call of Jerdon's leafbird consists of a rich mixture of imitations of the calls of various other species of birds.", iucn: "LC" },
  "goflea1": { extract: "The golden-fronted leafbird (Chloropsis aurifrons) is a species of leafbird. It is found from the Indian subcontinent and south-western China, to south-east Asia and Sumatra. It builds its nest in a tree, laying 2-3 eggs. This species eats insects and berries.", iucn: "LC" },
  "strwea2": { extract: "The streaked weaver (Ploceus manyar) is a species of weaver bird found in South Asia and South-east Asia in the countries of Bangladesh, Bhutan, Cambodia, China, Egypt, India, Indonesia, Myanmar, Nepal, Pakistan, Singapore, Sri Lanka, Thailand, Vietnam and also introduced in Qatar and United Arab Emirates (UAE). These are not as common as the baya weaver but are similar looking but have streaked underparts. They nest in small colonies often in reed beds near water bodies.", iucn: "LC" },
  "baywea1": { extract: "The baya weaver (Ploceus philippinus) is a weaverbird found across the Indian subcontinent and Southeast Asia. Flocks are found in grasslands, cultivated areas, scrub and secondary growth. They are known for their hanging retort shaped nests woven from leaves, usually found on thorny trees or palm fronds, near or hanging over water where predators cannot easily reach. They are widespread and common within their range and are prone to local, seasonal movements in response to rain and food availability. Five subspecies are recognised. The nominate race P. p. philippinus is found through much of mainland India while P. p. burmanicus is found eastwards into Southeast Asia. The population in southwest India is darker above and referred to as subspecies P. p. travancoreensis.", iucn: "LC" },
  "benwea1": { extract: "The black-breasted weaver (Ploceus benghalensis), also known as the Bengal weaver or black-throated weaver, is a weaver resident in the northern river plains of the Indian subcontinent. Like the other weavers, the males build an enclosed nest from reeds and mud, and visiting females select a mate at least partially based on the quality of the nest.", iucn: "LC" },
  "zebfin2": { extract: "The Sunda zebra finch (Taeniopygia guttata) is a species of bird in the family Estrildidae. It is found in the Lesser Sundas. For almost two centuries, its closest relative from Australia was generally included in T.guttata as a subspecies; since the 2020s it is generally considered a separate species Taeniopygia castanotis. Most pre-2020 literature referencing \"T.guttata\" actually refers to the birds now known as T.castanotis – in particular physiological, neurological and behavioral studies generally used \"T.guttata\" for the Australian species, because T.guttata sensu stricto was never kept in captivity in significant numbers, and thus was unavailable for such research.", iucn: "LC" },
  "indsil": { extract: "The Indian silverbill or white-throated munia (Euodice malabarica) is a small passerine bird found in the Indian subcontinent and adjoining regions that was formerly considered to include the closely related African silverbill (Euodice cantans). This estrildid finch is a common resident breeding bird in the drier regions of the Middle East and the Indian subcontinent. It has also been introduced into many other parts of the world and has become established in some areas. They forage in small flocks in grassland and scrub habitats.", iucn: "LC" },
  "javspa": { extract: "The Java sparrow (Padda oryzivora; syn. Lonchura oryzivora), also known as the Java finch, Java rice sparrow or Java rice bird, is a small passerine bird. This species in the family Estrildidae is a resident breeding bird in Java, Bali, and Bawean in Indonesia. It is a popular cage bird, and has been introduced into many other countries.", iucn: "EN" },
  "nutman": { extract: "The scaly-breasted munia or spotted munia (Lonchura punctulata), known in the pet trade as nutmeg mannikin or spice finch, is a sparrow-sized estrildid finch native to tropical Asia. A species of the genus Lonchura, it was formally described and named by Carl Linnaeus in 1758. Its name is based on the distinct scale-like feather markings on the breast and belly. The adult is brown above and has a dark conical bill. The species has 11 subspecies across its range, which differ slightly in size and colour. This munia eats mainly grass seeds apart from berries and small insects. They forage in flocks and communicate with soft calls and whistles. The species is highly social and may sometimes roost with other species of munias. This species is found in tropical plains and grasslands. Breeding pairs construct dome-shaped nests using grass or bamboo leaves.", iucn: "LC" },
  "bltmun1": { extract: "The black-throated munia or Jerdon's mannikin (Lonchura kelaarti) is a small passerine bird. This estrildid finch is a resident breeding bird in the hills of southwest India, the Western Ghats, Eastern Ghats and Sri Lanka.", iucn: "LC" },
  "whrmun": { extract: "The white-rumped munia (Lonchura striata) or white-rumped mannikin, sometimes called striated finch in aviculture, is a small passerine bird from the family of waxbill \"finches\" (Estrildidae). These are not close relatives of the true finches (Fringillidae) or true sparrows (Passeridae). It is native to tropical continental Asia and some adjacent islands, and has been naturalized in some parts of Japan. Its domesticated descendant, the society finch or Bengalese finch, is found worldwide as a pet and a biological model organism.", iucn: "LC" },
  "trimun": { extract: "The tricoloured munia (Lonchura malacca) is an estrildid finch, native to Bangladesh, India, Sri Lanka, Pakistan, and southern China. The species has also been introduced to the Caribbean, in Trinidad, Jamaica, Hispaniola, Puerto Rico, Cuba, and Venezuela. This species, like the chestnut munia has been known as the black-headed munia. Immature birds have pale brown upperparts, lack the dark head found in adults, and have uniform buff underparts that can be confused with immatures of other munias such as the scaly-breasted munia.", iucn: "LC" },
  "redava": { extract: "The red avadavat (Amandava amandava), red munia or strawberry finch, is a sparrow-sized bird of the family Estrildidae. It is found in the open fields and grasslands of tropical Asia and is popular as a cage bird due to the colourful plumage of the males in their breeding season. It breeds in the Indian subcontinent in the monsoon season. The species name of amandava and the common name of avadavat are derived from the city of Ahmedabad in Gujarat, India, from where these birds were exported into the pet trade in former times.", iucn: "LC" },
  "houspa": { extract: "The house sparrow (Passer domesticus) is a bird of the sparrow family Passeridae, found in most parts of the world. It is a small bird that has a typical length of 16 cm (6.3 in) and a mass of 24–39.5 g (0.85–1.39 oz). Females and young birds are coloured pale brown and grey, and males have brighter black, white, and brown markings. One of 28 species in the genus Passer, the house sparrow is native to most of Europe, the Mediterranean Basin, and a large part of Asia. Its intentional or accidental introductions to many regions, including parts of Australasia, Africa, and the Americas, make it the most widely distributed wild bird. The house sparrow is strongly associated with human habitation, and can live in urban or rural settings.", iucn: "LC" },
  "chspet1": { extract: "The yellow-throated sparrow or chestnut-shouldered petronia (Gymnoris xanthocollis) is a species of sparrow found in southern Asia. It is a species mostly of the dry savannah. They forage on the ground for grain and for berries in bushes. They are often seen perched atop bare branches on trees while calling.", iucn: "LC" },
  "palroc1": { extract: "The pale rockfinch or pale rock sparrow (Carpospiza brachydactyla) is a small sparrow found in the Middle East and Central Asia. It is the only member of the genus Carpospiza. Some authorities include it in the genus Petronia. Others have placed it in the finch family due to some similarities in behaviour and form, but the anatomy of its tongue exhibits characteristic sparrow features. The range of pale rockfinch extends from eastern Turkey to Afghanistan, and south into the Arabian Peninsula and northern Africa as far as Ethiopia. Its natural habitats are subtropical or tropical dry shrubland and temperate grassland. The breeding pattern of the pale rock sparrow is associated with specific aspects of habitat. Presence of this species is associated with temperature, grasshopper and beetle abundance, whereas density is associated with available habitat.", iucn: "LC" },
  "forwag1": { extract: "The forest wagtail (Dendronanthus indicus) is a medium-sized passerine bird in the wagtail family Motacillidae. It has a distinctive plumage that sets it apart from other wagtails and has the habit of wagging its tail sideways unlike the usual up and down movements of the other wagtail species. It is the only wagtail species that nests in trees. It is found mainly in forested habitats, breeding in the temperate parts of east Asia and wintering across tropical Asia from India to Indonesia.", iucn: "LC" },
  "grywag": { extract: "The grey wagtail (Motacilla cinerea) is a member of the wagtail family, Motacillidae, measuring around 18–19 cm overall length. The species looks somewhat similar to the yellow wagtail but has the yellow on its underside restricted to the throat and vent. Breeding males have a black throat. The species is widely distributed, with several populations breeding in Eurosiberia and migrating to tropical regions in Asia and Africa. The species is always associated with running water when breeding, although they may use man-made structures near streams for the nest. Outside the breeding season, they may also be seen around lakes, coasts and other watery habitats. Like other wagtails, they frequently wag their tail and fly low with undulations and they have a sharp call that is often given in flight.", iucn: "LC" },
  "eaywag1": { extract: "The western yellow wagtail (Motacilla flava) is a small passerine bird in the wagtail family Motacillidae, which also includes the pipits and longclaws. This species breeds in much of temperate Europe and Asia. Most populations are migratory, moving south to tropical Africa and southern Asia for the winter; the small population breeding in Egypt is however resident there. It is a slender 15–16 cm long bird, with the characteristic long, constantly wagging tail of its genus. It is the shortest tailed of the European wagtails. The breeding adult male is basically olive above and yellow below. In other plumages, particularly in juveniles, the yellow may be diluted to whitish. The heads of breeding males come in a variety of colours and patterns depending on subspecies. The call is a high-pitched jeet. This insectivorous bird inhabits open country near water, such as wet meadows.", iucn: "LC" },
  "eaywag": { extract: "The eastern yellow wagtail (Motacilla tschutschensis) is a small passerine in the wagtail family Motacillidae, which also includes the pipits and longclaws. It was formerly usually classified as a subspecies of the western yellow wagtail, but was split from it in 2003 when genetic data showed this classification to be paraphyletic with respect to the citrine wagtail. It breeds in the eastern Palearctic and Alaska and migrates to South Asia and Australia.", iucn: "LC" },
  "citwag": { extract: "The citrine wagtail (Motacilla citreola) is a small songbird in the family Motacillidae.", iucn: "LC" },
  "whbwag1": { extract: "The white-browed wagtail or large pied wagtail (Motacilla maderaspatensis) is a medium-sized bird and is the largest member of the wagtail family. They are conspicuously patterned with black above and white below, a prominent white brow, shoulder stripe and outer tail feathers. White-browed wagtails are native to the Indian subcontinent, common near small water bodies and have adapted to urban environments where they often nest on roof tops. The specific name is derived from the Indian city of Madras (now Chennai).", iucn: "LC" },
  "whiwag": { extract: "The white wagtail (Motacilla alba) is a small passerine bird in the family Motacillidae, which also includes pipits and longclaws. The species breeds in the Palearctic zone in most of Europe and Asia and parts of North Africa; it also has a toehold in western Alaska as a scarce breeder. It is resident in the mildest parts of its range, but otherwise migrates to Africa. In total, there are between 9 and 11 subspecies of M. alba; in Ireland and Great Britain, the black-backed subspecies known as the pied wagtail (M. a. yarrellii) predominates. The white wagtail is an insectivorous bird of open country, often near habitation and water. It prefers bare areas for feeding, where it can see and pursue its prey. In urban areas, it has adapted to foraging on paved areas such as car parks. It nests in crevices in stone walls and similar natural and human-made structures.", iucn: "LC" },
  "ricpip1": { extract: "Richard's pipit (Anthus richardi) is a medium-sized passerine bird which breeds in open grasslands in the East Palearctic. It is a long-distance migrant moving to open lowlands in the Indian subcontinent and Southeast Asia. It is a rare but regular vagrant to western Europe. The genus name Anthus is the Latin name for a small bird of grasslands. The English name and richardi are for the French naturalist Charles Richard (1745–1835), director of postal services at Lunéville and friend of Francois Levaillant. It belongs to the pipit genus Anthus in the family Motacillidae. It was formerly lumped together with the Australasian, African, mountain and paddyfield pipits in a single species: Richard's pipit, Anthus novaeseelandiae. These pipits are now commonly considered to be separate species although the African and paddyfield pipits are sometimes treated as part of A. richardi.", iucn: "LC" },
  "oripip1": { extract: "The paddyfield pipit or Oriental pipit (Anthus rufulus) is a small passerine bird in the pipit and wagtail family. It is a resident (non-migratory) breeder in open scrub, grassland and cultivation in southern Asia east to the Philippines. Although among the few breeding pipits in the Asian region, identification becomes difficult in winter when several other species migrate into the region. The taxonomy of the species is complex and has undergone considerable changes.", iucn: "LC" },
  "lobpip1": { extract: "The long-billed pipit or brown rock pipit (Anthus similis) is a passerine bird which has a wide distribution. A number of subspecies have been created for the populations in Africa, through the Arabian Peninsula and South Asia. The systematics of this complex is yet to be clarified. Most birds are residents or short distance migrants.", iucn: "LC" },
  "blypip1": { extract: "Blyth's pipit (Anthus godlewskii) is a medium-sized passerine bird which breeds in Mongolia and neighbouring areas of China, Tibet and India . It is a long distance migrant moving to open lowlands in Southern Asia. It is a very rare vagrant to western Europe. This is a large pipit, but is an undistinguished looking species on the ground, mainly brown above and pale below. It is very similar to Richard's pipit, but is slightly smaller, shorter legs and a shorter dark bill. Its flight is strong and direct, and it gives a characteristic \"pshee\" call, higher pitched than Richard's. In south Asia, in winter some care must be taken to distinguish this from other large pipits which winter or are resident in the area, including Richard's. This species is insectivorous. This bird was named after the English zoologist Edward Blyth.", iucn: "LC" },
  "tawpip1": { extract: "The tawny pipit (Anthus campestris) is a medium-large passerine bird which breeds in much of the central Palearctic from northwest Africa and Portugal to Central Siberia and on to Inner Mongolia. It is a migrant moving in winter to tropical Africa and the Indian subcontinent.", iucn: "LC" },
  "trepip": { extract: "The tree pipit (Anthus trivialis) is a small passerine bird that breeds throughout most of Europe and the Palearctic as far east as the East Siberian Mountains. It is a long-distance migrant, migrating in winter to Africa and southern Asia. The scientific name is from Latin: anthus is the name of a small bird of grasslands, and the specific trivialis means \"common\". The breeding habitat is open woodland and scrub. The nest is placed on the ground and usually 4–6 eggs are laid. This species is insectivorous like its relatives, but will also eat seeds.", iucn: "LC" },
  "olbpip": { extract: "The olive-backed pipit (Anthus hodgsoni) is a small passerine bird of the pipit (Anthus) genus, which breeds across southern, north central and eastern Asia, as well as in the north-eastern European Russia. It is a long-distance migrant moving in winter to southern Asia and Indonesia. Sometimes it is also called Indian pipit or Hodgson's pipit, as well as tree pipit owing to its resemblance with the tree pipit. However, its back is more olive-toned and less streaked than that species, and its head pattern is different with a better-marked supercilium. The genus name Anthus is from Latin and is the name for a small bird of grasslands. The specific hodgsoni commemorates English diplomat and collector Brian Houghton Hodgson.", iucn: "LC" },
  "retpip": { extract: "The red-throated pipit (Anthus cervinus) is a small passerine bird, which breeds in the far north of Europe and the Palearctic, with a foothold in northern Alaska. It is a long-distance migrant, wintering to Africa and South-East Asia and western Alaska in North America. It is vagrant to Western Europe.", iucn: "LC" },
  "comros": { extract: "The common rosefinch (Carpodacus erythrinus) or scarlet rosefinch is the most widespread and common rosefinch of Asia and Europe.", iucn: "LC" },
  "crebun1": { extract: "The crested bunting (Emberiza lathami) is a species of bird in the family Emberizidae. It is sparrow sized with males having rufous wings and tail on a black body and females being less contrastingly coloured in dull brown. Both males and females have the distinctive crest. The species was formerly placed in an monotypic genus Melophus on account of its crest, unique among the buntings. The species has a wide but scattered distribution in Asia. They are found in mostly open and dry habitats over a range of altitudes. Populations in the higher elevations of the Himalayas show seasonal altitudinal movements. They are more gregarious in winter.", iucn: "LC" },
  "blhbun1": { extract: "The black-headed bunting (Emberiza melanocephala) is a passerine bird in the bunting family Emberizidae. It breeds in south-east Europe east to Iran and migrates in winter mainly to India, with some individuals moving further into south-east Asia. Like others in its family, it is found in open grassland habitats where they fly in flocks in search of grains and seed. Adult males are well marked with yellow underparts, chestnut back and a black head. Adult females in breeding plumage look like duller males. In other plumages, they can be hard to separate from the closely related red-headed bunting and natural hybridization occurs between the two species in the zone of overlap of their breeding ranges in northern Iran.", iucn: "LC" },
  "rehbun1": { extract: "The red-headed bunting (Emberiza bruniceps) is a passerine bird in the bunting family Emberizidae. It breeds in central Asia, including Afghanistan, Iran, Kazakhstan, Kyrgyzstan, Mongolia; Russia (European Russia, Central Asian Russia), Tajikistan, Turkmenistan, Uzbekistan and China. It is migratory, wintering in India and Bangladesh. Its status in western Europe, where it is a vagrant, has been confused by escapes, especially as this species has been more commonly recorded than the closely related black-headed bunting, despite the latter having a more westerly breeding range. Reports in Britain have declined dramatically over recent years, coinciding with the decline in some Emberizidae species from the impact of illegal trade. An individual found on Shetland in 2010 was deemed to be wild in origin. The red-headed bunting breeds in open scrubby areas including agricultural land.", iucn: "LC" },
  "chebun2": { extract: "The buntings are a group of Old World passerine birds forming the genus Emberiza, the only genus in the family Emberizidae. The family contains 44 species. They are seed-eating birds with stubby, conical bills that inhabit open and half-open habitats, including deserts, stony drylands, shrubland, savanna, and open taiga forests.", iucn: "" },
  "chbbun1": { extract: "The buntings are a group of Old World passerine birds forming the genus Emberiza, the only genus in the family Emberizidae. The family contains 44 species. They are seed-eating birds with stubby, conical bills that inhabit open and half-open habitats, including deserts, stony drylands, shrubland, savanna, and open taiga forests.", iucn: "" },
  "gyhbun1": { extract: "The grey-necked bunting (Emberiza buchanani), sometimes referred to as grey-hooded bunting (a name also in use for chestnut-eared bunting) is a species of bird in the family Emberizidae. It breeds along a wide distribution range from the Caspian Sea to the Altai Mountains in Central Asia and winters in parts of Southern Asia. Like other buntings it is found in small flocks.", iucn: "LC" },
  "ortbun1": { extract: "The ortolan (Emberiza hortulana), also called ortolan bunting, is a Eurasian bird in the bunting family Emberizidae, a passerine family now separated by most modern scholars from the finches, Fringillidae. The genus name Emberiza is from Alemannic German Embritz, a bunting. The specific name hortulana is from the Italian name for this bird, ortolana. The English ortolan is derived from Middle French hortolan, \"gardener\". The ortolan is served in French cuisine, typically cooked and eaten whole. Traditionally, diners cover their heads with their napkin or a towel while eating the delicacy. The ortolan was so widely eaten that its French populations had dropped dangerously low by the 1990s. French laws protecting the bird, and an EU-wide prohibition against killing or capturing it, have had little effect on the ortolan's numbers.", iucn: "LC" },
  "houbun2": { extract: "The striolated bunting (Emberiza striolata) is a passerine bird in the bunting family Emberizidae, a group now separated by most modern authors from the finches, Fringillidae.", iucn: "LC" },
  "yebbun": { extract: "The yellow-breasted bunting (Emberiza aureola) is a passerine bird in the bunting family Emberizidae that is found across the Boreal and East Palearctic. The genus name Emberiza is from Old German Embritz, a bunting. The specific aureola is Latin for \"golden\". The bird's call is a distinctive zick, and the song is a clear tru-tru, tri-tri. Until 2004, the International Union for Conservation of Nature considered the yellow-breasted bunting to be a species of least concern. Since 2004, it has been gradually upgraded to a status of Critically Endangered due to rapid drops in population sizes. It is subject to heavy hunting pressure in China, through which most specimens pass during migration.", iucn: "CR" },
  "litbun": { extract: "The little bunting (Emberiza pusilla) is a passerine bird belonging to the bunting family (Emberizidae).", iucn: "LC" },
};

